SELECT 'moj-all-verified-judgments-review-002-chunk-147' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"723b5821-cc32-50e4-b218-79e86ac8b64e","document_type":"judgment","category":"judicial","subcategory":"general","title":"مطالبة برد مسروق -اشتراك يف سرقة من منزل -إقرار -عدم قبول الرجوع عن اإلقرار بحق اآلدمي -قبول قول املدعي مع ميينه -ثبوت الدعوى -احلكم على املتهمن رغم إقرار األول بعدم اشتراك الثاني معه يف السرقة ألن له إقرار سابق -القضاء بالقيمة األولى يف التحقيق دون ما زاد عنها يف االدعاء أمام المحكمة .","document_number":"34184985","case_number":"32251625","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/10","year":"1434","subject":"مطالبة برد مسروق -اشتراك يف سرقة من منزل -إقرار -عدم قبول الرجوع عن اإلقرار بحق اآلدمي -قبول قول املدعي مع ميينه -ثبوت الدعوى -احلكم على املتهمن رغم إقرار األول بعدم اشتراك الثاني معه يف السرقة ألن له إقرار سابق -القضاء بالقيمة األولى يف التحقيق دون ما زاد عنها يف االدعاء أمام المحكمة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/4/10 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34184985 :‬‬\n                    ‫َر ْق ُم الدعوى‪32251625:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34227940‬تاريخه‪1434/6/3:‬هـ‬\n\n\n‫مطالبــة بــرد مســروق ‪ -‬اشــتراك يف ســرقة مــن منــزل ‪ -‬إقــرار ‪ -‬عــدم‬\n‫قبــول الرجــوع عــن اإلقــرار بحــق اآلدمــي ‪ -‬قبــول قــول املدعــي مــع ميينــه‬\n‫‪ -‬ثبــوت الدعــوى ‪ -‬احلكــم علــى املتهمــن رغم إقرار األول بعدم اشــتراك‬\n‫الثانــي معــه يف الســرقة ألن لــه إقــرار ســابق ‪ -‬القضــاء بالقيمــة األولــى‬\n                 ‫يف التحقيــق دون مــا زاد عنهــا يف االدعــاء أمــام احملكمــة ‪.‬‬\n\n\n\n\n                             ‫قاعدة‪ :‬اليمني تشرع يف جانب أقوى املتداعيني‪.‬‬\n\n\n\n\n‫ادعــت املدعيــة بــأن املدعــى عليهمــا اشــتركا يف ســرقة أطقــم ذهــب‬\n‫وأجهــزة إلكترونيــة مــن منزلهــا؛ وطلبــت إلزامهمــا بتســليمها قيمة باقي‬\n‫املســروقات التــي لــم يتــم اســتعادتها منهمــا ‪ -‬أقــر املدعــى عليــه األول‬\n‫بالســرقة ودفــع بأنــه لــم يتصــرف يف املســروقات بــل اســتعادتها اجلهــات‬\n‫األمنيــة منــه وســلمتها للمدعيــة ســوى جــزء مــن الذهــب باعــه واســتعد‬\n‫بتســليم املدعيــة نفــس املبلــغ الــذي باعــه بــه وأمــا املدعــى عليــه الثانــي‬\n‫فقــد أنكــر دعــوى املدعيــة جتاهــه جملــة وتفصيــا إال أن لــه إقــرارا‬\n‫مصدقــا شــرعا بالســرقة ‪ -‬مــن املقــرر شــرعا أن املــرء مؤاخــذ بإقــراره‬\n‫وأن اليمــن تشــرع يف جانــب أقــوى املتداعيــن ‪ -‬وألن جانــب املدعيــة‬\n\n                                                                                       ‫‪112‬‬\n\f      ‫تقــوى بإقــرار املدعــى عليهمــا بالســرقة فيقبــل قولهــا فيمــا يتعلــق بقيمــة‬\n      ‫املســروقات باعتبــار أقــل قيمــة قدرتهــا للمســروقات ‪ -‬قــررت احملكمــة‬\n      ‫توجيــه اليمــن إلــى املدعيــة علــى صحــة دعواهــا فأدتهــا طبــق مــا طلــب‬\n      ‫منهــا ‪ -‬قضــت احملكمــة بإلــزام املدعــى عليهمــا بتســليم املدعيــة قيمــة‬\n      ‫املســروقات بعــد خصــم قيمــة مــا أعيــد إليهــا منهــا ‪ -‬عارضــت املدعيــة‬\n      ‫واملدعــى عليهمــا علــى احلكــم ‪ -‬قــررت محكمــة االســتئناف املوافقــة‬\n                                                                        ‫علــى احلكــم‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬رئيــس احملكمــة العامــة مبكــة‬\n      ‫املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة مبكــة املكرمــة برقــم ‪ 32251625‬وتاريــخ ‪1432/06/27‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 32786407‬وتاريــخ ‪1432/6/27‬ه ـ حضــرت‬\n      ‫‪ ......‬ســعودية اجلنســية مبوجــب الســجل املدنــي رقــم ( ) وادعــت علــى‬\n      ‫احلاضريــن معهــا يف مجلــس احلكــم ‪ .....‬اجلنســية مبوجــب اإلقامــة رقــم‬\n      ‫(اجلنســية مبوجــب البطاقــة البديلــة رقــم (‪ )513‬يرافقهــا العســكري‬\n      ‫قائلــة يف تقريــر دعواهــا ان املدعــى عليهمــا دخلــوا منزلــي وســرقوا‬\n      ‫ذهبــي املكــون مــن أربعــة وثالثــن بنجــر عيــار ‪ 21‬دقــة الدركتــر بناجــر‬\n      ‫عــدد واحــد وعشــرين حبــه عيــار ‪ 21‬وبناجــر ابــو منشــار عشــر حبــات‬\n      ‫عيــار ‪ 21‬وبناجــر دقــه عاديــه ســت حبــات وطقــم ذهــب اشــتريته مببلــغ‬\n      ‫ســبعة عشــر الــف وثمامنائــة وخمســة وســتني ريــال وطقــم ذهــب مببلــغ‬\n      ‫ســبعة االف وأربعمائــة ريــال وطقــم املــاس مببلــغ احــدى عشــر الــف‬\n      ‫ريــال وســاعة املــاس مببلــغ ثمانيــة آالف ريــال وطقمــن مزنــط احدهمــا‬\n‫‪113‬‬\n\f‫اشــتريته بأربعــة االف ريــال واآلخــر مببلــغ ثالثــة االف ريــال وخمســة‬\n‫أســاور عريضــة وتســعة أطقــم ذهــب هدايــا فــرح وسالســل صغيــره ذهــب‬\n‫عددهــا واحــد وعشــرين سلســله وخمســة وعشــرون خامتــا مــن الذهــب‬\n‫ومبلــغ نقــدي قــدره عشــرون الــف ريــال وعــدد اثنــن البتــوب واثنــن‬\n‫رســيفر وكمــرة فيديــو ديجتــال وطقــم يخــص الشــغالة التــي تعمــل‬\n‫لــدي لــذا اطلــب احلكــم علــى املدعــى عليهمــا بإعــادة املســروقات التــي‬\n‫أخذوهــا مــن منزلــي هكــذا ادعــت وبعــرض ذلــك علــى املدعــى عليهمــا‬\n‫أجــاب كل واحــد منهمــا مبفــرده غيــر صحيــح مــا ذكرتــه املدعيــة مــن‬\n‫ســرقتنا ملنزلهــا فلــم نقــم بســرقة منزلهــا وال غيــره مــن املنــازل هكــذا‬\n‫أجــاب كل واحــد مبفــرده ويف جلســة اخــرى حضــرت املدعيــة واملدعــى‬\n‫عليهمــا وبســؤال املدعيــة هــل لديهــا بينــه قالــت لــدي اعترافــات املدعــى‬\n‫عليهمــا التــي ســبق تدوينهــا قضيــة ســرقتهما اطلــب الرجــوع اليهــا ثــم‬\n‫جــرى اطالعــي علــى اقــراري املدعــى عليهمــا املصدقــن شــرعا وجــرى‬\n‫تدوينهمــا بنصهمــا يف ضبــط القضيــة ويف جلســة اخــرى لــدى أنــا ‪.......‬‬\n‫القاضــي باحملكمــة العامــة مبكــة املكرمــة والقائــم بعمــل مســاعد‬\n‫رئيــس احملكمــة مبوجــب خطــاب فضيلــة رئيــس احملكمــة رقــم‬\n‫‪ 33619201‬يف ‪1433/4/3‬ه ـ حضــرت املدعيــة كمــا حضــر املدعــي‬\n‫عليهمــا يرافقهمــا اجلنــدي‪ /‬رقمــه ‪ 247‬وجــرى االطالع على اخلطاب رقم‬\n‫‪ 70722‬يف ‪1431/7/11‬ه ـ فوجدتــه صــادر مــن جلنــة التحقيــق يف قضايا‬\n‫ســرقات املنــازل ويتضمــن انــه مت القبــض علــى املدعــي عليهمــا وعثــر‬\n‫بحــوزة‪ /‬علــى محفظــة بهــا مبلــغ الــف وثمامنائــة وثمانــن ريــاال وبتفتيــش‬\n‫منزلهمــا عثــر علــى مبلــغ ثمانــن الــف ريــال أ‪-‬ه ـ كمــا جــرى االطــاع‬\n‫علــى اخلطــاب رقــم ‪14/407269‬ع يف ‪1431/7/16‬ه ـ فوجــد انــه صــادر‬\n\n\n                                                                                   ‫‪114‬‬\n\f      ‫مــن رئيــس جلنــة التحقيــق يف قضايــا ســرقات املنــازل واملتضمــن انــه مت‬\n      ‫بيــع املضبوطــات املتبقيــة عــن طريــق شــيخ طائفــة داللــي حــراج اخلــردة‬\n      ‫مببلــغ خمســه آالف وســتمائة وثمانيــة ريــاالت وجــرى ســؤال املدعيــة‬\n      ‫هــل لديهــا فواتيــر باألشــياء التــي تدعيهــا فقالــت ســأبحث عــن ذلــك‬\n      ‫وجــرت الكتابــة للشــرطة إليضــاح األعيــان املســروقة لديهــم وايضــاح‬\n      ‫هــل يوجــد بيــان لديهــم يوضــح أســماء اصحابهــا وذلــك مبوجــب خطابنــا‬\n      ‫رقــم ‪ 33761460‬يف ‪1433/4/21‬ه وذلــك بخطابنــا رقــم ‪33761460‬‬\n      ‫يف ‪1433/4/21‬ه ـ فــوردت اإلفــادة مــن مديــر مركــز شــرطة التنعيــم‬\n      ‫باخلطــاب رقــم ‪ 143784‬يف ‪1433/4/27‬ه ـ واملقيــد باحملكمــة برقــم‬\n      ‫‪ 33817654‬يف ‪1433/5/1‬ه ـ واملتضمــن بــان جميــع املضبوطــات‬\n      ‫املوجــودة يف املركــز هــي املبالــغ املاليــة املوضحــة ســابقا وأمــا بالنســبة‬\n      ‫للمضبوطــات األخــرى فجــرى تســليمها ألصحابهــا كمــا هــو موضــح‬\n                                                                    ‫بــأوراق املعاملــة إه ـ‬\n      ‫وجــرى ســؤال املدعيــة عــن تاريــخ الســرقة ووصــف بيتهــا فقالــت أن‬\n      ‫الســرقة متــت عــام ‪1431‬ه ـ أمــا وصــف بيتهــا فهــو عبــارة عــن شــقه بالــدور‬\n      ‫العلــوي يف العمــارة الواقعــة ‪ .....‬املكونــة مــن دوريــن وبــن الــدور األرضــي‬\n      ‫كيلــون بــاب حديــد وبــاب شــقتي مــن اخلشــب وقــد قــام املدعــى عليهــم‬\n      ‫بكســر البــاب احلديــد الواقــع بــن الدوريــن وبــاب الشــقة اخلشــب وأخــذا‬\n      ‫املســروقات التــي ذكرتهــا يف دعــواي هكــذا قــررت كمــا جــرى‬\n      ‫ســؤالها هــل اســتلمت شــيئ ًا مــن املســروقات ممــا وجــد مــع املدعــى‬\n      ‫عليهمــا عــن طريــق الشــرطة فقالــت نعــم إننــي ذهبــت الــى مراكــز‬\n      ‫شــرطة التنعيــم والعزيزيــة والشــرائع وقــد رأيــت جميــع املضبوطــات‬\n      ‫العينيــة مــع املدعــى عليهمــا مــن أجهــزه وذهــب ووجــدت ثمانــي بناجــر‬\n\n\n‫‪115‬‬\n\f‫وخمــس سالســل وســتة خــوامت وجميعهــا مــن الذهــب ولــم أجــد شــيئا‬\n‫ســواه وقــد اســتلمت هــذا الذهــب هكــذا قــررت وبعــرض ذلــك علــى‬\n‫املدعــى عليهمــا قــال املدعــى عليــه صحيــح اننــي ســرقت شــقة املدعيــة‬\n‫وقــد أخــذت مــن بيتهــا ذهبــا ال اذكــر نوعــه وال وصفــه وإمنــا الــذي‬\n‫اذكــره أننــي بعــت جــزء منــه بعشــرة آالف ريــال وباقــي الذهــب لــم‬\n‫أتصــرف بــه وقبضــت علــي الشــرطة ووجدتــه يف بيتــي ومت عرضــه مــع‬\n‫بقيــة املضبوطــات معــي علــى أصحــاب البيــوت املســروقة واســتلمت‬\n‫املدعيــة حقهــا مــن الذهــب املوجــود هــذا مــا لــدي وأنــا اقــر بــه وملتــزم‬\n‫بدفــع مبلــغ عشــرة آالف ريــال لهــا قيمــة الذهــب الــذي بعتــه ممــا ســرقته‬\n‫مــن بيتهــا وأمــا زميلــي فلــم يشــترك معــي يف هــذه الســرقة هكــذا قــرر‬\n‫وقــال املدعــى عليــه انــا لــم اذهــب لبيــت املدعيــة ولــم اســرق منــه شــيئا‬\n‫هكــذا قــرر وبســؤال املدعيــة عــن قيمــة املســروقات عــدا مــا اســتلمته‬\n‫منهــا فقالــت انهــا تتجــاوز ثالثمائــة الــف ريــال وانــا اطالــب بهــذا املبلــغ‬\n‫هكــذا قــررت وبعــرض ذلــك علــى املدعــي عليهمــا قــال املدعــي عليــه‬\n‫األول اننــي ســرقت مــن بيــت املدعيــة ذهــب واننــي بعــت جــزء منــه بعشــرة‬\n‫آالف ريــال والباقــي اســتلمته املدعيــة ولــذا فانــا لــن ادفــع لهــا ســوى هــذا‬\n‫املبلــغ الــذي بعــت بــه الذهــب عشــرة آالف ريــال فقــط وانــا الــذي ســرقت‬\n‫بيتهــا وحــدي ولــم يكــن معــي‪ /‬أو غيــره هكــذا قــرر وبعــرض ذلــك علــى‬\n‫املدعيــة قالــت غيــر صحيــح مــا ذكــره املدعــي عليــه فــإن قيمــة الذهــب‬\n‫الــذي ســرقه مــن بيتــي ولــم اســتلمه يزيــد عــن ثالثمائــة الــف ريــال وانــا‬\n‫اطلــب الزامهمــا بدفــع ثالثمائــة الــف ريــال هكــذا قــررت وقــال املدعــي‬\n‫عليــه الثانــي أنــا لــم أســرق مــن بيتهــا شــيئا هكــذا قــرر وجــرى ســؤال‬\n‫املدعيــة هــل لديهــا بينــه علــى هــذه املســروقات التــي تدعيهــا ممــا لــم‬\n\n\n                                                                                        ‫‪116‬‬\n\f      ‫تســتلمه فقالــت نعــم فأبــرزت ‪ /1‬فاتــورة محــل لبيــع الذهــب برقــم‬\n      ‫‪ 259551‬بشــراء ثمانيــة بناجــر بثالثــة آالف ريــال ‪ /2‬فاتــورة شــركة ‪....‬‬\n      ‫لصناعــة املجوهــرات برقــم ‪ 10/3954‬بشــراء بنجرتــن بألــف وخمســة‬\n      ‫وســتني ريــال ‪ /3‬فاتــورة محــل ‪ ....‬لبيــع الذهــب برقــم ‪ 6249‬بشــراء أربــع‬\n      ‫بناجــر بخمســة آالف ومائتــن وســتة وســبعني ريــال ‪ /4‬فاتــورة مــن محــل‬\n      ‫‪ ....‬بشــراء جوالــن مــن نــوع ‪ ....‬بألــف وخمســمائة وأربعــن ريــاال ‪/5‬‬\n      ‫فاتــورة مــن محــل مجوهــرات ‪ ....‬برقــم ‪ 394966‬بشــراء أســاور ايطاليــة‬\n      ‫الصنــع مببلــغ ســبعمائة وســتني ريــاال ‪ .‬كمــا أبــرزت كشــف حســابها‬\n      ‫املصــريف الصــادر مــن مصــرف ‪ ....‬وتتضمــن مشــتريات املدعيــة مــن‬\n      ‫الذهب على النحو االتي ‪ /1 :‬مجوهرات ‪ 7600 ....‬ريال ‪ /2‬مجوهرات‬\n      ‫‪ 2326 ....‬ريــال ‪ /3‬مجوهــرات ‪ 3824 ....‬ريــال ‪ /4‬مجوهــرات ‪4273 ....‬‬\n      ‫ريــال ‪ /5‬مجوهــرات ‪ 3500 ....‬ريــال ‪ /6‬مجوهــرات ‪ 790 ....‬ريــال ‪/7‬‬\n      ‫مجوهــرات ‪ 1350 ....‬ريــال ‪ /8‬مجوهــرات ‪ 1100 ....‬ريــال ‪ /9‬مجوهرات‬\n      ‫‪150 ....‬ريــال ‪ /10‬مجوهــرات ‪ 225 ....‬ريــال ‪ /11‬مجوهــرات ‪5200 ....‬‬\n      ‫ريــال ‪ /12‬مجوهــرات ‪ 2700 ....‬ريــال ‪ /13‬مجوهــرات ‪6800 ....‬‬\n      ‫ريــال‪ /14‬مجوهــرات ‪ 6860 ....‬ريــال ‪ /15‬مجوهــرات ‪ 2940 ....‬ريــال‬\n      ‫‪ /16‬مجوهــرات ‪ 6000 ....‬ريــال ‪ /17‬مجوهــرات ‪ 3124 ....‬ريــال ‪/18‬‬\n      ‫مجوهــرات ‪ 2873 ....‬ريــال ‪ /19‬مجوهــرات ‪ 3300 ....‬ريــال ‪/20‬‬\n      ‫مجوهــرات ‪ 7950 ....‬ريــال ‪ /21‬مجوهــرات ‪ 3000 ....‬ريــال ‪/22‬‬\n      ‫مجوهــرات ‪ 1415 ....‬ريــال ‪ /23‬مجوهــرات ‪ 3734 ....‬ريــال ‪/24‬‬\n      ‫مجوهرات ‪5600 ....‬ريال ‪ /25‬مجوهرات ‪ 914 ....‬ريال ‪ /26‬مجوهرات‬\n      ‫‪ 6700 ....‬ريــال ‪ /27‬مجوهــرات ‪ 2326 ....‬ريــال ‪ /28‬مجوهــرات ‪....‬‬\n      ‫‪1110060‬ريــال ‪ /29‬مجوهــرات ‪ ....‬للذهــب ‪ 2281‬ريال ‪ /30‬مجوهرات‬\n\n\n‫‪117‬‬\n\f‫‪9000 ....‬ريــال ‪ /31‬مجوهــرات ‪ 119033 ....‬ريــال ‪ /32‬مجوهــرات ‪....‬‬\n‫‪ 1000‬ريــال ‪ /33‬مجوهــرات ‪ 7540 ....‬ريــال ‪ /34‬مجوهــرات ‪2300 ....‬‬\n‫ريــال ‪ /35‬مجوهــرات ‪ 2121 ....‬ريــال ‪ /36‬مجوهــرات ‪ 5000 ....‬ريــال‬\n‫‪ /37‬مجوهــرات ‪ 2150 ....‬ريــال ‪ /38‬مجوهــرات ‪ ....‬للذهــب‬\n‫‪2000‬ريــال‪ /39‬مجوهــرات ‪ 1450 ....‬ريــال ‪ /40‬مجوهــرات ‪6500 ....‬‬\n‫ريــال ‪ /41‬مجوهــرات ‪ 4000 ....‬ريــال ‪ /42‬مجوهــرات ‪ 3351 ....‬ريــال‬\n‫‪ /43‬مجوهــرات ‪ 15000 ....‬ريــال ‪ /44‬مجوهــرات ‪ 4120 ....‬ريــال ‪/45‬‬\n‫مجوهــرات ‪ 4125 ....‬ريــال ‪ /46‬مجوهــرات ‪ 7000 ....‬ريــال ‪/47‬‬\n‫مجوهــرات ‪ 950 ....‬ريــال ‪ /48‬مجوهــرات ‪ 1650 ....‬ريــال ‪/49‬‬\n‫مجوهــرات ‪ 2900 ....‬ريــال ‪ /50‬مجوهــرات ‪ 9840 ....‬ريــال ‪/51‬‬\n‫مجوهــرات ‪ 3300 ....‬ريــال ‪ /52‬مجوهــرات ‪ 2422 ....‬ريــال ‪/53‬‬\n‫مجوهــرات ‪ 2798 ....‬ريــال ‪ /54‬مجوهــرات ‪ 2175 ....‬ريــال ‪/55‬‬\n‫مجوهــرات ‪1674 ....‬ريــال ‪ /56‬مجوهــرات ‪ 1356 ....‬ريــال ‪/57‬‬\n‫مجوهــرات ‪ 5545 ....‬ريــال ‪ /58‬مجوهــرات ‪ 20800 ....‬ريــال ‪/59‬‬\n‫مجوهــرات ‪ 310 ....‬ريــال ‪ /60‬مجوهــرات ‪ 850 ....‬ريــال ‪ /61‬مجوهرات‬\n‫‪ 950 ....‬ريــال ‪ /62‬مجوهــرات ‪ 3821 ....‬ريــال ‪ .‬ومجمــوع املبالــغ مائتــان‬\n‫وثمانيــة وأربعــون الفــا وواحــد وثالثــون ريــاال وبســؤال املدعيــة هــل لديهــا‬\n‫فواتيــر ســوى مــا قدمتــه فقالــت هنــاك أشــياء أخــرى ســرقت مــن منزلــي‬\n‫غيــر هــذا الذهــب وهــو جهــازي كمبيوتــر محمــول وآلة تصويــر وجهازي‬\n‫اســتقبال وســاعة املــاس وذهــب آخــر غيــر هــذا الذهــب الــذي أحضــرت‬\n‫فواتيــره وثمنــه وليــس لــدي فواتيــر بهــذه األشــياء هكــذا قــررت وبعرض‬\n‫ذلــك علــى املدعــى عليهمــا قــال املدعــى عليــه األول أنــا لــم أخــذ ســوى مــا‬\n‫ســبق أن ذكرتــه يف إجابتــي وأنــا مســتعد بدفــع عشــرة آالف ريــال لهــا‬\n\n\n                                                                                        ‫‪118‬‬\n\f      ‫فقــط هكــذا قــرر وقــال املدعــى عليــه الثانــي أنــا لــم اســرق مــن منزلهــا‬\n      ‫شــيئا ولــن ادفــع لهــا شــيئا هكــذا قــرر وبســؤال املدعيــة هــل لديهــا زيــادة‬\n      ‫بينــه فقالــت ليــس لــدي ســوى مــا قدمتــه لكــم هكــذا قــررت ثــم جــرى‬\n      ‫اطالعــي علــى بــاغ املدعيــة بالســرقة املــدون علــى ملــف التحقيــق املرفــق‬\n      ‫باملعاملــة لفــه رقــم ‪ 165‬دوســيه رقــم (‪ )2‬فوجــدت انهــا قــد ذكــرت ان‬\n      ‫قيمــة املســروقات حوالــي مائتــي الــف ريــال فقــط وبعــرض ذلــك علــى‬\n      ‫املدعيــة قالــت نعــم انــا قلــت ذلــك ولكــن كان املبلــغ تقريبيــا والصحيــح‬\n      ‫ان املســروقات كانــت بثالثمائــة الــف ريــال هكــذا قــررت فســألت‬\n      ‫املدعــى عليهمــا عــن املــكان الــذي وجــد فيــه الذهــب املــدون مــن املدعية‬\n      ‫الــذي تعرفــت عليــه لــدى الشــرطة واســتلمته فقــال املدعــى عليــه األول‬\n      ‫ان الشــرطة عثــروا عليهــا عنــدي يف البيــت هكــذا قــرر ثم جــرى الرجوع‬\n      ‫الــى ملــف التحقيــق املرفــق باملعاملــة لفــه رقــم ‪ 165‬دوســيه رقــم (‪)2‬‬\n      ‫فوجــد هــذا نصــه ( بحضورنــا نحــن املوقعــن أدنــاه وبتاريخــه أعــاه ويف‬\n      ‫متــام الســاعة احلاديــة عشــر ظهــرا ويف مقــر جلنــة التحقيــق يف قضايــا‬\n      ‫ســرقات املنــازل مبركــز شــرطة الكعكيــة جــرى عــرض املضبوطــات‬\n      ‫التــي مت العثــور عليهــا يف منــزل املتهــم األول نيجيــري اجلنســية علــى املــرأة‬\n      ‫‪ .......‬ســعودية اجلنســية والتــي ســبقت وان تقدمــت ببــاغ عــن تعــرض‬\n      ‫منزلهــا للســرقة وعنــد العــرض تعرفــت علــى مجموعــه مــن املضبوطــات‬\n      ‫وهــي كاالتــي‪ /1 .:‬عــدد (‪ )8‬بناجــر ذهــب عليــه خطــوط فضيــه ‪/2‬‬\n      ‫عــدد (‪ )13‬خــامت ذهــب متعــددة األشــكال ‪ /3‬عــدد (‪ )2‬زوج اقــراط‬\n      ‫ذهــب ‪ /4‬عــدد (‪ )1‬ســوار يــد ذهــب ‪ /5‬عــدد (‪ )1‬سلســله جــوال ذهــب‬\n      ‫ابيــض ‪ /6‬عــدد (‪ )9‬اقــراط فرديــة ذهــب ‪ /7‬عــدد (‪ )4‬تعليقــات ذهــب‬\n      ‫‪ /8‬عــدد (‪ )1‬تعليقــه اكسســوار اللــون فضــي ‪ .‬كمــا جــرى عــرض‬\n\n\n‫‪119‬‬\n\f‫املضبوطــات التــي مت العثــور عليهــا مبنــزل املتهــم الثاني نيجيري اجلنســية‬\n‫واســتطاعت املــراءة املذكــورة التعــرف علــى بعضهــا وهــي كاالتــي‪.:‬‬\n‫‪ /1‬عــدد واحــد طقــم اكسســوار اللــون فضــي مــع فصــوص ( تعليقــه ‪+‬‬\n‫زوج اقــراط ‪ +‬ســوار يــد ) ‪ /2‬عــدد (‪ )3‬ازواج اقــراط متعــددة االشــكال‬\n‫‪ /3‬عــدد (‪ )3‬تعليقــات ذهــب متعــددة االشــكال ‪ /4‬عــدد (‪ )2‬خــوامت يــد‬\n‫ذهــب اللــون فضــي ‪ /5‬عــدد واحــد خــامت يــد ذهــب ‪ .‬وحفظــا للواقــع مت‬\n‫اعــداد هــذا احملضــر وعليــه جــرى التوقيــع ‪ .‬جنــدي اول توقيــع شــقيقها‬\n‫‪ ........‬توقيــع إ‪-‬ه ـ وبعــرض ذلــك علــى املدعيــة قالــت صحيــح انــا اســتلمت‬\n‫جميــع هــذه االشــياء هكــذا قــررت فســألت املدعيــة عــن ثمــن مــا‬\n‫اســتلمته مــن املســروقات فقالــت أن ثمنهــا هــو ثمانيــة عشــرة الفــا‬\n‫وثمامنائــة وســتني ريــال ولــذا وبــراءة لذمتــي فإنــي اقدرهــا بعشــرين الــف‬\n‫ريــال هكــذا قــررت فســألت املدعيــة عمــا جــاء يف بالغهــا االول مــن ان‬\n‫قيمــة املســروقات مائتــي الــف ريــال تقريبــا فقالــت أننــي قلــت هــذا املبلــغ‬\n‫علــى التقريــب واال فالصحيــح أن ثمنهــا يزيــد عــن مائتــن وخمســن الــف‬\n‫ريــال باإلضافــة الــى أنــه يوجــد ذهــب آخــر لــم أذكــره يف البــاغ األول‬\n‫ولــم اتعــرض لتقديــره وهــو مببلــغ مائــة الــف ريــال وبــذا يكــون مجمــوع‬\n‫ثمــن مــا ســرق مــن بيتــي هــو مبلــغ وقــدره ثالثمائــة وخمســون الــف ريــال‬\n‫وأنــا أطالــب بهــذا املبلــغ هكــذا قــررت وعليــه وألنــه جانــب املدعيــة‬\n‫تقــوى بإقــرار املدعــى عليــه ووجــود بعــض املســروقات ببيــت املدعــى‬\n‫عليهمــا كمــا جــاء يف محضــر املعاينــة وألن املدعيــة ذكــرت يف بــاغ‬\n‫الســرقة االول أن املســروقات تقــارب مــن مائتــي الــف ريــال فقــد قــررت‬\n‫حتليفهــا علــى ذلــك وعلــى أن ثمــن مــا اســتلمته مــن ذهــب هــو مببلــغ‬\n‫عشــرين الــف ريــال فاســتعدت وحلفــت قائلــة واهلل العظيــم أن ثمــن‬\n\n\n                                                                                       ‫‪120‬‬\n\f      ‫املســروقات التــي ســرقها املدعــى عليهمــا مــن بيتــي هــو بأكثــر مــن‬\n      ‫مائتــي الــف ريــال وأنــه يف احلقيقــة ثالثمائــة وخمســن الــف ريــال وأن‬\n      ‫ثمــن مــا اســتلمته عــن طريــق الشــرطة هــو ال يزيــد عــن عشــرين الــف‬\n      ‫ريــال هكــذا حلفــت فبنــاء علــى مــا تقــدم مــن الدعــوى واالجابــة وألن‬\n      ‫املدعــى عليــه أقــر بالســرقة مــن بيــت املدعيــة بينمــا أنكــر ذلــك املدعــى‬\n      ‫عليــه الثانــي وبعــد االطــاع علــى إقــرارات املدعــى عليهمــا املصدقــة‬\n      ‫شــرعا وبعــد االطــاع علــى بــاغ املدعيــة االول بالشــرطة املتضمــن أن‬\n      ‫ثمــن املســروقات مائتــا الــف ريــال تقريبــا وبعــد االطــاع علــى محضــر‬\n      ‫املعاينــة املتضمــن وجــود بعــض املســروقات يف منــزل املدعــى عليهمــا‬\n      ‫وقــد تعرفــت عليهــا املدعيــة وقــد قــررت املدعيــة أن ثمــن مــا اســتلمته ال‬\n      ‫يزيــد عــن عشــرين الــف ريــال وألن الراجــح مــن أقــوال أهــل العلــم أن‬\n      ‫اليمــن يف جانــب اقــوى املتداعــن وقــد تقــوى جانــب املدعيــة باإلقراريــن‬\n      ‫املصدقــن شــرعا وإقــرار املدعــى عليــه األول يف هــذه القضيــة ووجــود‬\n      ‫بعــض املســروقات يف منــزل املدعــى عليهمــا وألن املدعيــة حلفــت اليمــن‬\n      ‫علــى أن ثمــن املســروقات يزيــد علــى مائتــي الــف ريــال وأن ثمــن مــا‬\n      ‫اســتلمته منهــا ال يزيــد عــن عشــرين الــف ريــال وألن املدعيــة مؤاخــذة مبــا‬\n      ‫جــاء يف اقرارهــا يف بــاغ الســرقة االول لذلــك كلــه فقــد حكمــت علــى‬\n      ‫املدعــى عليهمــا بــأن يدفعــا للمدعيــة مائــة وثمانــن الــف ريــال وعــدم‬\n      ‫اســتحقاق املدعيــة لباقــي املبلــغ الــذي تدعيــه وبعــرض احلكــم علــى‬\n      ‫الطرفــن قــرروا جميعــا عــدم القناعــة وطلبوا رفعه حملكمة االســتئناف‬\n      ‫بعــد تقــدمي الئحــة اعتراضيــة فأفهمتهــم مبراجعــة احملكمــة خــال‬\n      ‫عشــرة أيــام الســتالم صــورة الصــك وتقــدمي الالئحــة االعتراضيــة خــال‬\n      ‫ثالثــن يومــا مــدة االعتــراض فــإذا تأخــروا ســقط حقهــم يف طلــب‬\n\n\n‫‪121‬‬\n\f‫االســتئناف واكتســب احلكــم القطعيــة‪ .‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل‬\n   ‫على نبينا محمد وعلى آله وصحبه وسلم‪ .‬حرر يف ‪1434/04/03‬هـ‪.‬‬\n\n\n\n‫•صــدق احلكــم مــن محكمــة االســتئناف برقــم ‪ 34227940‬وتاريــخ‬\n                                                  ‫‪1434/6/3‬هـ‪.‬‬\n\n\n\n\n                                                                          ‫‪122‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":112,"source_page_end":122,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"97311d57b7d1b65a35154cc8239b53cd38ceea16eb5e6f2e37595b51a18a2fb5","normalized_text_hash":"5e8f222f79046c4d95da20d63908c0e7239b54ae977b3bfefa1155699fb1592e","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p112-34184985"},{"id":"5de70533-bbd8-5650-ba2a-e8a55781465a","document_type":"judgment","category":"judicial","subcategory":"general","title":"مطالبة برد مسروق -اشتراك يف سرقة من منزل -عدم قبول الرجوع عن اإلقرار بحق آلدمي -قبول قول املدعي مع ميينه -حتمل ضمان املسروقات بالتساوي بن املتهمن ما لم يقروا باستفادتهم خاف ذلك -ثبوت الدعوى .","document_number":"347621","case_number":"32391711","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة ببريدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/10","year":"1434","subject":"مطالبة برد مسروق -اشتراك يف سرقة من منزل -عدم قبول الرجوع عن اإلقرار بحق آلدمي -قبول قول املدعي مع ميينه -حتمل ضمان املسروقات بالتساوي بن املتهمن ما لم يقروا باستفادتهم خاف ذلك -ثبوت الدعوى .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"        ‫تاريخه‪1434/1/10 :‬هـ‬\n                        ‫ُ‬               ‫َر ْق ُم َّ‬\n                            ‫الص ِّك‪347621 :‬‬\n                          ‫َر ْق ُم الدعوى‪32391711:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 3451153‬تاريخه‪1434/4/24:‬هـ‬\n\n\n      ‫مطالبــة بــرد مســروق ‪ -‬اشــتراك يف ســرقة مــن منــزل ‪ -‬عــدم قبــول‬\n      ‫الرجــوع عــن اإلقــرار بحــق آلدمــي ‪ -‬قبــول قــول املدعــي مــع ميينــه‬\n      ‫‪ -‬حتمــل ضمــان املســروقات بالتســاوي بــن املتهمــن مــا لــم يقــروا‬\n                             ‫باســتفادتهم خــاف ذلــك ‪ -‬ثبــوت الدعــوى ‪.‬‬\n\n\n\n\n                      ‫‪ -1‬قول النبي صلى اهلل عليه وسلم‪( :‬شاهداك أو ميينه)‪.‬‬\n                                   ‫‪ -2‬اليمني تشرع يف جانب أقوى املتداعيني ‪.‬‬\n                                                          ‫‪ -3‬ال عذر ملن أقر ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي بــأن املدعــى عليــه اشــترك مــع آخــر يف ســرقة أطقــم ذهــب‬\n      ‫وأجهــزة إلكترونيــة مــن منزلــه كمــا قامــا بتكســير األقفــال؛ ولــذا‬\n      ‫فقــد طلــب إلزامــه بتســليم نصــف قيمــة املســروقات ونصــف تكاليــف‬\n      ‫إصــاح األقفــال وتنظيــف املنــزل ‪ -‬أنكــر املدعــى عليــه دعــوى املدعــي‪-‬‬\n      ‫اطلعــت احملكمــة علــى إقــرار املدعــى عليــه باالشــتراك يف الســرقة أمام‬\n      ‫جهــة التحقيــق فوجدتــه مجمــا مــن جهــة بيــان قيمــة املســروقات ‪ -‬مــن‬\n      ‫املقــرر شــرعا أنــه ال عــذر ملــن أقــر وأن اليمــن تشــرع يف جانــب أقــوى‬\n      ‫املتداعيــن‪ -‬وجانــب املدعــي يتقــوى بإقــرار املدعــى عليــه بالســرقة‬\n\n‫‪123‬‬\n\f‫فيقبــل قولــه فيمــا يتعلــق بقيمــة املســروقات ‪ -‬قــررت احملكمــة توجيــه‬\n‫اليمــن إلــى املدعــي علــى صحــة دعــواه فأداهــا طبــق مــا طلــب منــه ‪-‬‬\n‫قضــت احملكمــة بإلــزام املدعــى عليــه بتســليم املدعــي املبلــغ املدعــى‬\n‫بــه والــذي ميثــل نصــف املبلــغ اإلجمالــي‪ -‬عــارض املدعــى عليــه علــى‬\n       ‫احلكــم‪ -‬قــررت محكمــة االســتئناف املصادقــة علــى احلكــم ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد‪ :‬لــدي أنا‬\n‫(‪ )......‬القاضــي يف احملكمــة العامــة ببريــدة وبنــاء علــى املعاملــة املقيــدة‬\n‫لنــا مــن فضيلــة الرئيــس برقــم ‪ 321146076‬وتاريخ‪1432/9/3‬ه ـ‬\n‫واحملالــة برقــم ‪ 32391711‬يف ‪1432/9/3‬ه ـ ففــي هــذا اليــوم الســبت‬\n‫املوافق‪1434/1/10‬ه ـ فتحــت اجللســة األولــى يف متــام الســاعة التاســعة‬\n‫صباحــا وفيهــا حضــر ‪ /‬ســعودي بالســجل املدنــي رقــم الوكيل الشــرعي‬\n‫عــن ‪ /‬مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل بريــدة الثانيــة برقــم‬\n‫‪ 34739‬وتاريــخ ‪1433/6/28‬ه ـ مدعيــا علــى احلاضــر معــه ‪ /‬ســعودي‬\n‫بالســجل املدنــي رقــم قائــا يف دعــواه عليــه إنــه يف آخــر شــهر ربيــع األول‬\n‫ســنة ‪1431‬ه ـ قــام املدعــى عليــه ورفيقــه بالســطو علــى منــزل موكلــي‬\n‫الواقع يف حي ‪ ......‬حالي ًا (‪ .....‬ســابقاً) ببريدة وســرقة أطقم ذهب بقيمة‬\n‫ثالثــة وأربعــن ألــف ريــال وجهــاز كمبيوتــر محمــول نــوع توشــيبا بقيمــة‬\n‫خمســة آالف ريــال وجهــاز جــوال ‪ ....‬بقيمــة ثالثــة آالف ريــال كمــا قامــا‬\n‫بتكســير أقفــال األبــواب الداخليــة والتــي كلــف إصالحهــا تســعمائة‬\n‫وخمســن ريــا ًال مــع أعمــال النظافــة للمنــزل وبلــغ مجمــوع ذلــك مبلغــا‬\n‫وقــدره واحــد وخمســون ألفــا وتســعمائة وخمســون ألــف ريــال ومبــا أن‬\n\n                                                                                      ‫‪124‬‬\n\f      ‫املدعــى عليــه شــريك مــع زميلــه يف هــذه الســرقة ويتحمــل نصــف قيمــة‬\n      ‫هــذه املســروقات مــع اصــاح أقفــال األبــواب وأعمــال النظافــة لــذا أطلــب‬\n      ‫إلــزام املدعــى عليــه بتســليمي نصــف قيمــة املســروقات يف وقــت الســرقة‬\n      ‫وذلــك مبلــغ وقــدره خمســة وعشــرون ألفــا وتســعمائة وخمســة وســبعون‬\n      ‫ريــاال هــذه دعــواي وبعــرض ذلــك علــى املدعــى عليــه فقــال مــا نســبه لــي‬\n      ‫املدعــي وكالــة يف دعــواه جملــة وتفصيــا غيــر صحيــح ولــم أقــم أو‬\n      ‫اشــترك بذلــك هــذه إجابتــي ‪ .‬ومبــا أن املدعــى عليــه أنكــر مــا نســب‬\n      ‫لــه يف الدعــوى واســتنادا لقولــه صلــى اهلل عليــه وســلم‪( :‬شــاهداك أو‬\n      ‫ميينــه) لــذا طلبــت مــن املدعــي وكالــة البينــة علــى صحــة دعــواه فقــال إن‬\n      ‫بينتــي علــى ذلــك هــي اعترافــه بذلــك أمــا احملقــق ســابقا أثنــاء التحقيــق‬\n      ‫وميكنكــم طلــب دفتــر التحقيــق لالطــاع عليــه وبنــاء علــى ذلــك جــرت‬\n      ‫مخاطبتــي عــن طريــق فضيلــة مســاعد رئيــس احملكمــة لســعادة مديــر‬\n      ‫ســجن بريــدة بطلــب تزويــدي بنســخة مــن محاضــر التحقيــق مــع املدعــى‬\n      ‫عليــه موجــب اخلطــاب رقــم ‪ 331143772‬يف ‪1433/ 10/ 14‬ه وقــد‬\n      ‫وردتنــي اإلجابــة عــن ذلــك منــه عــن طريــق فضيلــة رئيس احملكمــة برقم‬\n      ‫‪ 1 / 26/ 8338/9‬يف ‪1433/ 11/ 13‬ه ـ املرفــق بهــا دفتــر محاضــر‬\n      ‫التحقيــق مشــفوع ‪ 196‬وباالطــاع عليــه وجــد يف الصحيفــة األولــى منــه‬\n      ‫مــا نصــه‪( :‬وباســتجواب ‪ /‬عــن ارتكابــه عــدة ســرقات فأجــاب منهــا‬\n      ‫عــن الســؤال الثانــي دخلــت منــزل ‪ /‬بحــي ‪ .....‬وســرقت منــه جهــاز ‪.....‬‬\n      ‫جــوال وجهــاز حاســب آلــي ومجموعــة مجوهــرات وكان برفقتــي زميلــي‬\n      ‫‪ /‬فقــط ال غير‪.‬أ‪.‬ه ـ وبعرضــه علــى املدعــى عليــه فقــال مــا نســب لــي‬\n      ‫بذلــك فقــد بصمــت عليــه واعترفــت بــه أمــام البحــث اجلنائــي مكرهــا‬\n      ‫بذلــك هكــذا أفــاد املدعــى عليــه ومبــا أن الفقهــاء قــد نصــوا علــى أنــه‬\n\n\n‫‪125‬‬\n\f‫تؤخــذ اليمــن يف جانــب أقــوى املتداعيــن ونظــرا ألن املدعــى عليــه لــم‬\n‫يفصــح يف إقــراره عــن قيمــة املســروق لــذا طلبــت مــن املدعــي وكالــة‬\n‫إحضــار موكلــه فأحضــر ‪ /‬ســعودي اجلنســية حامــل الســجل املدنــي رقم‬\n‫وبطلــب اليمــن منــه علــى صحــة دعــواه فقــال واهلل العظيــم إنــه يف آخــر‬\n‫شــهر ربيــع األول عــام ‪1431‬ه ـ قــام رجــان بالســطو علــى منزلــي الواقــع‬\n‫يف ‪ .....‬ســابق ًا وحــي ‪ .....‬حاليـ ًا وكســرا أقفــال األبــواب الداخليــة وســرقا‬\n‫مــن داخــل بيتــي أطقــم ذهــب قيمتهــا وقــت الســرقة بثالثــة وأربعــن ألــف‬\n‫ريــال وجهــاز كمبيوتــر محمــول نــوع ‪ .....‬قيمتــه بخمســة آالف ريــال‬\n‫وجهــاز جــوال ‪ .....‬قيمتــه بثالثــة آالف ريــال ومت تصليــح أقفــال األبــواب‬\n‫الداخليــة التــي قامــا بكســرها مببلــغ تســعمائة وخمســن ريــاال مــع‬\n‫أعمــال النظافــة وقــد تبــن لــي مــن اعتــراف املدعــى عليــه هــذا احلاضــر‬\n‫لــدى البحــث اجلنائــي أنــه هــو الــذي قــام بســرقة منزلــي املذكــور وســرقة‬\n‫األعيــان املذكــورة مــع ‪ .....‬وأن قيمــة األعيــان املســروقة مــع قيمــة تصليح‬\n‫األبــواب الداخليــة مــع قيمــة أعمــال النظافــة هــي مــا ذكرتــه آنفــا واهلل‬\n‫علــى مــا أقــول شــهيد وبعــد ســماع الدعــوى واإلجابــة واالطــاع علــى‬\n‫أوراق املعاملــة ومبــا ان املدعــي وكالــة ادعــى مبــا ادعــى بــه وأنكــر‬\n‫املدعــى عليــه ذلــك وأفــاد املدعــي وكالــة أن بينتــه علــى ذلــك هــي مــا ورد‬\n‫يف اعتــراف املدعــى عليــه مبحضــر التحقيــق وبالرجــوع حملضــر التحقيق‬\n‫املنصــوص بعاليــه واعتــراف املدعــى عليــه بذلــك وأنه مكرهــا على ذلك‬\n‫ومبــا أن املدعــى عليــه لــم يذكــر يف اعترافــه قيمــة األعيــان املدعــى بهــا‬\n‫واســتنادا ملــا قــرره الفقهــاء بــأن اليمــن تؤخــذ يف جانــب أقــوى املتداعيني‬\n‫وأدى املدعــي أصالــة اليمــن املعتبــرة شــرعا علــى صحــة دعــواه واســتنادا‬\n‫للقاعــدة ال عــذر ملــن أقــر لــذا فقــد ثبــت لــدي أن يف ذمــة املدعــى عليــه‬\n\n\n                                                                                       ‫‪126‬‬\n\f      ‫للمدعــي أصالــة قيمــة األعيــان املذكــورة يف الدعــوى وقدرهــا خمســه‬\n      ‫وعشــرون الفــا وتســعمائة وخمــس وســبعون ريــاال ومبــا أنــه ثبــت لــدي‬\n      ‫ذلــك فقــد أفهمــت املدعــى عليــه أنــه يلزمــه تســليم ذلــك للمدعــي أصالــة‬\n      ‫هــذا مــا ظهــر لــي وبــه حكمــت ولــدى عــرض ذلــك علــى املدعــى عليــه‬\n      ‫فقــرر عــدم قناعتــه باحلكــم وطلــب رفــع احلكــم مــع املعاملــة حملكمــة‬\n      ‫االســتئناف بــدون الئحــة اعتراضيــة وقــررت رفــع كامــل املعاملــة مــع‬\n      ‫صــك احلكــم وصــورة ضبطــه حملكمــة االســتئناف لتدقيقــه وبــاهلل‬\n              ‫التوفيــق وصلــى اهلل علــى نبينــا محمــد حــرر يف ‪1434/1/10‬ه ـ ‪.‬‬\n\n\n\n      ‫•صــدق احلكــم مــن محكمــة االســتئناف برقــم ‪ 3451153‬وتاريــخ‬\n                                                     ‫‪1434/4/24‬هــ‪.‬‬\n\n\n\n\n‫‪127‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":123,"source_page_end":127,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"a37ff12bbb5cc27b6c85c20a6908ee32fd6b0c80c5adc5fc03b737849426840e","normalized_text_hash":"dbd0356633e368feebf55e702caa183f9098db4f04ef7bb89b087b094e710645","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p123-347621"},{"id":"9cc87f24-b0a1-574d-a166-70a4fffb7435","document_type":"judgment","category":"judicial","subcategory":"general","title":"رد مسروق -اشتراك يف سرقة مبالغ مالية عن طريق تزوير شيكات -اإلقرار -احلكم باإللزام برد املبالغ ممن قبضها واستلمها -رد الدعوى ملن لم يثبت قبضه للمبالغ -اإلفهام بالرجوع على من","document_number":"33316247","case_number":"32540118","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/6/25","year":"1434","subject":"رد مسروق -اشتراك يف سرقة مبالغ مالية عن طريق تزوير شيكات -اإلقرار -احلكم باإللزام برد املبالغ ممن قبضها واستلمها -رد الدعوى ملن لم يثبت قبضه للمبالغ -اإلفهام بالرجوع على من","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1433/6/25 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪33316247 :‬‬\n                    ‫َر ْق ُم الدعوى‪32540118:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 3422887‬تاريخه‪1434/1/26:‬هـ‬\n\n\n‫رد مســروق ‪ -‬اشــتراك يف ســرقة مبالــغ ماليــة عــن طريــق تزويــر شــيكات‬\n‫‪ -‬اإلقــرار ‪ -‬احلكــم باإللــزام بــرد املبالــغ ممــن قبضهــا واســتلمها ‪ -‬رد‬\n‫الدعــوى ملــن لــم يثبــت قبضــه للمبالــغ ‪ -‬اإلفهــام بالرجــوع علــى مــن‬\n                                                                        ‫غــره ‪.‬‬\n\n\n\n\n‫مــا اســتند إليــه القاضــي مــن املبــادئ العامــة وقواعــد العدالــة الــواردة‬\n                                                         ‫يف تســبيب احلكــم ‪.‬‬\n\n\n\n\n‫ادعــى وكيــل الشــركة املدعيــة بــأن املدعــى عليهــم قامــوا باالســتيالء‬\n‫علــى مبالــغ ماليــة مــن احلســاب املصــريف ملوكلتــه عــن طريــق تزويــر‬\n‫شــيكات عائــدة لهــا وصرفهــا لصاحلهــم دون وجــه حــق ؛ وطلــب إلزامهــم‬\n‫متضامنــن بإعــادة املبالــغ املســروقة ملوكلتــه ‪ -‬أنكــر املدعــى عليهــم‬\n‫دعــوى املدعيــة جتاههــم‪ -‬املدعــى عليهمــا األول والرابــع أقــرا بأنهمــا‬\n‫قامــا بصــرف الشــيكات املذكــورة واســتلما املبالــغ املدعــى بهــا نقــدا‪،‬‬\n‫ودفعــا بأنهمــا فعــا ذلــك لصالــح شــخص آخــر وأنهمــا ســلما لــه تلــك‬\n‫املبالــغ بعــد أن أعطاهمــا جــزء منهــا‪ -‬قضــت احملكمــة بإلــزام املدعــى‬\n‫عليهمــا األول والرابــع بتســليم املدعيــة املبالــغ التــي قامــا بســحبها مــن‬\n\n                                                                                    ‫‪128‬‬\n\f      ‫حســابها املصــريف عــن طريــق تلــك الشــيكات املــزورة وأفهمــت األول‬\n      ‫بــأن لــه أن يقيــم دعــواه علــى مــن غــره متــى رغــب ذلك ‪ -‬عارضــت املدعية‬\n      ‫واملدعــى عليــه األول علــى احلكــم وقنــع بــه باقــي املدعــى عليهــم ‪ -‬قررت‬\n                                ‫محكمــة االســتئناف املوافقــة علــى احلكــم ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n      ‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة العامــة مبحافظــة جدة‪/‬املســاعد برقــم ‪ 32540118‬وتاريــخ‬\n      ‫‪ 1432/11/19‬ه ـ املقيــدة باحملكمــة برقــم ‪ 321447916‬وتاريــخ‬\n      ‫‪ 1432/11/14‬ه ـ ففــي يــوم األحــد املوافــق‪ 1433/02/07‬ه ـ حضــر‬\n      ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم الوكيــل الشــرعي عــن‬\n      ‫‪ ....‬بوكالتــه عــن بصفتــه رئيــس مجلــس املديريــن بشــركة ‪ ...‬مبوجــب‬\n      ‫الوكالــة الصــادرة مــن كتابــه عــدل الثانيــة بشــمال جــدة برقــم ‪2348‬‬\n      ‫يف ‪1432/1/7‬ه ـ جلــد ‪ 10215‬وحضــر ســعودي اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم الوكيــل الشــرعي عــن بوكالتــه عــن املدعــى عليــه‬\n      ‫‪ ...‬مبوجــب الوكالــة الصــادرة مــن كتابــه عــدل الثانيــة بشــمال جــدة‬\n      ‫برقــم ‪ 105843‬يف ‪1432/12/19‬ه ـ جلــد ‪ 11251‬و الوكيــل الشــرعي‬\n      ‫عــن بوكالتــه عــن املدعــى عليــه مبوجــب الوكالــة الصــادرة مــن كتابــه‬\n      ‫عــدل الثانيــة بشــمال جــدة برقــم ‪ 5662‬يف ‪1433/1/17‬ه ـ جلــد ‪11340‬‬\n      ‫و حضــر املدعــى عليهمــا الســجينان ولــم يحضــرا مــا يثبــت هويتهمــا‬\n      ‫وابــرز املدعــي وكالــه ‪ ...‬املذكــور اعــاه صحيفــة دعــوى هــذا نصهــا‬\n      ‫‪ :‬حيــث أقــدم املدعــى عليهــم كل مــن‪ ...-4 ...-3 ...-2 ....- 1 :‬علــى‬\n\n‫‪129‬‬\n\f‫االســتيالء علــى مبلــغ وقــدرة ‪3.449.000‬ريــال (ثالثــة ماليــن وأربعمائــة‬\n‫وتســعة وأربعــون ألــف ريــال ) عــن طريــق تزويــر محــررات عرفيــه مــن‬\n‫شــركة موكلــي وحكــم عليهــم مبعاقبــة كل واحــد منهــم بســجنه‬\n‫مــدة ســنتني حتســب مــن تاريــخ توقيفــه علــى ذمــة هــذه القضيــة وتغــرمي‬\n‫كل واحــد منهــم مبلــغ خمســة آالف ريــال ‪.‬وذلــك كمــا هــو واضــح‬\n‫مــن احلكــم الصــادر مــن ديــوان املظالــم برقــم ‪/86‬د‪ 12/‬لعــام ‪1432‬ه ـ‬\n‫و(املرفــق صورتــه) واطلــب إلــزام املدعــى عليهــم متضامنــن بدفــع مبلــغ‬\n‫وقدره‪3449.000.‬ريــال (ثالثــة ماليــن وأربعمائــة وتســعة وأربعــون ألــف‬\n‫ريــال) للشــركة املدعيــة ‪ .‬وبقــراءة هــذه الدعــوى علــى املدعــى عليهــم‬\n‫اصالــه ووكالــة اجابــوا قائلــن نطلــب تســليمنا صــورة الدعــوى وامهالنــا‬\n‫إلحضــار اإلجابــة عليهــا مفصــا وعليــه جــرى تســليمهم صــورة مــن‬\n‫الدعــوى واجلــت اجللســة ويف يــوم االحــد املوافــق ‪1433/3/13‬ه ـ حضــر‬\n‫املدعــي وكالــه املذكــور اعــاه وحضــر املذكــور اعــاه ولــم يحضــر‬\n‫املدعــى عليــه واجــاب املدعــى عليــه وكالــه علــى الدعــوى املرصــودة‬\n‫اعــاه قائــا انــه ال صحــة ملــا جــاء يف هــذه الدعــوى وعليــه طلبــت مــن‬\n‫املدعــي وكالــه البينــة علــى مــا جــاء يف دعــواه فقــال ان بينتــي هــي‬\n‫احلكــم الصــادر مــن ديــوان املظالــم املشــار اليــه يف الدعــوى املتضمــن‬\n‫اعترافــات املدعــى عليهــم باســتعمال احملرريــن املزوريــن وهمــا شــيكني‬\n‫وصرفهمــا مــن البنــك حلســابهما وإلحضــار املدعــى عليــه الســجني‬\n‫واخــذ جوابــه علــى الدعــوى اجلــت اجللســة ويف يــوم األربعــاء املوافــق‬\n‫‪ 1433/05/26‬ه ـ حضــر املدعــي وكالــه املذكــور اعــاه وحضــر‬\n‫املدعــى عليــه وكالــه بهــاء الديــن املذكــور اعــاه وحضــر املدعــى عليــه‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم واجــاب املدعــى عليــه‬\n\n\n                                                                                 ‫‪130‬‬\n\f      ‫قائــا ان مــا جــاء يف الدعــوى غيــر صحيــح واننــي لــم اســتلم شــيئا مــن‬\n      ‫املبلــغ املذكــور يف الدعــوى ابــدا ‪ .‬فطلبــت مــن املدعــي وكالــه ابــراز‬\n      ‫البينــة علــى دعــواه فابــرز حكمــا صــادر مــن ديــوان املظالــم هــذا نصــه‪:‬‬\n      ‫«حكــم رقــم ‪/86‬د‪ 12/‬لعــام ‪1432‬ه ـ صــادر عــن الدائــرة الثانيــة عشــرة‬\n      ‫يف القضيــة رقــم ‪/2/1268‬ق لعــام ‪1432‬ه ـ املقامــة مــن ‪/‬فــرع هيئــة‬\n      ‫الرقابــة والتحقيــق مبنطقــة مكــة املكرمــة ضــد املدعــى عليــه ‪... /‬‬\n      ‫ورفقــاه انــه يف يــوم األحــد املوافــق ‪1432/2/19‬ه ـ اجتمعــت الدائــرة‬\n      ‫الثانيــة عشــرة باحملكمــة االداريــة مبحافظــة جــدة واملشــكلة مــن ‪:‬‬\n      ‫القاضــي ‪ ...‬رئيســا القاضــي عضــوا القاضــي عضــوا وبحضــور امينــا‬\n      ‫للســر وذلــك للنظــر يف القضيــة املذكــورة اعــاه احملالــة للدائــرة بتاريــخ‬\n      ‫‪1432/2/15‬ه ـ الوقائــع تتخلــص وقائــع هــذه القضيــة يف انــه ورد الــى‬\n      ‫احملكمــة اإلداريــة مبحافظــة جــدة خطــاب هيئــة الرقابــة والتحقيــق‬\n      ‫رقــم (‪ )1671/14‬وتاريــخ ‪1432/2/8‬ه املرفــق بــه قــرار االتهــام رقــم‬\n      ‫(‪/224‬ج) لعــام ‪1432‬ه مــع مشــفوعاته وقــد باشــرت الدائــرة النظــر‬\n      ‫يف القضيــة علــى النحــو املثبــت مبحضــر الضبــط حيــث حضــر ممثــل‬\n      ‫االدعــاء ‪ /‬واملتهمــن وادعــى ممثــل االدعــاء يف مواجــه املتهمــن قائــا‪:‬‬\n      ‫تتهــم هيئــة الرقابــة والتحقيــق كل مــن ‪ ... 1 :‬ســعودي اجلنســية ‪)44( ،‬‬\n      ‫ســنة ‪ ،‬متقاعــد ‪،‬متــزوج ولديــه اوالد ‪،‬موقــوف بســجون محافظــة جــدة‬\n                                                ‫اعتبــارا مــن تاريــخ ‪1432/1/16‬ه ـ‬\n      ‫‪ ... -2‬ســعودي اجلنســية ‪ )23( ،‬ســنة ‪ ،‬جنــدي بقــوات الطــوارئ اخلاصــة‬\n      ‫بالعاصمــة املقدســة ‪ .‬اعــزب ‪،‬موقــوف بســجون محافظــة جــدة اعتبــارا‬\n                                                          ‫مــن تاريــخ ‪1432/1/12‬ه ـ‬\n      ‫‪ ... -3‬ســعودي اجلنســية ‪ )34( ،‬ســنة ‪ ،‬موظــف مبصــرف ‪ ...‬متــزوج‬\n\n\n‫‪131‬‬\n\f‫واب لبنــت ‪ ،‬موقــوف بســجون محافظــة جــدة اعتبــارا مــن تاريــخ‬\n                                                                  ‫‪1432/1/28‬هــ‪.‬‬\n‫‪ ... -4‬ســعودي اجلنســية ‪31( ،‬ســنه متــزوج ولديــه بنتــن ‪ ،‬موقــوف‬\n          ‫بســجون محافظــة جــدة اعتبــارا مــن تاريــخ ‪1432/1/28‬هــ‪.‬‬\n‫النهــم وقبــل ذلــك التاريــخ بدائــرة محافظــة جدة مبنطقــة مكة املكرمة‬\n‫‪ :‬املتهــم االول والثانــي والثالــث‪- :‬ســاهموا مــع ‪ /‬؟ ســوري اجلنســية ؟‬\n‫فــرزت لــه اوراق مســتقلة للبحــث عنــه ؟ يف تزويــر ورقــة ماليــه جتاريــة‬\n‫(الشــيك رقــم ‪ 20908‬وتاريــخ ‪2010/12/1‬م باســم املتهــم الثانــي مببلــغ‬\n‫‪ 324000‬ريــال ‪ -‬صــادر مــن البنــك ‪ ...‬فــرع شــارع ‪ ...‬مــن حســاب شــركة‬\n‫‪ )...‬عــن طريــق االتفــاق واملســاعدة وذلــك بــان حصــل املتهــم االول علــى‬\n‫احملــرر مــن ‪ /‬املذكــور بعــد ان قــام بســرقته وتزويــر تواقيــع االشــخاص‬\n‫املعتمديــن لــدى البنــك بصرفــه ثــم قــام بتســليمه للمتهــم الثالــث الــذى‬\n‫قــام بتعبئــة بيانــات املســتفيد واملبلــغ ثــم ســلمه للمتهــم الثانــي الــذى بدوره‬\n‫قدمــه للبنــك ومت صرفــه ‪ ،‬وبنــاء عليــه متــت اجلرميــة املتهــم االول والرابــع‪:‬‬\n‫‪-‬ســاهما مــع ‪ /‬املذكــور اعــاه يف تزويــر ورقــة ماليــه جتاريــة (الشــيك‬\n‫رقم ‪ 20893‬وتاريخ ‪2010/12/7‬م باســم املتهم الرابع مببلغ ‪3125000‬‬\n‫ريــال ‪ ،‬الصــادر مــن البنــك ‪ .....‬فــرع شــارع ‪ .....‬مــن حســاب شــركة ‪...‬‬\n‫) عــن طريــق االتفــاق واملســاعدة وذلــك بــان حصــل املتهــم االول علــى‬\n‫احملــرر مــن ‪ /‬املذكــور بعــد ان قــام بســرقته وتزويــر تواقيــع االشــخاص‬\n‫املعتمديــن لــدى البنــك بصرفــة ثــم قــام املتهــم االول بتعبئــة الشــيك باســم‬\n‫املســتفيد ؟ املتهــم الرابــع ‪ -‬واملبلــغ ثــم ســلمه للمتهــم الرابــع الــذى بــدورة‬\n‫قدمــه للبنــك وقــام بصرفــه مــع علمــه بالتزويــر ؟ وبنــاء عليــه متــت اجلرميــة‪.‬‬\n‫املتهمــن مــن االول حتــى الرابــع ‪ :‬اســتعملوا احملــرران (محــل االتهــام) مــع‬\n\n\n                                                                                          ‫‪132‬‬\n\f      ‫علمهــم التــام بتزويرهمــا وذلــك بتداولهمــا فيمــا بينهــم بعــد امتــام جرميــة‬\n      ‫التزويــر ؟ كمــا هــو موضــح اعــاه ومــن ثــم قيــام املتهــم الثانــي والرابــع‬\n      ‫بتقدميهــا للبنــك وصــرف املبلــغ ؟ بنــاء عليــه متــت اجلرميــة‪ .‬ودللــت الهيئــة‬\n      ‫علــى االتهــام ‪ :‬شــكوى رئيــس شــركة ‪ ...‬املتضمنــة ســرقة الشــيكني ؟‬\n              ‫محــل االتهــام وتزويــر تواقيــع االشــخاص املعتمديــن يف الشــركة‪.‬‬\n      ‫‪ -2‬افــادة البنــك ‪ ...‬املتضمــن ان الــذى قــام بصــرف الشــيكني ؟ محــل‬\n                                                    ‫االتهــام همــا املتهــم الثانــي والرابــع‪.‬‬\n      ‫‪ -3‬اعتــراف املتهــم االول مبــا نســب اليــه مــن قيامــة باحلصــول علــى‬\n      ‫الشــيكني ‪ -‬محــل االتهــام ؟ مــن شــخص ســوري اجلنســية اســمه‪ .../‬ثــم‬\n      ‫قــام بتقدميهمــا الــى املتهمــن الثانــي والرابــع لغــرض الصــرف باســمهما‪.‬‬\n      ‫‪ -4‬اعتــراف املتهــم االول بــان جميــع املتهمــن لديهم العلم بان الشــيكني‬\n                                   ‫محل االتهام مســروقة ومت تعبئتهما بعد الســرقة ‪.‬‬\n      ‫‪ -5‬اعتــراف املتهــم االول بــان الــذى قــام بتعبئــة بيانــات الشــيك االول‬\n      ‫الــذى باســم املتهــم الثانــي هــو املتهــم الثالــث ولديــه العلــم بالتزويــر‪-6.‬‬\n      ‫اعتــراف املتهــم الثانــي بأنــه قــام باســتخراج تذكــره ســفر لغــرض صرف‬\n      ‫الشــيك باســمة كــون بنــك املطــار ال يصــرف الشــيك اال للمســافرين ثــم‬\n      ‫قــام بصرفــه وتســليم املبلــغ للمتهــم االول دون ان يســتلم مبلــغ التذكــرة‬\n      ‫الــذى جتاوز(‪800‬ريــال) ‪ -7‬اعتــراف املتهــم الثانــي بأنــه ذهــب الــى املطار‬\n      ‫لغــرض صــرف الشــيك ؟ محــل االتهــام ؟ برفقــة املتهمــن االول والثالــث‪.‬‬\n      ‫‪ -8‬اعتــراف املتهــم الثالــث بانــه قــام بتعبئــة الشــيك ؟ محــل االتهــام الــذى‬\n                                 ‫باســم املتهــم الثانــي بتدويــن اســم املســتفيد واملبلــغ ‪.‬‬\n      ‫‪ -9‬املتهــم الثالــث يعمــل مبصــرف ‪ ...‬وأفــاد بأنــه التحــق بــدورات تدريبيــة‬\n      ‫لألعمــال املصرفيــة وبذلــك لديــه العلــم بانــه مــا قــام بــه مخالــف لألنظمــة‬\n\n\n‫‪133‬‬\n\f‫مــن قيامــة بتعبئــة بيانــات املســتفيد دون علــم صاحــب احلســاب والرجــوع‬\n                                                                             ‫اليــه ‪.‬‬\n‫‪ -10‬اعتــراف املتهــم الرابــع مبــا نســب اليــه مــن انــه حصــل علــى الشــيك‬\n‫الــذى باســمة محــل االتهــام مــن املتهــم االول ثــم قــام بصرفــة مــع علمــه‬\n‫التــام بالتزويــر ‪.‬وطلبــت الهيئــة مــن احملكمــة االداريــة محاكمــة‬\n‫املتهمــن املذكوريــن طبقــا ألحــكام املــواد (‪ )10،7،6،5‬مــن نظــام‬\n‫مكافحــة التزويــر وقــرار مجلــس الــوزراء رقــم (‪ )223‬لعــام ‪1399‬هــ‪.‬‬\n‫وبســؤال املدعــى عليــه االول اجلــواب اجــاب قائــا ‪:‬اعتــرف مبــا ورد‬\n‫يف الدعــوى جملــه وتفصيــا فقــد حصلــت علــى الشــيك محــل االتهــام‬\n‫مــن شــخص ســوري اســمه‪ /‬موقــع مــن شــخصني مــن شــركة ‪ ...‬وقمــت‬\n‫بتســليم الشــيك للمتهــم الثانــي ‪ /‬وقمنــا بصــرف الشــيك مــن مصــرف ‪...‬‬\n‫فــرع ‪ ...‬ثــم وبعــد ذلــك ســلمني املتهــم الثانــي املبلــغ كــون الشــيك باســمة‬\n‫وســلمته نســبته خمســة يف املائــة البالغــة ثمانيــة عشــر الــف ريــال وأصادق‬\n‫علــى أقوالــي الســابقة وأضــاف بأنــه متــزوج ويعــول اســره مكونــه مــن‬\n‫زوجــه وطفلــن ووالدتــي األرملــة‪ .‬وبســؤال املدعــى عليــه الثانــي اجلــواب‬\n‫اجــاب قائــا‪ :‬بــان املتهــم ‪...... /‬ســلمني الشــيك محــل االتهــام وقــام‬\n‫بكتابــة اســمى علــى الشــيك املتهــم الثالــث ‪ /‬وذهبنــا الــى املطــار‬\n‫ودخلــت الــى مصــرف ‪ ...‬فــرع ‪ ...‬واملتهــم االول‪ /‬وقمــت بصــرف الشــيك‬\n‫وســلمت املبلــغ اليــه وبســؤاله عــن اقوالــه يف التحقيقــات اجــاب بانهــا‬\n‫صحيحــة ويصــادق عليهــا وبســؤاله عــن نســبته مــن مبلــغ الشــيك اجــاب‬\n‫بأنــه لــم يســتلم أي نســبة ومبواجهتــه باعترافــه يف التحقيقــات بأنــه قــام‬\n‫باســتخراج تذكــرة ســفر لغــرض صــرف الشــيك الــذى باســمة الن بنــك‬\n‫املطــار ال يصــرف الشــيك اال للمســافرين اجــاب ذلــك صحيــح‪ .‬وبســؤال‬\n\n\n                                                                                        ‫‪134‬‬\n\f      ‫املدعــى عليــه الثالــث اجلــواب اجــاب قائــا‪ :‬اعتــرف بأنــى قمــت بكتابــة‬\n      ‫اســم املســتفيد ‪ /‬واملبلــغ علــى الشــيك مببلــغ ثالثمائــة وأربعــة وعشــرون‬\n      ‫الــف ريــال وقمــت بتوصيــل املتهمــن االول والثانــي الــى مطــار ‪ ...‬لصــرف‬\n      ‫الشــيك وال اعلــم عــن موضــوع الشــيك وقــد ذكــر لــي أخــي املتهــم االول‬\n      ‫انــه عبــارة عــن عربــون مصنــع وبســؤاله عــن اقوالــه يف التحقيقــات اجــاب‬\n      ‫بأنهــا صحيحــة ويصــادق عليهــا وبســؤاله ايــن تعمــل فأجــاب باننــي اعمــل‬\n      ‫مبصــرف ‪ ...‬وقــد التحقــت بعــدة دورات تدريبيــة لألعمــال املصرفيــة‬\n      ‫وبســؤاله قيامــك بكتابــة اســم املســتفيد واملبلــغ علــى الشــيك محــل‬\n      ‫االتهــام دون علــم صاحــب احلســاب والرجــوع اليــه مخالــف لألنظمــة ؟‬\n      ‫اجــاب بأنــه غيــر مخالــف لألنظمــة ‪.‬وبســؤال املدعــى عليــه الرابــع اجلواب‬\n      ‫اجــاب قائــا ‪ :‬بــان املتهــم االول ‪ /‬ســلمني الشــيك مكتــوب باســمي‬\n      ‫وعليــه املبلــغ بثالثــة ماليــن ومائــة وخمســة وعشــرون الــف ريــال فســألته‬\n      ‫ملــاذا قــام بكتابــة الشــيك باســمي فأجابنــي بأنــه حســابه مقفــل وذهبنــا‬\n      ‫معــا الــى بنــك ‪ ...‬وقمــت بصرفــه علــى النحــو التالــي ‪(:‬مبلــغ مائتــن‬\n      ‫وخمســة وســبعون الــف ريــال نقــدا وقمــت بتحويــل باقــي املبلــغ يف حســابه‬\n      ‫يف مصــرف ‪ ...‬وســلمني املتهــم االول مبلــغ مائــة وتســعة وثالثــون الــف‬\n      ‫ريــال مســتحقاتي التــي متثــل عملــي معــه ملــدة ســبعة اشــهر وبســؤاله عــن‬\n      ‫اقوالــه يف التحقيقــات اجــاب بانهــا صحيحــة‪ .‬وبســؤال املتهــم االول كــم‬\n      ‫نســبة املتهــم الرابــع مــن صــرف الشــيك الثانــي فأجــاب باننــي ســلمته‬\n      ‫خمســة يف املئــة مــن قيمــة الشــيك مبلــغ وقــدرة مائــة وتســعة وثالثــون الــف‬\n      ‫ريــال وباقــي مبلــغ الشــيك ســلمته للشــخص الســوري ‪./‬وبســؤال املدعــى‬\n      ‫عليــه االول بــان املتهــم الرابــع ذكــر بــان املبلــغ الــذى تســلمه منــك كان‬\n      ‫عبــارة عــن رواتبــه املتأخــرة ملــدة ســبعة اشــهر فأجــاب بــان كالمــه غيــر‬\n\n\n‫‪135‬‬\n\f‫صحيــح واملبلــغ املســلم لــه ميثــل خمســة يف املئــة مــن قيمــة الشــيك وبســؤال‬\n‫املدعــى عليــه الرابــع عــن اقوالــه الســابقة اجــاب بانهــا صحيحــة ويصــادق‬\n‫عليهــا ثــم اضــاف املتهــم الرابــع بانــه يعــول اســرة مكونــه مــن زوجتــن‬\n‫وطفلتــن ليــس لهــم عائــل بعــد اهلل غيــرى ثــم اكتفــى االطــراف مبــا‬\n‫قدمــوه وطلبــوا الفصــل يف القضيــة بحالتهــا الراهنــة ‪.‬وحيــث انــه بنــاء‬\n‫علــى الدعــوى واإلجابــة وبعــد دراســة القضيــة واالطــاع علــى االوراق‬\n‫وعلــى شــكوى رئيــس شــركة ‪ ....‬املتضمنــة ســرقة شــيكني محــل‬\n‫االتهــام وتزويــر تواقيــع املعتمديــن يف الشــركة وعلــى افــادة البنــك ‪...‬‬\n‫بــان الــذى قــام بصــرف الشــيكني محــل االتهــام املدعــى عليهمــا الثانــي‬\n‫والرابــع وعلــى اعتــراف املدعــى عليــه االول يف جميــع مراحــل التحقيــق‬\n‫وأمــام الدائــرة مبــا نســب اليــه مــن قيامــة باحلصــول علــى الشــيكني محل‬\n‫االتهــام مــن شــخص ســوري اجلنســية يدعــى ‪........ /‬ثــم قــام بتقدميهمــا‬\n‫للمدعــى عليهمــا الثانــي والرابــع مــن اجل صرفهما باســمهما وان املدعى‬\n‫عليهــم جميعــا لديهــم العلــم بــان الشــيكني مزوريــن وان نصيــب كال‬\n‫منهــم خمســة يف املائــة مــن قيمــة الشــيك وعلــى اعتــراف املدعــى عليــه‬\n‫الثانــي بأنــه قــام باســتخراج تذكــرة ســفر لغــرض صــرف الشــيك الــذى‬\n‫باســمه الن بنك املطار ال يصرف الشــيك إال للمســافرين ثم قام بصرفة‬\n‫وتســليم املبلــغ الــى املدعــى عليــه االول دون ان يســتلم مبلــغ التذكــرة‬\n‫البالــغ ثمامنائــة ريــال مــن املدعــى عليــه االول وانــه ذهــب للمطــار مــن اجــل‬\n‫صــرف الشــيك برفقــة املدعــى عليهمــا االول والثالــث وعــل اعتــراف‬\n‫املدعــى عليــه الثالــث بأنــه قــام بتعبئــة الشــيك محــل االتهــام الــذى باســم‬\n‫املدعــى عليــه الثانــي وذلــك بتدويــن اســم املســتفيد املدعــى عليــه الثانــي‬\n‫واملبلــغ علــى الرغــم مــن علمــه بــان ذلــك مخالــف لألنظمــة كونــه يعمــل‬\n\n\n                                                                                         ‫‪136‬‬\n\f      ‫يف مصــرف ‪ ...‬ولديــه عــدة دورات تدريبيــة لألعمــال املصرفيــة وقيامــة‬\n      ‫بتعبئــة بيانــات املســتفيد واملبلــغ علــى الشــيك دون علــم صاحــب احلســاب‬\n      ‫والرجــوع اليــه و علــى اعتــراف املدعــى عليــه الرابــع يف التحقيقــات بانــه‬\n      ‫حصــل علــى الشــيك الــذى باســمة محــل االتهــام مــن املدعــى عليــه االول‬\n      ‫ثــم قــام بصرفــة واســتالم نســبته خمســة يف املائــة مــن قيمــة الشــيك مــع‬\n      ‫علمــه التــام بتزويــره ممــا تخلــص معــه الدائــرة الــى ادانتهــم بجرائــم‬\n      ‫التزويــر واالســتعمال املنســوبة اليهــم يف هــذه الدعــوى‪ .‬ومعاقبتهــم عــن‬\n      ‫ذلــك طبقــا لنــص املــادة (‪ )10،7،6،5‬مــن نظــام مكافحــة التزويــر‬\n      ‫واعتبارهــم فاعلــن اصليــن طبقــا لقــرار مجلــس الــوزراء رقــم (‪)223‬‬\n      ‫لعــام ‪1399‬ه مــع االكتفــاء بالعقوبــة املقــررة للجرميــة االشــد اعمــاال ملبدأ‬\n      ‫تداخــل العقوبــات يف الفقــه اإلســامي ‪ .‬لذلــك حكمــت الدائــرة‪ :‬بإدانــة‬\n      ‫كل مــن االول ‪ .../‬والثانــي‪..... /‬والثالــث‪..... /‬والرابــع ‪(...... /‬ســعوديي‬\n      ‫اجلنســية) بجرائــم التزويــر واالســتعمال املنســوبة اليهــم يف هــذه الدعــوى‬\n      ‫ومعاقبــة كل واحــد منهــم بســجنه مــدة ســنتني حتســب مــن تاريــخ‬\n      ‫توقيفــه علــى ذمــة هــذه القضيــة وتغــرمي كل واحــد منهــم مبلــغ خمســة‬\n      ‫آالف ريــال ملــا هــو موضــح باألســباب وبإعالنــه علــى االطــراف قــرروا‬\n      ‫القناعــة بــه وبذلــك اصبــح احلكــم نهائيــا وواجــب النفــاذ‪ .‬واهلل املوفــق‬\n      ‫وصلــى اهلل علــى نبينــا محمــد وعلــى الــه وصحبــه وســلم»‪ .‬وبعــرض مــا‬\n      ‫جــاء يف هــذا احلكــم علــى املدعــى عليهــم قالــوا اننــا حضرنــا لــدى ديــوان‬\n      ‫املظالــم وصــدر علينــا احلكــم املرصــود اعــاه وللتأمــل يف الدعوى اجلت‬\n      ‫اجللســة احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء املوافــق‪1433/06/25‬‬\n      ‫ه ـ حضــر املدعــي وكالــه املذكــور اعــاه وحضــر املدعــى عليــه وكاله‬\n      ‫‪ ...‬املذكــور اعــاه وحضــر الســجناء املذكوريــن اعــاه وابــرز املدعــى‬\n\n\n‫‪137‬‬\n\f‫عليــه وكالــه صــك وكالــة صــادر مــن كتابــه عــدل الثانية بشــمال جدة‬\n‫برقــم ‪ 47238‬يف ‪1433/5/25‬ه ـ جلــد ‪ 11756‬تتضمــن توكيل املدعى‬\n‫عليــه يف املرافعــة واملدافعــة وحضــور اجللســات ‪...‬الــخ وتخــول للوكيــل‬\n‫الســير يف هــذه الدعــوى نيابــة عــن املدعــى عليــه املذكــور اعــاه ‪ .‬وبعــد‬\n‫التأمــل يف الدعــوى واالطــاع علــى احلكــم الصــادر مــن ديــوان املظالــم‬\n‫املرصــود اعــاه وجــد ان املدعــى عليــه هــو مــن قــام بصــرف الشــيك رقــم‬\n‫‪ 020893‬واســتالم قيمتــه وبســؤال املدعــى عليــه املذكــور اعــاه عــن‬\n‫ذلــك قــال صحيــح اننــي قمــت بصــرف الشــيك رقــم ‪ 020893‬واســتلمت‬\n‫قيمتــه وقدرهــا ثالثــة ماليــن ومائــه وخمســه وعشــرون الــف ريــال‬\n‫واخــذت منهــا مبلــغ مائــه وتســعه وثالثــن الــف ريــال فقــط واملبلــغ الباقــي‬\n‫وقــدرة مليونــان وتســعمائة وســته وثمانــن الــف ريــال قمــت بتحويلــه علــى‬\n‫حســاب املدعــى عليــه وبســؤال املدعــى عليــه عــن ذلــك قــال صحيــح‬\n‫ان املدعــى عليــه ‪ ...‬قــد حــول املبلــغ علــى حســابي وانــا قمــت بســحبه‬\n‫نقــدا وتســليمه للمدعــو ســوري اجلنســية نقــدا وباالطــاع علــى احلكــم‬\n‫الصــادر مــن ديــوان املظالــم املرصــود اعــاه وجــد ان املدعــى عليــه ‪ ...‬هــو‬\n‫مــن قــام بصــرف الشــيك رقــم ‪ 020908‬واســتالم قيمتــه وبســؤال املدعــى‬\n‫عليــه املذكــور اعــاه عــن ذلــك قــال صحيــح اننــي قمــت بصــرف الشــيك‬\n‫رقــم ‪ 020908‬واســتلمت قيمتــه وقدرهــا ثالثمائــة واربعــه وعشــرون الــف‬\n‫ريــال وقمــت بســحبه نقــدا وتســليمه للمدعــى وبســؤال املدعــى عليــه عــن‬\n‫ذلــك قــال صحيــح ان املدعــى عليــه ‪ ...‬قــد ســلمني املبلــغ نقــدا وقمــت‬\n‫بتســليمه للمدعــو ســوري اجلنســية نقــدا وســلمني مــن املبلــغ ثمانيــة عشــر‬\n‫الــف وســتمائة ريــال فقــط وعليــه بنــاء علــى الدعــوى واإلجابــة ومــا جــاء‬\n‫يف احلكــم النهائــي الصــادر مــن ديــوان املظالــم املرصود اعــاه واعتراف‬\n\n\n                                                                                      ‫‪138‬‬\n\f      ‫املدعــى عليــه ‪ ...‬باســتالم مبلــغ مائــه وتســعه وثالثــن الــف ريــال واعتراف‬\n      ‫املدعــى عليــه باســتالم مبلــغ مليونــن وتســعمائة وســته وثمانــن ريــال مــن‬\n      ‫الشــيك االول ومبلــغ ثالثمائــة واربعــه وعشــرين الــف ريــال مــن الشــيك‬\n      ‫الثانــي ليصبــح مجمــوع املبلــغ الــذي اســتلمه املدعــى عليــه هــو مبلــغ‬\n      ‫ثالثــة مليــون وثالثمائــة وعشــرة االف ريــال وجلميــع مــا ذكــر بعاليــه‬\n      ‫فقــد حكمــت علــى املدعــى عليــه بتســليم شــركة ‪ ...‬مبلــغ مائــه وتســعه‬\n      ‫وثالثــن الــف ريــال وحكمــت علــى املدعــى عليــه بتســليم شــركة ‪...‬‬\n      ‫مبلــغ ثالثــة ماليــن وثالثمائــة وعشــرة االف ريــال وحكمــت بــرد دعــوى‬\n      ‫املدعيــة شــركة ‪ ...‬املذكــورة اعــاه علــى املدعــى عليهمــا ‪.....‬و ‪ ...‬لعــدم‬\n      ‫ثبــوت اســتالمهما ملبلــغ الشــيكني املذكوريــن اعــاه وافهمــت املدعــى‬\n      ‫عليــه املذكــور اعــاه بــان لــه ان يقيــم دعــواه علــى املدعــو ‪ ...‬متــى‬\n      ‫رغــب ذلــك حكمــا افهمتــه اجلميــع باملجلــس الشــرعي فقــرروا عــدم‬\n      ‫قناعتهــم بــه مــا عــدا املدعــى عليهــم ‪...‬و‪ ...‬و‪ ...‬املذكوريــن اعــاه فقــد‬\n      ‫قــرروا القناعــة باحلكــم وافهمــت املعترضــن علــى احلكــم املذكوريــن‬\n      ‫اعــاه بــأن عليهــم مراجعــه احملكمــة بعــد عشــرة ايــام الســتالم صــورة‬\n      ‫مــن صــك احلكــم واالعتــراض عليــه خــال ثالثــن يومــا مــن تاريــخ‬\n      ‫اســتالمهم صــورة صــك احلكــم واذا مضــى ثالثــون يومــا علــى تســجيل‬\n      ‫صــك احلكــم ولــم يقدمــوا اعتراضهــم عليــه ســقط حقهــم يف االعتــراض‬\n      ‫واصبــح احلكــم مكتســب القطعيــة وغيــر خاضــع للتمييــز ففهمــوا ذلــك‬\n      ‫وامــرت بإخــراج صــك مبوجبــه ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                  ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/06/25‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ثــم عــادت إلينــا املعاملــة مــن محكمــة االســتئناف‬\n      ‫مبكــة املكرمــة وبرفقهــا صــك احلكــم مظهــرا عليــه بالتصديــق‬\n\n\n‫‪139‬‬\n\f‫مــن الدائــرة اجلزائيــة الرابعــة مبحكمــة االســتئناف مبكــة املكرمــة‬\n‫بالقــرار رقــم ‪ 3422887‬يف ‪1434/1/26‬ه ـ وهــذا نصــه بعــد املقدمــة ‪:‬‬\n‫وبدراســة احلكــم وصــورة ضبطــه والالئحتــن االعتراضيتــن تقــررت‬\n‫املوافقــة علــى احلكــم وبــاهلل التوفيــق ‪ ،‬وعليــه أمــرت باحلــاق ذلــك‬\n‫بضبطــه وســجله وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                          ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/2/24‬ه ـ ‪.‬‬\n\n\n\n\n                                                                               ‫‪140‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":128,"source_page_end":140,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"7786c42a3bfc0f3d4915da13f2bf3f08f451a03827e02067107d4b6e91d3bcc9","normalized_text_hash":"5e43bcf6f1843a2209de1b46e6a0c10d864eef58a8e9b4d3ddc7af541bd8d7ae","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p128-33316247"},{"id":"ad9998b4-d967-57d5-840c-b806c8947b69","document_type":"judgment","category":"judicial","subcategory":"general","title":"قيمة مسروق -املطالبة برد قيمة جواالت مسروقة -إقرار املدعى عليهما املصدق شرعا -وجوب رد العن املسروقة على مالكها إذا كانت باقية -ورد قيمتها إذا كانت تالفة -أو مثلها إذا كانت مثلية -تقدير قيمة املسروق عن طريق قسم اخلبراء -احلكم برد قيمة اجلواالت املسروقة -تنازل املدعى عن احلق احملكوم به.","document_number":"348978","case_number":"33293198","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف مبنطقة مكة ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/11","year":"1434","subject":"قيمة مسروق -املطالبة برد قيمة جواالت مسروقة -إقرار املدعى عليهما املصدق شرعا -وجوب رد العن املسروقة على مالكها إذا كانت باقية -ورد قيمتها إذا كانت تالفة -أو مثلها إذا كانت مثلية -تقدير قيمة املسروق عن طريق قسم اخلبراء -احلكم برد قيمة اجلواالت املسروقة -تنازل املدعى عن احلق احملكوم به.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"        ‫تاريخه‪1434/1/11 :‬هـ‬\n                        ‫ُ‬                ‫َر ْق ُم َّ‬\n                             ‫الص ِّك‪348978 :‬‬\n                          ‫َر ْق ُم الدعوى‪33293198 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 3435048‬تاريخه‪1434/2/11:‬هـ‬\n\n\n      ‫قيمــة مســروق ‪ -‬املطالبــة بــرد قيمــة جــواالت مســروقة ‪ -‬إقــرار املدعــى‬\n      ‫عليهمــا املصــدق شــرعا ‪ -‬وجــوب رد العــن املســروقة علــى مالكهــا إذا‬\n      ‫كانــت باقيــة ‪ -‬ورد قيمتهــا إذا كانــت تالفــة ‪ -‬أو مثلهــا إذا كانــت‬\n      ‫مثليــة ‪ -‬تقديــر قيمــة املســروق عــن طريــق قســم اخلبــراء ‪ -‬احلكــم بــرد‬\n           ‫قيمــة اجلــواالت املســروقة ‪ -‬تنــازل املدعــى عــن احلــق احملكــوم بــه‪.‬‬\n\n\n\n\n             ‫‪ .1‬قوله صلى اهلل عليه وسلم «على اليد ما أخذت حتى تؤديه»‪.‬‬\n      ‫‪ .2‬قــال ابــن رشــد ‪« :‬إذا اجتمــع القــوم يف الغصــب أو الســرقة أو احلرابــة‬\n      ‫بعضــا‪،‬‬\n          ‫فــكل واحــد منهــم ضامــن بجميــع مــا أخــذوه‪ ،‬ألن بعضهــم قـ ّوى ً‬\n      ‫جميعــا‪ ،‬وإن ولــي‬\n                    ‫ً‬      ‫كالقــوم املجتمعــن علــى قتــل رجــل فيقتلــون بــه‬\n                                                           ‫القتــل أحدهــم وحــده»‪.‬‬\n      ‫‪ .3‬قــال ابــن قدامــة رحمــه اهلل‪« :‬ال يختلــف أهــل العلــم يف وجــوب رد‬\n      ‫العــن املســروقة علــى مالكهــا إذا كانــت باقيــة‪ ،‬فأمــا إن كانــت تالفــة‪،‬‬\n      ‫فعلــى الســارق رد قيمتهــا‪ ،‬أو مثلهــا إن كانــت مثليــة‪ ،‬قطــع أو لــم‬\n                         ‫يقطــع‪ ،‬موســر ًا كان أو معســر ًا» املغنــي‪.)274/10( :‬‬\n      ‫‪ .4‬جــاء يف التشــريع اجلنائــي لعبــد القــادر عــودة «إذا كان الســارق قــد‬\n      ‫تعــاون مــع غيــره يف إخــراج الســرقة ‪ ،‬فــكل مــن لزمــه القطــع يف الســرقة‬\n      ‫كان مســئو ًال بالتضامــن عمــا أخــذه غيــره ممــن وجــب عليهــم القطــع‪.‬‬\n\n\n‫‪141‬‬\n\f‫ادعــى املدعــي بالوكالــة عــن مؤسســة جتاريــة أن يف ذمــة املدعى عليهما‬\n‫ملوكلتــه خمســة وتســعني ألفــا وســبعمائة وأربعــة وأربعــن ريــاال قيمــة‬\n‫أربعــة وثالثــن جــوا ًال مــن نــوع آي فــون‪ ،‬وذلــك لقيــام املدعــى عليهمــا‬\n‫بســرقة هــذه األجهــزة مــن الشــركة الشــاحنة ‪ ،‬وقــد أقــرت الشــركة‬\n‫أن هــذه اجلــواالت للمؤسســة املدعيــة ‪ ،‬وطلــب إلزامهمــا بدفــع املبلــغ‬\n‫املذكور‪ ،‬جرى الرجوع إلقرار الشــركة املذكورة يف الصك الصادر‬\n‫برقــم ‪ ....‬وتاريــخ ‪ ،.....‬وإقــرار الشــركة أيضـ ًا املرفــق باملعاملــة املتضمــن‬\n‫أن األجهــزة املتعلقــة بهــذه الدعــوى تخــص فــرع املؤسســة املدعيــة وتنــازل‬\n‫الشــركة الناقلــة عــن الدعــوى لصالــح املؤسســة املذكــورة‪ ،‬بعــرض‬\n‫الدعــوى علــى املدعــى عليهمــا أنكــرا الدعــوى جملــة وتفصيال‪ ،‬بســؤال‬\n‫املدعــى وكالــة عــن بينتــه علــى دعــواه‪ ،‬أجــاب أن بينتــه مــا جــاء يف‬\n‫أوراق املعاملــة مــن إقــرار املدعــى عليهمــا ‪ ،‬جــرى االطــاع علــى إقــراري‬\n‫املدعــى عليهمــا املصدقــن شــرع ًا ‪ ،‬جــرى االطــاع علــى الصــك الصــادر‬\n‫برقــم ‪ .....‬وتاريــخ ‪ .....‬املتضمــن تقديــر اجلــوال الواحــد مــن أهــل اخلبــرة‬\n‫بألفــن وثمامنائــة وســتة عشــر ريــاال ‪ ،‬ويصبــح مجمــوع قيمــة اجلــواالت‬\n‫خمســة وتســعني ألفــا وســبعمائة وأربعــة وأربعــن ريــاال‪ ،‬بنــاء علــى‬\n‫مــا جــاء يف إقــراري املدعــى عليهمــا املصدقــن شــرعا‪ ،‬ومــا جــاء يف‬\n‫أقوالهمــا يف التحقيقــات‪ ،‬مــا جــاء يف تقريــر أهــل اخلبــرة بتقديــر قيمــة‬\n‫اجلــواالت املســروقة‪ ،‬لقولــه صلــى اهلل عليــه وســلم «علــى اليــد مــا أخــذت‬\n‫حتــى تؤديــه»‪ ،‬لــذا مت احلكــم علــى املدعــى عليهمــا بدفــع مبلــغ وقــدره‬\n‫خمســة وتســعون ألفــا وســبعمائة وأربعــة وأربعــون ريــاالً‪ ،‬للمدعــي أصالــة‬\n\n\n                                                                                       ‫‪142‬‬\n\f      ‫‪ -‬بعــرض احلكــم علــى املدعــي وكالــة قــرر القناعــة وقــرر املدعــى‬\n      ‫عليهمــا عدمهــا ‪ -‬بعــد رفــع احلكــم حملكمــة االســتئناف متــت املصادقــة‬\n      ‫عليــه ‪ -‬قــرر وكيــل الشــركة املدعيــة التنــازل عــن حــق موكلــه لوجــه‬\n                                                                       ‫اهلل تعالــى ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة اجلزائيــة يف محافظــة جدة‪/‬املســاعد برقــم ‪33293198‬‬\n      ‫وتاريــخ ‪ 1433/04/26‬ه ـ املقيــدة باحملكمــة برقــم ‪ 33403935‬وتاريخ‬\n      ‫‪ 1433/03/01‬ه ـ ففــي يــوم األحــد املوافــق‪ 1434/01/11‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة (‪ )10:00‬لســماع دعــوى ‪ ..........‬ضــد ‪ .........‬وفيهــا‬\n      ‫حضــر ‪ ...........‬ســعودي اجلنســية مبوجــب بطاقــة الهويــة الوطنيــة رقــم‬\n      ‫‪............‬الوكيــل الشــرعي عــن ‪ ................‬أصالــة عــن نفســه وبصفتــه‬\n      ‫صاحــب مؤسســة ‪...........‬التجاريــة برقــم ‪..........‬وتاريــخ ‪1433/07/14‬ه ـ‬\n      ‫املخولــة لــه املطالبــة وإقامــة الدعــاوي املرافعــة واملدافعــة ســماع الدعــاوي‬\n      ‫والــرد عليهــا اإلقــرار واإلنــكار والصلــح التنــازل طلــب اليمــن ورده‬\n      ‫واالمتنــاع عنــه وإحضــار الشــهود والبينــات والطعــن فيهــا الطعــن يف‬\n      ‫التزويــر تعيــن اخلبــراء واحملكمــن وادعــى علــى احلاضريــن معــه يف‬\n      ‫هــذه اجللســة ‪ ..........‬مينــي اجلنســية مبوجــب بطاقــة بديلــه رقــم ‪2/.........‬‬\n      ‫ا يف‬ ‫و ‪ ..........‬مينــي اجلنســية مبوجــب بطاقــة بديلــه رقــم ‪ 2/.........‬قائ ـ ً‬\n      ‫حتريــر دعــواه إن ملوكلتــي يف ذمــة املدعــى عليهمــا احلاضريــن معــي‬\n      ‫يف هــذه اجللســة مبلــغ وقــدره خمســة وتســعون ألــف وســبعمائة وأربعــة‬\n\n‫‪143‬‬\n\f‫وأربعــون ريــال ‪95744‬ريــال وذلــك قيمــة أربعــة وثالثــون جــوال مــن‬\n‫نــوع آي فــون وذلــك لقيــام املدعــى عليهمــا بســرقة هــذه األجهــزة مــن‬\n‫شــركة ‪ ..............‬الشــركة الشــاحنة وذلــك بتاريــخ ‪1430/01/02‬ه ـ‬\n‫وقــد أقــرت الشــركة يف مجلــس احلكــم عنــد الشــيخ ‪ ............‬بــأن‬\n‫هــذه اجلــواالت لنــا وذلــك بتاريــخ ‪1432/7/25‬ه ـ ومبوجــب إقرارهــم‬\n‫املرفــق باملعاملــة أطلــب إلزامهمــا بدفــع هــذا املبلــغ ملوكلتــي علم ـ ًا بــأن‬\n‫احلــق العــام قــد نظــر مــن قبــل فضيلــة الشــيخ ‪ ...........‬وصــدر فيــه القــرار‬\n‫الشــرعي رقــم ‪/5/08‬م وتاريــخ ‪ 1432/01/07‬واملصــدق مــن محكمــة‬\n‫االســتئناف مبنطقــة مكــة برقــم ‪ 3381504‬وتاريــخ ‪1433/02/14‬هــذه‬\n‫دعــواي وبالرجــوع إلــى إقــرار الشــركة الناقلــة شــركة ‪............‬‬\n‫بواســطة وكيلهمــا ‪ ...............‬الوكيــل الشــرعي عــن شــركة ‪.......‬‬\n‫القابضــة مبوجــب الوكالــة برقــم ‪66690‬يف ‪1431/9/15‬ه ـ واملخولــة‬\n‫لــه يف وكالتــه حــق اإلقــرار وقــرر أن الشــركة رفعــت الدعــوى بصفتهــا‬\n‫الشــركة الناقلــة وصــادق علــى ذلــك وكيــل مؤسســة ‪ ...‬كمــا جــاء‬\n‫يف الصــك الصــادر برقــم ‪/5/80‬م وتأريــخ ‪1432/01/07‬ه ـ وإقرارهــم‬\n‫املرفــق باملعاملــة املتضمــن أن األجهــزة املتعلقــة بهــذه الدعــوى تخــص‬\n‫فــرع مؤسســة ‪ ..........‬وتنــازل الشــركة الناقلــة عــن الدعــوى لصالــح‬\n‫مؤسســة ‪ ..........‬وعليــه توقيــع وكيــل شــركة ‪ ...‬ووكيــل مؤسســة‬\n‫‪ .........‬وبعــرض الدعــوى علــى املدعــى عليهمــا وســؤالهما اجلــواب أجابــا‬\n‫ا‬‫قائلــن مــا ذكــره املدعــى وكالــة كلــه غيــر صحيــح جملــة وتفصي ـ ً‬\n‫ا مــا‬‫هكــذا أجابــا وبســؤال املدعــى وكالــة عــن بينتــه أجــاب قائ ـ ً‬\n‫جــاء يف أوراق املعاملــة مــن إقرارهمــا عليــه جــرى اطالعــي علــى إقــرار‬\n‫املدعــى عليــه ‪ .............‬علــى املصــدق شــرعا املرفــق باملعاملــة لفــة رقــم‬\n\n\n                                                                                         ‫‪144‬‬\n\f      ‫(‪ )122‬صحيفــة رقــم (‪ )2-1‬واملتضمــن مــا نصــه أنــه يف حوالــي الســاعة‬\n      ‫الثانيــة ظهــرا يــوم األثنــن املوافــق ‪1430/1/15‬ه ـ أثنــاء تواجــدي يف‬\n      ‫مطعــم ومطبــخ ‪ ...‬يف حــي ‪ .....‬لغــرض شــراء وجبــة غــداء قابلــت أحــد‬\n      ‫األشــخاص ويدعــي ‪ ............../‬صومالــي اجلنســية والــذي أعرفــه مــن‬\n      ‫الســابق وأبلغنــي أنــه يوجــد لديــه أجهــزة جــواالت جديــدة يرغــب يف‬\n      ‫بيعهــا وســألني عمــا إذا كنــت اعــرف أحــد يرغــب يف شــرائها وأخبرتــه‬\n      ‫أننــي ال أعــرف أحــد وقــام هــو بــدوره باالتصــال علــى املدعــو ‪............/‬‬\n      ‫مينــي اجلنســية وطلــب منــه احلضــور إلينــا وبعــد حضــوره ركبنــا ســويا يف‬\n      ‫ســيارة املدعــو ‪ ............/‬وتوجهنــا إلــى أحــد محــات اجلــواالت يف شــارع‬\n      ‫‪ ...‬وهــو محــل ‪ .....‬لالتصــاالت وقــام املدعــو‪ ............. /‬بدخــول احملــل‬\n      ‫ومعــه أجهــزة اجلــواالت ورجــع إلينــا وأبلغنــا بأنــه ثمــن األجهــزة غيــر‬\n      ‫متوفــر بالكامــل وســوف يكتمــل بعــد ســاعة تقريبــا وانتظرنــا خــارج‬\n      ‫احملــل وبعــد ذلــك دخلــت احملــل مــع املدعــو‪ ......... /‬وقــام العامــل باحملــل‬\n      ‫بتســليم املدعــو‪ ............ /‬مبلــغ مالــي وقــدرة (‪ )60000‬ســتون ألــف‬\n      ‫ريــال وقــام بعدهــا بتســليمها لــي وخرجنــا مــن احملــل ســوا وركبنــا مــع‬\n      ‫املدعــو‪ ...../‬يف ســيارته مــن نــوع‪ ........‬اللــون أبيــض ال أعــرف رقــم لوحتهــا‬\n      ‫وقــام بإيصالــي إلــي ســيارتي يف حــي ‪ .....‬بجــوار مطعــم ‪ ...‬وســلمني مبلــغ‬\n      ‫مالــي وقــدره (‪ )1700‬ريــال ســعودي كمســاعده لــي كونــي عاطــل عــن‬\n      ‫العمــل حاليــا وبعــد ذلــك ذهــب املدعــو ‪ ............./‬وبرفقــة املدعــو ‪......./‬‬\n      ‫إلــي جهــة غيــر معروفــة لــدي وأخــذت ســيارتي وتوجهــت إلــى منزلــي بعــد‬\n      ‫ذلــك هــذا إقــراري وعليــه أوقــع كمــا جــرى اطالعــي علــى إقــرار املدعــى‬\n      ‫عليــه ‪ ...‬املصــدق شــرعا واملرفــق باملعاملــة لفــة رقــم (‪ )129‬صحيفــة رقــم‬\n      ‫(‪ )4/3/2‬واملتضمــن مــا نصــه أقــر وأعتــرف أنــا املدعــو ‪.................. /‬‬\n\n\n‫‪145‬‬\n\f‫مينــي اجلنســية ‪ 34‬ســنه وأقيــم يف البــاد بطريقــة غيــر مشــروعه بأنــه‬\n‫ســبق وأن مت القبــض علــي يف عــدة قضايــا جنائيــة كان آخرهــا عــام‬\n‫‪1426‬ه ـ ومت ابعــادي عــن البــاد علــى أثرهــا وقدمــت إلــي الســعودية‬\n‫قبــل حوالــي شــهرين بطريقــة التهريــب عبــر احلــدود الســعودية اليمنيــة‬\n‫وقبــل حوالــي شــهر وعشــرون يومــا قمــت بشــراء إقامــة مــزورة حتمــل‬\n‫صورتــي واســم ‪ ...........‬مينــي اجلنســية واســتخدمتها كإثبــات للهويــة‬\n‫ولقــد اشــتريتها مــن شــخص باكســتاني اجلنســية ال أعرفــه وال أســتطيع‬\n‫اإلرشــاد عليــه مقابــل مبلــغ مالــي وقــدرة (‪ )300‬ثالثمائــة ريــال ويف يــوم‬\n‫األثنــن ‪1430/1/15‬ه ـ اتصــل بــي املدعــو‪ .............. /‬مينــي اجلنســية‬\n‫وأبلغنــي أنــه يوجــد لديــه عــدد (‪ )33‬جهــاز جــوال نــوع ‪ .....‬جديــدة‬\n‫ويرغــب يف بيعهــا وقمــت بــدوري باالتصــال علــى املدعــو‪ .............. /‬مينــي‬\n‫اجلنســية والــذي يعمــل مبحــل ‪ .............‬لالتصــاالت بحــي ‪ .....‬بشــارع ‪.....‬‬\n‫وأبلغتــه باألجهــزة املوجــودة فقــال لــي أنــه ســوف يقــوم بشــراء األجهــزة‬\n‫وذكــرت لــه أنهــا مســروقة فقــال لــي ال يهــم ســوف اشــتريها وأنــه يقــوم‬\n‫بشــراء األجهــزة املســروقة وبالفعــل توجهــت إلــي احملــل الــذي يعمــل بــه‬\n‫أنــا واملدعــو‪ .................. /‬وشــخص اخــر صومالــي اجلنســية ال أعرفــه‬\n‫مــن الســابق وكانــت األجهــزة بحــوزة املدعــو‪ .............. /‬ومت تســليم‬\n‫املدعــو‪ ............. /‬عــدد ثالثــون جهــاز جــوال وقــام بتجربــة بعضــا منهــا‬\n‫ودفــع للمدعــو ‪ ................. /‬مبلــغ(‪ )60900‬ســتون ألــف وتســعمائة ريــال‬\n‫ســعودي وغــادرت أنــا واملدعــو‪ ............./‬احملــل وقــام بتســليمي املذكــور‬\n‫مبلــغ (‪ )1000‬ألــف ريــال لتوســطي يف بيــع األجهــزة ورجعــت إلــي محــل‬\n‫‪ ..........‬مــرة أخــرى وقــام املدعــو‪ ................ /‬بتســليمي مبلــغ (‪)1700‬‬\n‫الــف وســبعمائة ريــال كأتعــاب لتوســطي يف بيــع األجهــزة أيضــا ويف يــوم‬\n\n\n                                                                                      ‫‪146‬‬\n\f      ‫اخلميــس املوافــق ‪1430/1/18‬ه ـ توجهــت أنــا واملدعــو‪ ................ /‬مــرة‬\n      ‫اخرى إلى محل ‪ ...‬لالتصاالت ومت بيع عدد (‪ )3‬أجهزة من نفس النوع‬\n      ‫علــى املدعــو‪ .................../‬وأســتلم املدعــو‪ .............. /‬مبلــغ (‪)6000‬‬\n      ‫ســتة أالف ريــال ســعودي ويف يــوم اخلميــس املوافق‪1430/1/25‬ه ـ قــام‬\n      ‫املدعــو ‪ ................./‬بتســليمي عــدد خمســة ســتون وجهــه غــاف جــوال‬\n      ‫متنوعــة لبيعهــا وال اعلــم مــن أيــن حصــل عليهــا وتوجهــت إلــى محــل ‪.........‬‬\n      ‫التصــاالت وقمــت ببيعهــا مببلــغ (‪ )200‬ريــال وقــد مت القبــض علــي يف‬\n      ‫نفــس اليــوم مــن قبــل دويــات األمــن بعــد اإلبــاغ علــي مــن ‪ ......‬املذكــور‬\n      ‫وشــخص آخــر معــه ولقــد مت القبــض علــي وبرفقتــي شــخص مرافــق‬\n      ‫لــي يدعــى‪ ................./‬صومالــي اجلنســية الــذي قــام بإيصالــي إلــى‬\n      ‫محــل ‪ ......‬لالتصــاالت كمــا أقــر بأننــي أعــرف املدعــو‪ ............. /‬منــذ‬\n      ‫حوالــي ســنتني واعــرف املدعــو ‪ .................. /‬منــذ حوالــي شــهر تقريبــا‬\n      ‫واملدعــو‪ .................. /‬منــذ حوالــي أســبوعني هــذا إقــرار واعتــراف منــي‬\n      ‫بذلــك وعليــه أوقــع وبســؤال املدعــى باحلــق اخلــاص وكالــة عــن تقديــر‬\n      ‫قيمــة اجلــواالت املســروقة أجــاب قائــا ســبق وأن أحضرنــا عنــد فضيلــة‬\n      ‫الشــيخ ‪ ...........‬مقدريــن مــن أهــل اخلبــرة وهــي مســجلة بصــك احلكــم‬\n      ‫الصــادر منــه هكــذا أجــاب عليــه جــرى اطالعــي علــى الصــك الصــادر‬\n      ‫مــن قبــل فضيلــة الشــيخ برقــم ‪/5/80‬م وتاريــخ ‪1432/01/07‬ه ـ‬\n      ‫املتضمــن طلــب فضيلتــه مــن املدعــى مقدريــن مــن أهــل اخلبــرة فاحضــر‬\n      ‫كل مــن ‪ ..................‬مصــري اجلنســية إقامــة رقــم ‪ ...............‬و‪..............‬‬\n      ‫اجلنســية إقامــة رقــم ‪ ............‬وقــرر كل منهمــا إننــا نعــرف جــواالت‬\n      ‫املدعــي أصالــة نــوع آي فــون ‪16‬قيقــا ويقــدر الواحــد بألفــن وثمامنائــة‬\n      ‫وســتة عشــر ريــال ‪ 2816‬يصبــح مجمــوع قيمــة اجلــواالت خمســة وتســعني‬\n\n\n‫‪147‬‬\n\f‫ألــف وســبعمائة وأربعــة وأربعــن ريــال عليــه وبنــاء علــى مــا تقــدم مــن‬\n‫الدعــوى واإلجابــة ونظــرا ملــا جــاء يف إقــرار املدعــى عليهمــا املصــدق‬\n‫شــرعا ومــا جــاء يف أقوالهمــا يف التحقيقــات وملــا جــاء يف تقريــر أهــل‬\n‫اخلبــرة بتقديــر قيمــة اجلــواالت املســروقة وملــا جــاء يف املغنــي البــن قدامــه‬\n‫مــن قولــه‪ »:‬ال يختلــف أهــل العلــم يف وجــوب رد العــن املســروقة علــى‬\n‫مالكهــا إذا كانــت باقيــة‪ ،‬فأمــا إن كانــت تالفــة‪ ،‬فعلــى الســارق رد‬\n‫قيمتهــا‪ ،‬أو مثلهــا إن كانــت مثليــة‪ ،‬قطــع أو لــم يقطــع‪ ،‬موســر ًا كان‬\n‫أو معســر ًا (‪ »)274/10‬وجــاء يف التشــريع اجلنائــي لعبدالقــادر عــودة‬\n‫«إذا كان الســارق قــد تعــاون مــع غيــره يف إخــراج الســرقة ‪ ،‬فــكل مــن‬\n‫لزمــه القطــع يف الســرقة كان مســئو ًال بالتضامــن عمــا أخــذه غيــره ممن‬\n‫وجــب عليهــم القطــع» قــال ابــن رشــد ‪« :‬إذا اجتمــع القــوم يف الغصــب أو‬\n‫الســرقة أو احلرابــة فــكل واحــد منهــم ضامــن بجميــع مــا أخــذوه‪ ،‬ألن‬\n‫بعضــا‪ ،‬كالقــوم املجتمعــن علــى قتــل رجــل فيقتلــون بــه‬     ‫بعضهــم قـ ّـوى ً‬\n‫جميعــا‪ ،‬وإن ولــي القتــل أحدهــم وحــده» و لقولــه صلــى اهلل عليــه وســلم»‬ ‫ً‬\n‫علــى اليــد مــا أخــذت حتــى تؤديــه» عليــه فقــد حكمــت علــى املدعــى‬\n‫عليهمــا بدفــع مبلــغ وقــدره خمســة وتســعني ألــف وســبعمائة وأربعــة‬\n‫وأربعــن ريــال‪ 95744‬للمدعــن أصالــة وبعــرض احلكــم علــى املدعــن‬\n‫قــرر املدعــى وكالــه القناعــة وقــرر املدعــى عليهمــا عــدم القناعــة مــع‬\n‫االكتفــاء مبــا قــدم ســابقا مــن لوائــح اعتراضيــه وجــرى النطق باحلكم‬\n‫يف يــوم األحــد املوافــق ‪1434/1/11‬ه ـ وعلــى ذلــك جــرى التوقيــع وكان‬\n‫ختــام هــذه اجللســة الســاعة (‪ )11:00‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n      ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/1/11‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...........‬القاضــي يف احملكمــة‬\n\n\n                                                                                         ‫‪148‬‬\n\f      ‫اجلزائيــة مبحافظــة جــدة ففــي يــوم األربعــاء املوافق‪1434/05/15‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة (‪ )11:00‬املتعلقــة بدعــوى ‪ .................‬ضــد‬\n      ‫‪ .................‬وفيهــا حضــر ‪ ................‬ســعودي اجلنســية مبوجــب بطاقــة‬\n      ‫الهويــة الوطنيــة رقــم ‪...........‬الوكيــل الشــرعي عــن ‪ ..............‬أصالــة عــن‬\n      ‫نفســه وبصفتــه صاحــب مؤسســة ‪..................‬التجاريــة برقــم ‪...............‬‬\n      ‫وتاريــخ ‪1433/07/14‬ه ـ املخولــة لــه املطالبــة وإقامــة الدعــاوي املرافعــة‬\n      ‫واملدافعــة ســماع الدعــاوي والــرد عليهــا اإلقــرار واإلنــكار والصلــح‬\n      ‫التنــازل طلــب اليمــن ورده واالمتنــاع عنــه وإحضــار الشــهود والبينــات‬\n      ‫ال‬\n       ‫والطعــن فيهــا الطعــن يف التزويــر تعيــن اخلبــراء واحملكمــن وقــرر قائ ً‬\n      ‫أن موكلتــي قــد تنازلــت عــن املبلــغ احملكــوم ملوكلتــي يف باطــن هــذا‬\n      ‫الصــك وقــدره خمســة وتســعون ألــف وســبعمائة وأربعــة وأربعــون ريــال‬\n      ‫‪ 95744‬ريــال وال تطالــب املدعــي عليهمــا بشــيء بخصــوص هــذه القضية‬\n      ‫وذلــك لوجــه اهلل تعالــى وبنــاء علــى ذلــك ومبــا أن وكيــل املدعــي قــرر‬\n      ‫تنــازل موكلتــه وهــو بكامــل أهليتــه املعتبــرة شــرعا و باالطــاع علــى‬\n      ‫وكالتــه وجدتهــا تخولــه حــق اإلقــرار لــذا فقــد ثبــت لــدي تنــازل وكيــل‬\n      ‫املدعيــة عــن دعواهــا جتــاه املدعــى عليهمــا ‪.........‬و‪ ...........‬بكامــل املبلــغ‬\n      ‫املدعــى بــه يف باطــن هــذا الصــك وأخليــت ســبيل املدعــى عليهمــا مــن‬\n      ‫هــذا املبلــغ املدعــى بــه يف باطــن الصــك وبهــذا تكــون القضيــة منتهيــة‬\n      ‫وأقفلــت اجللســة الســاعة ‪ 11 : 30‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n              ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/5/15‬ه ـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد فقــد‬\n      ‫جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة اخلامســة مبحكمــة االســتئناف‬\n      ‫يف منطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n\n\n‫‪149‬‬\n\f‫رئيــس احملكمــة اجلزائيــة مبحافظــة جــدة املســاعد برقــم ‪33/403935‬‬\n‫وتاريــخ ‪1434/1/28‬ه ـ املرفــق بهــا الصــك رقــم ‪ 348978‬وتاريــخ‬\n‫‪1434/1/11‬ه ـ الصــادر مــن فضيلــة الشــيخ‪ ............... /‬القاضــي‬\n‫باحملكمــة اجلزائيــة مبحافظــة جــدة املتضمــن دعــوى‪ ............ /‬وكالــة‬\n‫ضــد‪ ............ /‬مينــي اجلنســية ورفقــاه يف ســرقة جــواالت احملكــوم‬\n‫فيــه مبــا دون بباطــن الصــك ‪ ،‬وبدراســة الصــك وصــورة ضبطــه قررنــا‬\n‫املوافقــة علــى احلكــم باألكثريــة ‪ ،‬واهلل املوفــق وصلــى اهلل علــى نبينــا‬\n                                         ‫محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                  ‫‪150‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":141,"source_page_end":150,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"f1ea87e9fe15c847b78c2161d3aa33f1403b379e32c49003c497fef8d7d98880","normalized_text_hash":"027ce882eed94c2452a62cf365be4e1cad10d12040bf3a19e59dde53f1363a4c","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p141-348978"},{"id":"81f836a4-c202-59ed-8ebd-dd96a4ac7684","document_type":"judgment","category":"judicial","subcategory":"general","title":"مطالبة برد مسروق -اشتراك يف سرقة مبلغ مالي من منزل -عدم قبول الرجوع عن اإلقرار بحق آلدمي -ثبوت الدعوى -إلزام كل متهم مبا حصل عليه من املسروق .","document_number":"33368850","case_number":"33327793","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بعنيزة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/8/6","year":"1434","subject":"مطالبة برد مسروق -اشتراك يف سرقة مبلغ مالي من منزل -عدم قبول الرجوع عن اإلقرار بحق آلدمي -ثبوت الدعوى -إلزام كل متهم مبا حصل عليه من املسروق .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫تاريخه‪1433/8/6 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪33368850 :‬‬\n                          ‫َر ْق ُم الدعوى‪33327793:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                   ‫‪ 3453803‬تاريخه‪1434/3/2:‬هـ‬\n\n\n      ‫مطالبــة بــرد مســروق ‪ -‬اشــتراك يف ســرقة مبلــغ مالــي مــن منــزل ‪ -‬عــدم‬\n      ‫قبــول الرجــوع عــن اإلقــرار بحــق آلدمــي ‪ -‬ثبــوت الدعــوى ‪ -‬إلــزام كل‬\n                                        ‫متهــم مبــا حصــل عليــه مــن املســروق ‪.‬‬\n\n\n\n                        ‫‪ -1‬اإلنسان مؤاخذ بإقراره والسيما يف حق اآلدميني‪.‬‬\n      ‫‪ -2‬شــهادة الفســاق تقبــل علــى بعضهــم إذا لــم يدفــع الواحــد منهــم عــن‬\n                                ‫نفســه ضــررا ‪ ،‬كمــا ذكــره بعــض أهــل العلــم ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي بــأن املدعــى عليهــم اشــتركوا يف ســرقة مبلــغ مالــي مــن‬\n      ‫منزلــه وأنــه أعيــد لــه جــزء منــه؛ وطلــب إلزامهــم بإعــادة باقي املبلــغ املالي‬\n      ‫املســروق ‪ -‬أنكــر املدعــى عليهــم دعــوى املدعــي‪ -‬اطلعــت احملكمــة‬\n      ‫علــى حكــم صــادر منهــا بإدانــة املدعــى عليهــم يف الســرقة املذكــورة‬\n      ‫كمــا اطلعــت علــى إقراراتهــم باالشــتراك يف الســرقة ‪ -‬مــن املقــرر‬\n      ‫شــرعا أن الرجــوع عــن اإلقــرار يف حقــوق اآلدميــن غيــر مقبــول ‪ -‬لذلــك‬\n      ‫قضــت احملكمــة بإلــزام كل واحــد مــن املدعــى عليهــم بتســليم املبلــغ‬\n      ‫الــذي حتصــل عليــه مــن الســرقة إلــى املدعــي ‪ -‬قنــع املدعــي واملدعــى‬\n      ‫عليــه األول باحلكــم وعــارض عليــه املدعــى عليهمــا الثانــي والثالــث ‪-‬‬\n             ‫قــررت محكمــة االســتئناف باألكثريــة املصادقــة علــى احلكــم‪.‬‬\n‫‪151‬‬\n\f‫احلمــد هلل وحــده وبعــد يف يــوم الثالثــاء املوافــق ‪1433/5/25‬ه ـ لــدي‬\n‫أنــا ‪ ...‬القاضــي باحملكمــة العامــة بعنيــزة افتتحــت اجللســة يف الســاعة‬\n‫الثامنــة صباحــا للنظــر يف الدعــوى املقامــة مــن املقيــدة بهــذه احملكمــة‬\n‫برقــم ‪ 33887521‬يف ‪1433/5/11‬ه ـ احملالــة لنــا بشــرح فضيلة الرئيس‬\n‫وقــد حضــر يف هــذه اجللســة ‪ .......‬اجلنســية باإلقامــة رقــم وادعــى علــى‬\n‫احلاضريــن يف هــذه اجللســة األول ‪ /‬ســعودي اجلنســية مبوجــب ســجل رقــم‬\n‫والثانــي ‪ /‬ســعودي مبوجــب ســجل رقــم والثالــث ‪ /‬ســعودي مبوجــب‬\n‫ســجل رقــم قائــا يف حتريــر دعــواه لقــد قــام املدعــي عليهــم بســرقة‬\n‫مبلغــا مــن منزلــي الواقــع يف حــي متــروك بعنيــزة قــدره ثالثمائــة وثمانيــة‬\n‫االف ريــال قبــل ســنة تقريبــا وحكــم عليهــم بإثبــات إدانتهــم وصــدر قرار‬\n‫بذلــك مكتســب للقطعيــة ثــم ســلمت مبلغــا قــدره خمســة االف ريــال عــن‬\n‫طريــق شــرطة عنيــزة وأخبرونــي انــه جــزء مــن هــذا املبلــغ املدعــي بــه‬\n‫وذلــك قبــل عشــرين يــوم تقريبــا لــذا فإننــي اطلــب إلــزام املدعــي عليهــم‬\n‫بإعــادة املبلــغ املتبقــي مــن املبلــغ الذي ســرقوه مني وقــدره ثالثمائة وثالثة‬\n‫االف ريــال هــذه دعــواي وبســؤال املدعــي عليهــم عمــا جــاء يف دعــوى‬\n‫املدعــي أجــاب كل واحــد منهــم مبفــرده قائــا مــا ذكــره املدعــي كلــه‬\n‫غيــر صحيــح وجــرى منــي ســؤال املدعــي هــل لديــه بينــة علــى إقــرارات‬\n‫املدعــي عليهــم فأجــاب بقولــه أطلــب الرجــوع إلــى املعاملــة االساســية‬\n‫وإحضارهــا وفيهــا اإلقــرارات وجــرى منــي االطــاع علــى دفتــر التحقيــق‬\n‫مــن املعاملــة االساســية ومت االطــاع علــى إقــرارات املدعــي عليهــم فهــي‬\n‫كالتالــي إقــرار يف لفــة رقــم ‪ 39‬وفيــه مــا نصــه نعــم أنــا أقــر واعتــرف‬\n\n                                                                                     ‫‪152‬‬\n\f      ‫بأنــي قمــت بســرقة منــزل داخــل حــي البحيــرة وهــو بيــت‪ /‬مينــي اجلنســية‬\n      ‫صاحــب محــات وكان معــي كال مــن ‪ /‬و ‪ /‬كان دوري يف الســرقة‬\n      ‫املراقبــة خــارج املنــزل وإلهــاء مــن يأتــي ورمــي حجــر داخــل املنــزل وقــام‬\n      ‫بدخــول املنــزل كل مــن األول والثانــي وبعــد دخــول املنــزل بنصــف ســاعة‬\n      ‫خرجــوا مــن اجلهــة الثانيــة مــن املنــزل مــن فــوق الســور وكان معهــم مبالــغ‬\n      ‫ماليــه وقــام بإعطائــي مبلــغ مالــي وقــدره عشــرة االف ريــال فذهبــت إلــى‬\n      ‫املنــزل وحــدي وذهبــوا إلــى مــكان آخــر ال أعلــم أيــن وبعدهــا قامــوا‬\n      ‫بإقفــال جوالتهــم وهــذا هــو إقــرار منــي وعليــه أوقــع علمــا أنــه باقــي‬\n      ‫مــن املبلــغ خمســة االف ريــال ومت االطــاع علــى إقــرار يف لفــة رقــم ‪3‬‬\n      ‫وفيــه مــا نصــه أقــر أنــا ‪ /‬ســعودي اجلنســية أنــه قبــل فتــرة ال أذكــر‬\n      ‫بــأي يــوم وال أي تاريــخ ولكــن كنــت نائمــا يف منــزل والدتــي حضــر‬\n      ‫إلــى املدعــو ‪ /‬ومعــه املدعــو ‪ /‬ودخلــوا علــي وأنــا نائــم وصحونــي مــن‬\n      ‫النــوم ورجعــت وقلــت ألهلــي ســوف نذهــب لالســتراحة وبعــد خروجنــا‬\n      ‫نحــن الثالثــة واجتهنــا إلــى منــزل املدعــو ‪ /‬لقصــد الســرقة وقــام بالقفــز‬\n      ‫مــن الســور األمامــي للمنــزل ودخــل وبقيــت أنــا أراقــب يف أول الشــارع‬\n      ‫واملدعــو يف آخــر الشــارع وبعــد نصــف ســاعة جــاء ومعــه مبلــغ يف بطنــه‬\n      ‫وأخــرج مبلــغ وأعطانــي عشــرون الــف ريــال وإعطــاء املدعــو ‪ /‬ال أعــرف‬\n      ‫كــم وبعدهــا تفرقنــا وذهبــت ووضعــت يف املنــزل عنــد شــبك احلمــام يف‬\n      ‫البلــك وموجــود االن وبعدهــا ذهــب املدعــو‪ /‬مــع املدعــو ‪ /‬إلــى منــزل‬\n      ‫ولــد خالتــه وأعطــى املدعــو الــف ريــال والباقــي املبلــغ معــه هــذا إقــراري‬\n      ‫وعليــه أصــادق ومت االطــاع علــى إقــرار يف لفــة رقــم ‪ 9‬وفيــه مــا نصــه‬\n      ‫أقــر أنــا بأننــي أنــا وحيــث قــام ‪ /‬بدخــول منــزل ‪ /‬ومعــه ‪ /‬عــن طريــق‬\n      ‫الســور وســمعت صــوت كســر بــاب وبعــد نصــف ســاعة خرجــوا ومعهــم‬\n\n\n‫‪153‬‬\n\f‫مبالــغ ال أعلــم كــم ولكــن أعطانــي عشــرة االف ريــال وذهبــوا هــذا‬\n‫إقــراري وعليــه أصــادق فبنــاء علــى مــا تقــدم وحيــث طلــب املدعــي إلــزام‬\n‫املدعــي عليهــم بدفــع املبلــغ املدعــي بــه وحيــث أنكــر املدعــي عليهــم‬\n‫دعــوى املدعــي العــام وحيــث أنــه يوجــد إقــرار علــى املدعــى عليهــم‬\n‫بســرقة املبلــغ مــن بيــت املدعــي وحيــث أن اإلنســان مؤاخــذ بإقــراره‬\n‫والســيما يف حــق اآلدميــن حيــث أنــه ال يســقط حــق املدعــي بعــد إقــرار‬\n‫املدعــي عليهــم بالســرقة وحيــث أقــر املدعــي عليهــم أنــه اســتلم مــن ‪/‬‬\n‫مبلغــا وقــدره عشــرة االف ريــال وأعــاد أحــد أخوتــه خمســة االف ريــال‬\n‫وحيــث أقــر املدعــي عليــه ‪ /‬أنــه اســتلم مبلغــا وقــدره عشــرون الــف ريــال‬\n‫وحيــث أن املدعــي عليهــم ‪ /‬و ‪ /‬شــهد ‪ /‬بــأن مــن قــام بالقفــز وأخــذ املبلــغ‬\n‫هــو املدعــي عليــه ‪ /‬وحيــث أن شــهادة الفســاق تقبــل علــى بعضهــم كمــا‬\n‫ذكــره بعــض أهــل العلــم لذلــك كلــه فقــد حكمــت أوال بــأن يدفــع‬\n‫املدعــي عليــه ‪ /‬مبلغــا وقــدره خمســة االف ريــال وثانيــا حكمــت بــأن‬\n‫يدفــع املدعــي عليــه مبلغــا وقــدره عشــرون الــف ريــال وثالثــا حكمــت‬\n‫بــأن يدفــع املدعــي عليــه ‪ /‬مبلغــا وقــدره مائتــان وثمــان ســبعون ألــف ريــال‬\n‫هــذا مــا ظهــر لــي وبعرضــه عليهمــا قــرر املدعــي القناعــة وقــرر املدعــي‬\n‫عليــه ‪ /‬القناعــة وقــررا املدعــى عليهــم ‪ /‬وعــدم ‪ /‬القناعــة وأفهمــوا بــأن‬\n‫لهــم ثالثــون يومــا مــن تاريــخ صــدور الصــك لتقــدمي الئحــة اعتراضيــة‬\n‫وإال اكتســب احلكــم القطعيــة ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1433/7/30‬ه ويف يــوم‬\n‫االثنــن املوافــق ‪1434/02/04‬ه ـ افتتحــت اجللســة الســاعة ‪12:00:00‬‬\n‫وفيهــا عــادت املعاملــة مــن محكمــة االســتئناف بالقصيــم وبرفقتهــا‬\n‫القــرار رقــم ‪33471023‬يف ‪1433/11/30‬ه ـ الصــادر مــن قضاة الدائرة‬\n\n\n                                                                                       ‫‪154‬‬\n\f      ‫الثانيــة لتدقيــق القضايــا اجلزائيــة واملتضمــن املالحظــة علــى احلكــم‬\n      ‫الصــادر منــي مبــا يلــي أن فضيلتــه حكــم علــى املدعــى عليــه بــأن يدفــع‬\n      ‫للمدعــي املبلــغ املذكــور ولــم يذكــر مســتنده علــى مقــدار املبلــغ الــذي‬\n      ‫حكــم بــه كمــا أن مــا أشــار إليــه فضيلتــه مــن قبــول شــهادة الفســاق‬\n      ‫مخصــوص مبــا إذا لــم يدفــع عــن نفســه ضــررا كمــا يف هــذه القضيــة‬\n      ‫وإذا توجــه احلكــم علــى املدعــي عليهــم باملبلــغ فإنــه يلزمهــم متضامنــن‬\n      ‫إذا ثبــت اشــتراكهم بالســرقة مــع تنبيــه فضيلتــه إلــى إحلــاق مــا يــدل‬\n      ‫علــى أن املدعــي عليــه قــد قنــع باحلكــم وســدد املبلــغ احملكــوم بــه‬\n      ‫عليــه بالصــك وعليــه أجيــب أصحــاب الفضيلــة عــن املالحظــة االولــى أن‬\n      ‫املدعــي عليــه أقــر علــى نفســه بســرقة املــال ووضعــه معــه عنــد الســرقة ثم‬\n      ‫قــام بتوزيــع املــال علــى أصحابــه وبقــى املبلــغ الــذي حكــم عليــه بــه حتــت‬\n      ‫يــده لــذا فإنــه ملــزم بإعــادة مــا كان حتــت يــده مــن املــال املســروق وأمــا‬\n      ‫قبــول شــهادة بعضهــم علــى بعــض فإنــه يعضدهــا اعتــراف املدعــي عليــه‬\n      ‫بأنــه هــو مــن قــام بالســرقة وهــو مــن قــام بتوزيــع املــال علــى بقيــة رفقــاه‬\n      ‫فيكــون ملــزم بإعــادة املبلــغ الــذي اعتــرف أنــه بحوزتــه وأمــا إلزامهــم‬\n      ‫متضامنــن فــا وجــه لــه حيــث أن املدعــي عليــه ‪ .....‬هــو مــن قــام بالقفــز‬\n      ‫وتوزيــع املــال وحيــازة املبلــغ األكبــر الــذي حكمــت بــه عليــه وأمــا ‪.....‬‬\n      ‫فإنــه علــى صحيفــة خمســة وأربعــن مــن مجلــد الضبــط الثانــي عشــر‬\n      ‫اجلنائــي قــرر قناعتــه باحلكــم وســلم للمدعــى مبلغــا وقــدره عشــرون الف‬\n      ‫ريــال مبوجــب شــيك املســحوب علــى بنــك ‪ .....‬لــذا فإنــي مــا زلــت علــى‬\n      ‫حكمــي الســابق وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n      ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/2/4‬ه احلمــد هلل وحــده وبعــد فلــدي‬\n      ‫أنــا القاضــي يف احملكمــة العامــة بعنيــزة وبنــاء علــى املعاملــة احملالــة‬\n\n\n‫‪155‬‬\n\f‫لنــا مــن فضيلــة رئيــس احملكمــة العامــة بعنيــزة برقــم ‪33327793‬‬\n‫وتاريــخ ‪1433/05/11‬ه ـ املقيــدة باحملكمــة برقــم ‪ 33887521‬وتاريــخ‬\n‫‪ 1433/05/10‬ه ـ ففــي يــوم الســبت املوافــق‪ 1434/03/21‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 10:15:00‬وفيهــا عــادت املعاملــة مــن محكمــة‬\n‫االســتئناف بالقصيــم وبرفقتهــا قــرار التصديــق رقــم ‪ 3453803‬يف‬\n‫‪1434/3/2‬ه ـ الصــادر مــن قضــاة الدائــرة الثانيــة لتدقيــق القضايــا‬\n‫اجلزائيــة قــاض اســتئناف ختمــه وتوقيعــه وقــاض اســتئناف ختمــه‬\n‫وتوقيعــه ولــه وجهــة نظــر ورئيــس الدائــرة ختمــه وتوقيعــه وبــاهلل التوفيــق‬\n‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                               ‫‪1434/3/21‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                     ‫‪156‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":151,"source_page_end":156,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"9eaf435c386ba998b707def713f5fad73b893b0f32abcb07ebacf357902523bc","normalized_text_hash":"4e746bab8f61d840cd84363e5b492c89803043b4b9e89fa05e7cd14ce4053a83","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p151-33368850"},{"id":"f5a8b0f2-29fc-582f-a24a-bd112042cf82","document_type":"judgment","category":"judicial","subcategory":"general","title":"رد مسروق -سرقة مبلغ مالي من سيارة -إقرار أحد املدعى عليهم في ر د مثله إن عجز عن رد وإنكار البقية -املسروق إذا كان مثليا عينه -احلكم برد باقي املبلغ املسروق بعد خصم ما مت رده.","document_number":"34201455","case_number":"33386410","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/29","year":"1434","subject":"رد مسروق -سرقة مبلغ مالي من سيارة -إقرار أحد املدعى عليهم في ر د مثله إن عجز عن رد وإنكار البقية -املسروق إذا كان مثليا عينه -احلكم برد باقي املبلغ املسروق بعد خصم ما مت رده.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/4/29 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34201455 :‬‬\n                          ‫َر ْق ُم الدعوى‪33386410:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34253709‬تاريخه‪1434/6/27:‬هـ‬\n\n\n      ‫رد مســروق ‪ -‬ســرقة مبلــغ مالــي مــن ســيارة ‪ -‬إقــرار أحــد املدعــى عليهــم‬\n      ‫فيـ َـر ُّد مثلــه إن عجــز عــن رد‬\n                                       ‫وإنــكار البقيــة ‪ -‬املســروق إذا كان مثليــا ُ‬\n             ‫عينــه ‪ -‬احلكــم بــرد باقــي املبلــغ املســروق بعــد خصــم مــا مت رده‪.‬‬\n\n\n\n\n      ‫قــول النبــي صلــى اهلل عليــه وســلم‪( :‬لــو يعطــى النــاس بدعواهــم الدعــى‬\n               ‫نــاس دمــاء رجــال وأموالهــم ولكــن اليمــن علــى املدعــى عليــه) ‪.‬‬\n\n\n\n\n      ‫ادعــى وكيــل املدعــي علــى احلاضريــن معــه بــأن املدعــى عليهمــا األول‬\n      ‫والثامنــة قامــا بســرقة مبالــغ ماليــة مــن ســيارة موكلــه َّإبــان عملهمــا‬\n      ‫لديــه كســائق وخادمــة‪ ،‬ثــم قــام األول باقتســام تلــك املبالــغ مــع بقيــة‬\n      ‫املدعــى عليهــم‪ ،‬وبعــد القبــض عليهــم أعــادوا قيمــة جــزء منهــا للمدعــي‪،‬‬\n      ‫ولــذا فقــد طلــب إلزامهــم بإعــادة باقــي املبالــغ التــي ســرقت مــن موكله‪-‬‬\n      ‫أقــر األول بجميــع مــا جــاء يف دعــوى املدعــي جتاهــه وذكــر أنــه تصــرف‬\n      ‫بباقــي املبالــغ محــل الدعــوى‪ ،‬وأنكــر باقــي املدعــى عليهــم مــا جــاء يف‬\n      ‫الدعــوى إال أنهــم أقــروا ســوى الثامنــة باســتالم مبالــغ ماليــة مــن األول‪،‬‬\n      ‫ودفعــوا بأنهــم أعــادوا قيمتهــا للمدعــي‪ -‬املدعــي لــم يقــدم بينــة تثبــت‬\n      ‫دعــواه جتــاه املدعــى عليهــم وطلــب ميينهــم ‪ -‬عــدا األول‪ -‬علــى نفــي دعــواه‬\n‫‪157‬‬\n\f‫فأدوهــا طبــق مــا طلــب منهــم ‪ -‬قضــت احملكمــة بنــاء علــى إقــرار األول‬\n‫بإلزامــه بإعــادة مثــل املبلــغ الــذي ســرقه مــن املدعــي بعــد خصــم قيمــة‬\n‫اجلــزء الــذي ســبق أن أعــاده إليــه مــن املبلــغ اإلجمالــي‪ ،‬كمــا قضــت‬\n‫بصــرف النظــر عــن دعــوى املدعــي جتــاه بقيــة املدعــى عليهــم ‪ -‬قنــع‬\n‫املدعــي واملدعــى عليهــم باحلكــم عــدا األول فقــد عــارض عليــه ‪ -‬قــررت‬\n               ‫محكمــة االســتئناف املوافقــة علــى احلكــم باألكثريــة ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالرياض‪/‬املســاعد برقــم ‪ 33386410‬وتاريــخ ‪ 1433/06/08‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 331039024‬وتاريــخ ‪ 1433/06/03‬ه ـ ففــي‬\n‫يــوم الثالثــاء املوافــق‪ 1434/03/17‬ه ـ افتتحــت اجللســة الســاعة ‪11 : 15‬‬\n‫وفيهــا حضــر‪ ...../‬ســعودي مبوجــب الســجل املدنــي رقــم‪ )....( :‬بالوكالة‬\n‫عــن‪..... /‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‪ ).....(:‬مبوجــب‬\n‫الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة بجنــوب الريــاض برقــم‪:‬‬\n‫(‪ )3364510‬وتاريــخ ‪1433/5/3‬هـ ـ والتــي تخولــه املطالبــة واملرافعــة‬\n‫واملدافعــة واإلقــرار واإلنــكار والصلــح‪ ،‬كمــا حضــر حلضــوره ‪..... /1‬‬\n‫ســريالنكي هويــة رقــم‪...... /2 .).....( :‬ســريالنكي هويــة رقــم‪).....( :‬‬\n‫‪....... /3‬ســريالنكي هويــة رقــم‪...... /4 ).....( :‬ســريالنكي هويــة‬\n‫رقــم‪ ......./5 ،)....( :‬ســريالنكي (يحمــل بطاقــة نزيــل محكــوم‬\n‫رقــم‪ )..../../ ...:‬صــادرة مــن ســجن امللــز‪ ..../6 .‬ســريالنكي (يحمــل‬\n‫بطاقــة نزيــل محكــوم رقــم‪ ).../.../..:‬صــادرة مــن ســجن امللــز‪...... /7 .‬‬\n                                                                                   ‫‪158‬‬\n\f      ‫ســريالنكي هويــة رقــم‪..... /8 .).....( :‬ســريالنكية اجلنســية مبوجــب‬\n      ‫الهويــة رقــم‪ ).....( :‬واملعــرف بهــا مــن قبــل الســجانة حاملــة الســجل املدنــي‬\n      ‫رقــم‪ ،).....( :‬كمــا حضــر حلضورهــم املترجم املتعاون‪..... /‬ســريالنكي‬\n      ‫اجلنســية مبوجــب رخصــة اإلقامــة رقــم‪ ،).....( :‬وادعــى املدعــي وكالــة‬\n      ‫قائــا يف دعــواه‪ :‬إن املدعــى عليــه‪ ، .....‬واملدعــى عليهــا ‪ ...‬يعمــان‬\n      ‫لــدى موكلــي يف منزلــه ســائق وخادمــة‪ ،‬ويف تاريــخ ‪1432/3/23‬هـ ـ‬\n      ‫قامــا بالســرقة مــن موكلــي خمســة وخمســن ألــف جنيــه إســترليني‪،‬‬\n      ‫وخمســن ألــف يــورو‪ ،‬وذلــك مــن ســيارته ثــم قــام املدعــى عليــه بتوزيــع‬\n      ‫املبلــغ املســروق علــى زمالئــه املدعــى عليهــم البقيــة‪ ،‬وقــد أعــادوا مائــة‬\n      ‫ألــف ريــال ســعودي مــن املبلــغ املســروق وإننــي أطلــب يف دعــواي هــذه‬\n      ‫ســؤال املدعــى عليهــم وإلزامهــم بإعــادة املتبقــي مــن املبلــغ‪ ،‬والــذي يقــدر‬\n      ‫مببلــغ أربعمائــة ألــف ريــال ســعودي‪ ،‬هــذه دعــواي‪ .‬وبســؤال املدعــى‬\n      ‫عليهــم بواســطة املترجــم املذكــور أجــاب املدعــى عليــه‪ /‬بــأن كل مــا‬\n      ‫ذكــره املدعــي وكالــة يف دعــواه صحيــح فقــد ســرقت املبلــغ املذكــور‬\n      ‫بوحــدي وزوجتــي املدعــى عليهــا‪ /‬ال عالقــة لهــا بذلــك‪ ،‬وبعــد ســرقتي‬\n      ‫للمبلــغ ســلمت مــا يقــدر مبائــة ألــف للمدعــى عليــه ‪ ،‬والــذي قــام بتوزيــع‬\n      ‫املبلــغ علــى بقيــة املدعــى عليهــم احلاضريــن معــي يف مجلــس احلكــم‪،‬‬\n      ‫وأمــا املبلــغ املتبقــي والــذي يقــدر بأربعمائــة ألــف ريــال فســلمته لشــخص‬\n      ‫اســمه ‪ ،...‬وقــد ســافر يف نفــس اليــوم خــارج اململكــة‪ ،‬واملدعــى عليهــم‬\n      ‫احلاضريــن معــي قامــوا بإعــادة مــا اســتلموه‪ ،‬وهــو مائــة ألــف ريــال‪،‬‬\n      ‫واســتلمها املدعــي مــن الشــرطة‪ ،‬هــذا مــا لــدي‪ ،‬وأجــاب بقيــة املدعــى‬\n      ‫عليهــم عــدا املدعــى عليهــا بــأن مــا جــاء يف دعــوى املدعــي وكالــة غيــر‬\n      ‫صحيــح فلــم نســرق أي مبلــغ والصحيــح أن املدعــى عليــه‪ /‬اســتلم مــن‬\n\n\n‫‪159‬‬\n\f‫املدعــى عليــه مائــة ألــف ريــال ســعودي وقــام بتوزيعهــا علينــا وعنــد مــا‬\n‫قبــض علينــا قمنــا بإعادتهــا‪ ،‬هــذا مــا لدينــا‪ .‬وقالــت املدعــى عليهــا‬\n‫بواســطة املترجــم إن كل مــا ذكــره املدعــي وكالــة غيــر صحيــح‪،‬‬\n‫فأنــا لــم أســرق وال عالقــة لــي بذلــك‪ ،‬هــذا مــا لــدي‪ .‬وبعــرض ذلــك علــى‬\n‫املدعــي وكالــة قــال‪ :‬الصحيــح مــا ذكــرت يف دعــواي‪ ،‬وبســؤاله هــل‬\n‫لديــه بينــة علــى مــا ادعــى بــه مــن قيــام بقيــة املدعــى عليهــم عــدا األول‬\n‫باملشــاركة يف الســرقة‪ ،‬فقــال‪ :‬ليــس لــدي بينــة‪ ،‬ولكــن أطلــب ميينهــم‬\n‫علــى نفــي ذلــك وبعــرض ذلــك علــى املدعــى عليهــم عــدا األول اســتعدوا‬\n‫بــأداء اليمــن‪ ،‬وحلــف كل واحــد منهــم مبفــرده قائــا‪( :‬واهلل العظيــم‬\n‫أننــي لــم أشــارك املدعــى عليــه األول يف ســرقة املدعــي أصالــة‪ ،‬ولــم‬\n‫أســرق املبالــغ املدعــى بهــا وأن املدعــى عليــه هــو الــذي أعطانــي مبلــغ‬\n‫مائــة ألــف ريــال)‪ ،‬وبنــاء عليــه فقــد قــررت الكتابــة إلــى مؤسســة النقــد‬\n‫العربــي لتقديــر قيمــة املبلــغ املســلم للمدعــي مــن املبلــغ املســروق‪ ،‬وبــه‬\n‫رفعــت اجللســة‪ ،‬ويف جلســة أخــرى حضــر املدعــي وكالــه واملدعــى‬\n‫عليهــم جميعــا ولــم يحضــر املترجــم رغــم طلبــه وكان قــد جــرى منــا‬\n‫الكتابــة إلــى مؤسســة النقــد الســعودي باخلطــاب رقــم ‪34682630‬‬\n‫يف ‪1434/3/2‬ه ـ لتقديــر ‪ -1‬قيمــة املبلــغ خمســة وخمســن ألــف جنيــة‬\n‫إســترليني ‪ -2‬قيمــة مبلــغ خمســن ألــف يــورو وقــد وردنــا خطابهــم رقــم‬\n‫‪ 341000041129‬يف ‪1434/4/2‬ه ـ املتضمــن نفيدكــم بــأن قيمــة كل‬\n‫من ‪ -1 :‬مبلغ ‪ 55000‬جنية إســترليني تســاوي ‪ 322965/50‬ريال بســعر‬\n‫‪ 5.8721‬ريــال ســعودي‪ -2 .‬مبلــغ ‪ 50000‬ألــف يــورو تســاوي ‪254680/-‬‬\n‫ريــال بســعر ‪ 5.0936‬ريــال ســعودي ‪.‬أ‪.‬ه ـ ‪ ،‬ولعــدم حضــور املترجــم‬\n‫قــررت رفــع اجللســة ويف جلســة أخــرى حضــر املدعــي وكالــة‪..... /‬‬\n\n\n                                                                                       ‫‪160‬‬\n\f      ‫املدونــة هويتــه ووكالتــه ســابقا‪ ،‬كمــا حضــر املدعــى عليهــم جميعــا‪،‬‬\n      ‫وحضــره حلضورهــم املترجــم املتعــاون املدونــة هويتــه ســابقا‪ ،‬واملترجــم‬\n      ‫‪ .....‬ســريالنكي اجلنســية مبوجــب رخصــة اإلقامــة رقــم‪ ، ).....(:‬وبعرض‬\n      ‫مــا جــاء يف خطــاب مؤسســة النقــد العربــي الســعودي علــى املدعــى‬\n      ‫عليــه‪ ، /‬قــال‪ :‬إننــي ال أعلــم عــن تقديــر قيمــة اليــورو واالســترليني‪،‬‬\n      ‫هــذا مــا لــدي‪ .‬وبنــاء علــى مــا ســبق مــن الدعــوى واإلجابــة‪ ،‬ولقولــه صلــى‬\n      ‫اهلل عليــه وســلم (لــو يعطــى النــاس بدعواهــم الدعــى نــاس دمــاء رجــال‬\n      ‫وأموالهــم ولكــن اليمــن علــى املدعــى عليــه) ومبــا أن املدعــى عليــه ‪/‬‬\n      ‫‪.....‬قــد أقــر يف جوابــه بســرقة املبالــغ املدعــى بهــا‪ ،‬ومبــا أن بقيــة املدعــى‬\n      ‫عليهــم عــدا املدعــى عليهــا ‪ ...‬أنكــروا الســرقة ودفعــوا بتســليم مــا ســلم‬\n      ‫لهــم مــن أمــوال‪ ،‬وقدرهــا مئــة ألــف ريــال وقــد صــادق املدعــي وكالــة‬\n      ‫علــى مــا ذكــروه مــن تســليم املبلــغ املذكــور ومبــا أن املدعــى عليهــا‪/‬‬\n      ‫‪.....‬أنكــرت مــا جــاء يف الدعــوى‪ ،‬وقــررا املدعــي وكالــة عــدم وجــود‬\n      ‫بينــة لديــه‪ ،‬وطلــب ميــن بقيــة املدعــى عليهــم‪ ،‬ومبــا أن املدعــى عليهــم‬\n      ‫عــدا قــد أدوا اليمــن الشــرعية‪ ،‬علــى نفــي قيامهــم بالســرقة ومبــا أن‬\n      ‫املبلــغ املســلم للمدعــي‪ ،‬والــذي قــدره مئــة ألــف ريــال ســعودي يســاوي‬\n      ‫بالتقديــر املذكــور ســتة عشــر الــف وثمامنائــة وســتة وأربعــن يــورو وســتة‬\n      ‫وثالثــن باملئــة منــه لذلــك كلــه فقــد حكمــت علــى املدعــى عليــه بــأن‬\n      ‫يســلم للمدعــي خمســة وخمســن ألــف جنيــه اســترليني وثالثــة وثالثــن‬\n      ‫ألــف ومائــة وثالثــة وخمســن يــورو وثالثــة وســتني باملائــة مــن اليــورو‬\n      ‫وصرفــت النظــر عــن دعــوى املدعــي وكالــة جتــاه بقيــة املدعــى عليهــم‬\n      ‫وبــه حكمــت وبعــرض احلكــم عليهــم قــرر املدعــي وكالــة واملدعــى‬\n      ‫عليهــم عــدا القناعــة باحلكــم‪ ،‬أمــا املدعــى عليــه‪ ... /‬فقرر عــدم القناعة‬\n\n\n‫‪161‬‬\n\f‫باحلكــم‪ ،‬وطلــب رفــع معاملتــه إلــى محكمــة االســتئناف فأجبتــه إلــى‬\n‫طلبــه‪ ،‬وقــررت بعثهــا إلــى محكمــة االســتئناف‪ ،‬وأفهمتــه بأنــه ســوف‬\n‫يســلم صــورة مــن نســخة احلكــم يوم األربعاء املوافــق ‪1434/5/1‬ه ـ ـ وأن‬\n‫لــه مهلــة ثالثــن يومــا مــن تاريــخ االســتالم‪ ،‬لتقــدمي الئحتــه االعتراضيــة‬\n‫فــإذا انتهــت املهلــة ولــم يتقــدم بالئحتــه ســقط حقــه يف االعتــراض‪،‬‬\n‫وأصبــح احلكــم نافــذا‪ ،‬وبــه ختمــت اجللســة الســاعة‪ 30:12‬وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                ‫حــرر يف ‪ 1434/04/29‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء املوافــق‪ 1434/07/12‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 12:15‬وقــد عــادت املعاملــة مــن محكمــة‬\n‫االســتئناف باخلطــاب رقــم ‪ 341360101‬يف ‪1434/7/8‬ه ـ وبرفقهــا‬\n‫القــرار الصــادر مــن الدائــرة الثانيــة لتمييــز القضايــا اجلزائيــة يف‬\n‫محكمــة االســتئناف رقــم ‪ 34253709‬يف ‪1434/6/27‬ه ـ واملتضمــن‬\n‫وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة واوراق املعاملــة‬\n‫قررنــا باألكثريــة املصادقــة علــى احلكــم واهلل املوفق اه ـ ‪ ،‬وعليه جرى‬\n‫التهميــش مبوجبــه ‪ ،‬وبــه ختمــت اجللســة يف متــام الســاعة ‪ 12:20‬وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                 ‫حــرر يف ‪1434/7/12‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                     ‫‪162‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":157,"source_page_end":162,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"0a1c789a0eefa1dbc31f2f111794c42d7b78fec04e958bb551cbae55c009aeec","normalized_text_hash":"c95c0706affebd17f2058f0061b78bbf4e24c13d0e7a9a681a92534d0bceef05","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p157-34201455"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"723b5821-cc32-50e4-b218-79e86ac8b64e","document_type":"judgment","category":"judicial","subcategory":"general","title":"مطالبة برد مسروق -اشتراك يف سرقة من منزل -إقرار -عدم قبول الرجوع عن اإلقرار بحق اآلدمي -قبول قول املدعي مع ميينه -ثبوت الدعوى -احلكم على املتهمن رغم إقرار األول بعدم اشتراك الثاني معه يف السرقة ألن له إقرار سابق -القضاء بالقيمة األولى يف التحقيق دون ما زاد عنها يف االدعاء أمام المحكمة .","document_number":"34184985","case_number":"32251625","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/10","year":"1434","subject":"مطالبة برد مسروق -اشتراك يف سرقة من منزل -إقرار -عدم قبول الرجوع عن اإلقرار بحق اآلدمي -قبول قول املدعي مع ميينه -ثبوت الدعوى -احلكم على املتهمن رغم إقرار األول بعدم اشتراك الثاني معه يف السرقة ألن له إقرار سابق -القضاء بالقيمة األولى يف التحقيق دون ما زاد عنها يف االدعاء أمام المحكمة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/4/10 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34184985 :‬‬\n                    ‫َر ْق ُم الدعوى‪32251625:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34227940‬تاريخه‪1434/6/3:‬هـ‬\n\n\n‫مطالبــة بــرد مســروق ‪ -‬اشــتراك يف ســرقة مــن منــزل ‪ -‬إقــرار ‪ -‬عــدم‬\n‫قبــول الرجــوع عــن اإلقــرار بحــق اآلدمــي ‪ -‬قبــول قــول املدعــي مــع ميينــه‬\n‫‪ -‬ثبــوت الدعــوى ‪ -‬احلكــم علــى املتهمــن رغم إقرار األول بعدم اشــتراك‬\n‫الثانــي معــه يف الســرقة ألن لــه إقــرار ســابق ‪ -‬القضــاء بالقيمــة األولــى‬\n                 ‫يف التحقيــق دون مــا زاد عنهــا يف االدعــاء أمــام احملكمــة ‪.‬‬\n\n\n\n\n                             ‫قاعدة‪ :‬اليمني تشرع يف جانب أقوى املتداعيني‪.‬‬\n\n\n\n\n‫ادعــت املدعيــة بــأن املدعــى عليهمــا اشــتركا يف ســرقة أطقــم ذهــب‬\n‫وأجهــزة إلكترونيــة مــن منزلهــا؛ وطلبــت إلزامهمــا بتســليمها قيمة باقي‬\n‫املســروقات التــي لــم يتــم اســتعادتها منهمــا ‪ -‬أقــر املدعــى عليــه األول‬\n‫بالســرقة ودفــع بأنــه لــم يتصــرف يف املســروقات بــل اســتعادتها اجلهــات‬\n‫األمنيــة منــه وســلمتها للمدعيــة ســوى جــزء مــن الذهــب باعــه واســتعد‬\n‫بتســليم املدعيــة نفــس املبلــغ الــذي باعــه بــه وأمــا املدعــى عليــه الثانــي‬\n‫فقــد أنكــر دعــوى املدعيــة جتاهــه جملــة وتفصيــا إال أن لــه إقــرارا‬\n‫مصدقــا شــرعا بالســرقة ‪ -‬مــن املقــرر شــرعا أن املــرء مؤاخــذ بإقــراره‬\n‫وأن اليمــن تشــرع يف جانــب أقــوى املتداعيــن ‪ -‬وألن جانــب املدعيــة‬\n\n                                                                                       ‫‪112‬‬\n\f      ‫تقــوى بإقــرار املدعــى عليهمــا بالســرقة فيقبــل قولهــا فيمــا يتعلــق بقيمــة‬\n      ‫املســروقات باعتبــار أقــل قيمــة قدرتهــا للمســروقات ‪ -‬قــررت احملكمــة‬\n      ‫توجيــه اليمــن إلــى املدعيــة علــى صحــة دعواهــا فأدتهــا طبــق مــا طلــب‬\n      ‫منهــا ‪ -‬قضــت احملكمــة بإلــزام املدعــى عليهمــا بتســليم املدعيــة قيمــة‬\n      ‫املســروقات بعــد خصــم قيمــة مــا أعيــد إليهــا منهــا ‪ -‬عارضــت املدعيــة‬\n      ‫واملدعــى عليهمــا علــى احلكــم ‪ -‬قــررت محكمــة االســتئناف املوافقــة‬\n                                                                        ‫علــى احلكــم‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬رئيــس احملكمــة العامــة مبكــة‬\n      ‫املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة مبكــة املكرمــة برقــم ‪ 32251625‬وتاريــخ ‪1432/06/27‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 32786407‬وتاريــخ ‪1432/6/27‬ه ـ حضــرت‬\n      ‫‪ ......‬ســعودية اجلنســية مبوجــب الســجل املدنــي رقــم ( ) وادعــت علــى‬\n      ‫احلاضريــن معهــا يف مجلــس احلكــم ‪ .....‬اجلنســية مبوجــب اإلقامــة رقــم‬\n      ‫(اجلنســية مبوجــب البطاقــة البديلــة رقــم (‪ )513‬يرافقهــا العســكري‬\n      ‫قائلــة يف تقريــر دعواهــا ان املدعــى عليهمــا دخلــوا منزلــي وســرقوا‬\n      ‫ذهبــي املكــون مــن أربعــة وثالثــن بنجــر عيــار ‪ 21‬دقــة الدركتــر بناجــر‬\n      ‫عــدد واحــد وعشــرين حبــه عيــار ‪ 21‬وبناجــر ابــو منشــار عشــر حبــات‬\n      ‫عيــار ‪ 21‬وبناجــر دقــه عاديــه ســت حبــات وطقــم ذهــب اشــتريته مببلــغ‬\n      ‫ســبعة عشــر الــف وثمامنائــة وخمســة وســتني ريــال وطقــم ذهــب مببلــغ‬\n      ‫ســبعة االف وأربعمائــة ريــال وطقــم املــاس مببلــغ احــدى عشــر الــف‬\n      ‫ريــال وســاعة املــاس مببلــغ ثمانيــة آالف ريــال وطقمــن مزنــط احدهمــا‬\n‫‪113‬‬\n\f‫اشــتريته بأربعــة االف ريــال واآلخــر مببلــغ ثالثــة االف ريــال وخمســة‬\n‫أســاور عريضــة وتســعة أطقــم ذهــب هدايــا فــرح وسالســل صغيــره ذهــب‬\n‫عددهــا واحــد وعشــرين سلســله وخمســة وعشــرون خامتــا مــن الذهــب‬\n‫ومبلــغ نقــدي قــدره عشــرون الــف ريــال وعــدد اثنــن البتــوب واثنــن‬\n‫رســيفر وكمــرة فيديــو ديجتــال وطقــم يخــص الشــغالة التــي تعمــل‬\n‫لــدي لــذا اطلــب احلكــم علــى املدعــى عليهمــا بإعــادة املســروقات التــي‬\n‫أخذوهــا مــن منزلــي هكــذا ادعــت وبعــرض ذلــك علــى املدعــى عليهمــا‬\n‫أجــاب كل واحــد منهمــا مبفــرده غيــر صحيــح مــا ذكرتــه املدعيــة مــن‬\n‫ســرقتنا ملنزلهــا فلــم نقــم بســرقة منزلهــا وال غيــره مــن املنــازل هكــذا‬\n‫أجــاب كل واحــد مبفــرده ويف جلســة اخــرى حضــرت املدعيــة واملدعــى‬\n‫عليهمــا وبســؤال املدعيــة هــل لديهــا بينــه قالــت لــدي اعترافــات املدعــى‬\n‫عليهمــا التــي ســبق تدوينهــا قضيــة ســرقتهما اطلــب الرجــوع اليهــا ثــم‬\n‫جــرى اطالعــي علــى اقــراري املدعــى عليهمــا املصدقــن شــرعا وجــرى‬\n‫تدوينهمــا بنصهمــا يف ضبــط القضيــة ويف جلســة اخــرى لــدى أنــا ‪.......‬‬\n‫القاضــي باحملكمــة العامــة مبكــة املكرمــة والقائــم بعمــل مســاعد‬\n‫رئيــس احملكمــة مبوجــب خطــاب فضيلــة رئيــس احملكمــة رقــم‬\n‫‪ 33619201‬يف ‪1433/4/3‬ه ـ حضــرت املدعيــة كمــا حضــر املدعــي‬\n‫عليهمــا يرافقهمــا اجلنــدي‪ /‬رقمــه ‪ 247‬وجــرى االطالع على اخلطاب رقم‬\n‫‪ 70722‬يف ‪1431/7/11‬ه ـ فوجدتــه صــادر مــن جلنــة التحقيــق يف قضايا‬\n‫ســرقات املنــازل ويتضمــن انــه مت القبــض علــى املدعــي عليهمــا وعثــر‬\n‫بحــوزة‪ /‬علــى محفظــة بهــا مبلــغ الــف وثمامنائــة وثمانــن ريــاال وبتفتيــش‬\n‫منزلهمــا عثــر علــى مبلــغ ثمانــن الــف ريــال أ‪-‬ه ـ كمــا جــرى االطــاع‬\n‫علــى اخلطــاب رقــم ‪14/407269‬ع يف ‪1431/7/16‬ه ـ فوجــد انــه صــادر‬\n\n\n                                                                                   ‫‪114‬‬\n\f      ‫مــن رئيــس جلنــة التحقيــق يف قضايــا ســرقات املنــازل واملتضمــن انــه مت‬\n      ‫بيــع املضبوطــات املتبقيــة عــن طريــق شــيخ طائفــة داللــي حــراج اخلــردة‬\n      ‫مببلــغ خمســه آالف وســتمائة وثمانيــة ريــاالت وجــرى ســؤال املدعيــة‬\n      ‫هــل لديهــا فواتيــر باألشــياء التــي تدعيهــا فقالــت ســأبحث عــن ذلــك‬\n      ‫وجــرت الكتابــة للشــرطة إليضــاح األعيــان املســروقة لديهــم وايضــاح‬\n      ‫هــل يوجــد بيــان لديهــم يوضــح أســماء اصحابهــا وذلــك مبوجــب خطابنــا‬\n      ‫رقــم ‪ 33761460‬يف ‪1433/4/21‬ه وذلــك بخطابنــا رقــم ‪33761460‬‬\n      ‫يف ‪1433/4/21‬ه ـ فــوردت اإلفــادة مــن مديــر مركــز شــرطة التنعيــم‬\n      ‫باخلطــاب رقــم ‪ 143784‬يف ‪1433/4/27‬ه ـ واملقيــد باحملكمــة برقــم‬\n      ‫‪ 33817654‬يف ‪1433/5/1‬ه ـ واملتضمــن بــان جميــع املضبوطــات‬\n      ‫املوجــودة يف املركــز هــي املبالــغ املاليــة املوضحــة ســابقا وأمــا بالنســبة‬\n      ‫للمضبوطــات األخــرى فجــرى تســليمها ألصحابهــا كمــا هــو موضــح‬\n                                                                    ‫بــأوراق املعاملــة إه ـ‬\n      ‫وجــرى ســؤال املدعيــة عــن تاريــخ الســرقة ووصــف بيتهــا فقالــت أن‬\n      ‫الســرقة متــت عــام ‪1431‬ه ـ أمــا وصــف بيتهــا فهــو عبــارة عــن شــقه بالــدور‬\n      ‫العلــوي يف العمــارة الواقعــة ‪ .....‬املكونــة مــن دوريــن وبــن الــدور األرضــي‬\n      ‫كيلــون بــاب حديــد وبــاب شــقتي مــن اخلشــب وقــد قــام املدعــى عليهــم‬\n      ‫بكســر البــاب احلديــد الواقــع بــن الدوريــن وبــاب الشــقة اخلشــب وأخــذا‬\n      ‫املســروقات التــي ذكرتهــا يف دعــواي هكــذا قــررت كمــا جــرى‬\n      ‫ســؤالها هــل اســتلمت شــيئ ًا مــن املســروقات ممــا وجــد مــع املدعــى‬\n      ‫عليهمــا عــن طريــق الشــرطة فقالــت نعــم إننــي ذهبــت الــى مراكــز‬\n      ‫شــرطة التنعيــم والعزيزيــة والشــرائع وقــد رأيــت جميــع املضبوطــات‬\n      ‫العينيــة مــع املدعــى عليهمــا مــن أجهــزه وذهــب ووجــدت ثمانــي بناجــر‬\n\n\n‫‪115‬‬\n\f‫وخمــس سالســل وســتة خــوامت وجميعهــا مــن الذهــب ولــم أجــد شــيئا‬\n‫ســواه وقــد اســتلمت هــذا الذهــب هكــذا قــررت وبعــرض ذلــك علــى‬\n‫املدعــى عليهمــا قــال املدعــى عليــه صحيــح اننــي ســرقت شــقة املدعيــة‬\n‫وقــد أخــذت مــن بيتهــا ذهبــا ال اذكــر نوعــه وال وصفــه وإمنــا الــذي‬\n‫اذكــره أننــي بعــت جــزء منــه بعشــرة آالف ريــال وباقــي الذهــب لــم‬\n‫أتصــرف بــه وقبضــت علــي الشــرطة ووجدتــه يف بيتــي ومت عرضــه مــع‬\n‫بقيــة املضبوطــات معــي علــى أصحــاب البيــوت املســروقة واســتلمت‬\n‫املدعيــة حقهــا مــن الذهــب املوجــود هــذا مــا لــدي وأنــا اقــر بــه وملتــزم‬\n‫بدفــع مبلــغ عشــرة آالف ريــال لهــا قيمــة الذهــب الــذي بعتــه ممــا ســرقته‬\n‫مــن بيتهــا وأمــا زميلــي فلــم يشــترك معــي يف هــذه الســرقة هكــذا قــرر‬\n‫وقــال املدعــى عليــه انــا لــم اذهــب لبيــت املدعيــة ولــم اســرق منــه شــيئا‬\n‫هكــذا قــرر وبســؤال املدعيــة عــن قيمــة املســروقات عــدا مــا اســتلمته‬\n‫منهــا فقالــت انهــا تتجــاوز ثالثمائــة الــف ريــال وانــا اطالــب بهــذا املبلــغ‬\n‫هكــذا قــررت وبعــرض ذلــك علــى املدعــي عليهمــا قــال املدعــي عليــه‬\n‫األول اننــي ســرقت مــن بيــت املدعيــة ذهــب واننــي بعــت جــزء منــه بعشــرة‬\n‫آالف ريــال والباقــي اســتلمته املدعيــة ولــذا فانــا لــن ادفــع لهــا ســوى هــذا‬\n‫املبلــغ الــذي بعــت بــه الذهــب عشــرة آالف ريــال فقــط وانــا الــذي ســرقت‬\n‫بيتهــا وحــدي ولــم يكــن معــي‪ /‬أو غيــره هكــذا قــرر وبعــرض ذلــك علــى‬\n‫املدعيــة قالــت غيــر صحيــح مــا ذكــره املدعــي عليــه فــإن قيمــة الذهــب‬\n‫الــذي ســرقه مــن بيتــي ولــم اســتلمه يزيــد عــن ثالثمائــة الــف ريــال وانــا‬\n‫اطلــب الزامهمــا بدفــع ثالثمائــة الــف ريــال هكــذا قــررت وقــال املدعــي‬\n‫عليــه الثانــي أنــا لــم أســرق مــن بيتهــا شــيئا هكــذا قــرر وجــرى ســؤال‬\n‫املدعيــة هــل لديهــا بينــه علــى هــذه املســروقات التــي تدعيهــا ممــا لــم‬\n\n\n                                                                                        ‫‪116‬‬\n\f      ‫تســتلمه فقالــت نعــم فأبــرزت ‪ /1‬فاتــورة محــل لبيــع الذهــب برقــم‬\n      ‫‪ 259551‬بشــراء ثمانيــة بناجــر بثالثــة آالف ريــال ‪ /2‬فاتــورة شــركة ‪....‬‬\n      ‫لصناعــة املجوهــرات برقــم ‪ 10/3954‬بشــراء بنجرتــن بألــف وخمســة‬\n      ‫وســتني ريــال ‪ /3‬فاتــورة محــل ‪ ....‬لبيــع الذهــب برقــم ‪ 6249‬بشــراء أربــع‬\n      ‫بناجــر بخمســة آالف ومائتــن وســتة وســبعني ريــال ‪ /4‬فاتــورة مــن محــل‬\n      ‫‪ ....‬بشــراء جوالــن مــن نــوع ‪ ....‬بألــف وخمســمائة وأربعــن ريــاال ‪/5‬‬\n      ‫فاتــورة مــن محــل مجوهــرات ‪ ....‬برقــم ‪ 394966‬بشــراء أســاور ايطاليــة‬\n      ‫الصنــع مببلــغ ســبعمائة وســتني ريــاال ‪ .‬كمــا أبــرزت كشــف حســابها‬\n      ‫املصــريف الصــادر مــن مصــرف ‪ ....‬وتتضمــن مشــتريات املدعيــة مــن‬\n      ‫الذهب على النحو االتي ‪ /1 :‬مجوهرات ‪ 7600 ....‬ريال ‪ /2‬مجوهرات‬\n      ‫‪ 2326 ....‬ريــال ‪ /3‬مجوهــرات ‪ 3824 ....‬ريــال ‪ /4‬مجوهــرات ‪4273 ....‬‬\n      ‫ريــال ‪ /5‬مجوهــرات ‪ 3500 ....‬ريــال ‪ /6‬مجوهــرات ‪ 790 ....‬ريــال ‪/7‬‬\n      ‫مجوهــرات ‪ 1350 ....‬ريــال ‪ /8‬مجوهــرات ‪ 1100 ....‬ريــال ‪ /9‬مجوهرات‬\n      ‫‪150 ....‬ريــال ‪ /10‬مجوهــرات ‪ 225 ....‬ريــال ‪ /11‬مجوهــرات ‪5200 ....‬‬\n      ‫ريــال ‪ /12‬مجوهــرات ‪ 2700 ....‬ريــال ‪ /13‬مجوهــرات ‪6800 ....‬‬\n      ‫ريــال‪ /14‬مجوهــرات ‪ 6860 ....‬ريــال ‪ /15‬مجوهــرات ‪ 2940 ....‬ريــال‬\n      ‫‪ /16‬مجوهــرات ‪ 6000 ....‬ريــال ‪ /17‬مجوهــرات ‪ 3124 ....‬ريــال ‪/18‬‬\n      ‫مجوهــرات ‪ 2873 ....‬ريــال ‪ /19‬مجوهــرات ‪ 3300 ....‬ريــال ‪/20‬‬\n      ‫مجوهــرات ‪ 7950 ....‬ريــال ‪ /21‬مجوهــرات ‪ 3000 ....‬ريــال ‪/22‬‬\n      ‫مجوهــرات ‪ 1415 ....‬ريــال ‪ /23‬مجوهــرات ‪ 3734 ....‬ريــال ‪/24‬‬\n      ‫مجوهرات ‪5600 ....‬ريال ‪ /25‬مجوهرات ‪ 914 ....‬ريال ‪ /26‬مجوهرات‬\n      ‫‪ 6700 ....‬ريــال ‪ /27‬مجوهــرات ‪ 2326 ....‬ريــال ‪ /28‬مجوهــرات ‪....‬‬\n      ‫‪1110060‬ريــال ‪ /29‬مجوهــرات ‪ ....‬للذهــب ‪ 2281‬ريال ‪ /30‬مجوهرات‬\n\n\n‫‪117‬‬\n\f‫‪9000 ....‬ريــال ‪ /31‬مجوهــرات ‪ 119033 ....‬ريــال ‪ /32‬مجوهــرات ‪....‬‬\n‫‪ 1000‬ريــال ‪ /33‬مجوهــرات ‪ 7540 ....‬ريــال ‪ /34‬مجوهــرات ‪2300 ....‬‬\n‫ريــال ‪ /35‬مجوهــرات ‪ 2121 ....‬ريــال ‪ /36‬مجوهــرات ‪ 5000 ....‬ريــال‬\n‫‪ /37‬مجوهــرات ‪ 2150 ....‬ريــال ‪ /38‬مجوهــرات ‪ ....‬للذهــب‬\n‫‪2000‬ريــال‪ /39‬مجوهــرات ‪ 1450 ....‬ريــال ‪ /40‬مجوهــرات ‪6500 ....‬‬\n‫ريــال ‪ /41‬مجوهــرات ‪ 4000 ....‬ريــال ‪ /42‬مجوهــرات ‪ 3351 ....‬ريــال‬\n‫‪ /43‬مجوهــرات ‪ 15000 ....‬ريــال ‪ /44‬مجوهــرات ‪ 4120 ....‬ريــال ‪/45‬‬\n‫مجوهــرات ‪ 4125 ....‬ريــال ‪ /46‬مجوهــرات ‪ 7000 ....‬ريــال ‪/47‬‬\n‫مجوهــرات ‪ 950 ....‬ريــال ‪ /48‬مجوهــرات ‪ 1650 ....‬ريــال ‪/49‬‬\n‫مجوهــرات ‪ 2900 ....‬ريــال ‪ /50‬مجوهــرات ‪ 9840 ....‬ريــال ‪/51‬‬\n‫مجوهــرات ‪ 3300 ....‬ريــال ‪ /52‬مجوهــرات ‪ 2422 ....‬ريــال ‪/53‬‬\n‫مجوهــرات ‪ 2798 ....‬ريــال ‪ /54‬مجوهــرات ‪ 2175 ....‬ريــال ‪/55‬‬\n‫مجوهــرات ‪1674 ....‬ريــال ‪ /56‬مجوهــرات ‪ 1356 ....‬ريــال ‪/57‬‬\n‫مجوهــرات ‪ 5545 ....‬ريــال ‪ /58‬مجوهــرات ‪ 20800 ....‬ريــال ‪/59‬‬\n‫مجوهــرات ‪ 310 ....‬ريــال ‪ /60‬مجوهــرات ‪ 850 ....‬ريــال ‪ /61‬مجوهرات‬\n‫‪ 950 ....‬ريــال ‪ /62‬مجوهــرات ‪ 3821 ....‬ريــال ‪ .‬ومجمــوع املبالــغ مائتــان‬\n‫وثمانيــة وأربعــون الفــا وواحــد وثالثــون ريــاال وبســؤال املدعيــة هــل لديهــا‬\n‫فواتيــر ســوى مــا قدمتــه فقالــت هنــاك أشــياء أخــرى ســرقت مــن منزلــي‬\n‫غيــر هــذا الذهــب وهــو جهــازي كمبيوتــر محمــول وآلة تصويــر وجهازي‬\n‫اســتقبال وســاعة املــاس وذهــب آخــر غيــر هــذا الذهــب الــذي أحضــرت‬\n‫فواتيــره وثمنــه وليــس لــدي فواتيــر بهــذه األشــياء هكــذا قــررت وبعرض‬\n‫ذلــك علــى املدعــى عليهمــا قــال املدعــى عليــه األول أنــا لــم أخــذ ســوى مــا‬\n‫ســبق أن ذكرتــه يف إجابتــي وأنــا مســتعد بدفــع عشــرة آالف ريــال لهــا‬\n\n\n                                                                                        ‫‪118‬‬\n\f      ‫فقــط هكــذا قــرر وقــال املدعــى عليــه الثانــي أنــا لــم اســرق مــن منزلهــا‬\n      ‫شــيئا ولــن ادفــع لهــا شــيئا هكــذا قــرر وبســؤال املدعيــة هــل لديهــا زيــادة‬\n      ‫بينــه فقالــت ليــس لــدي ســوى مــا قدمتــه لكــم هكــذا قــررت ثــم جــرى‬\n      ‫اطالعــي علــى بــاغ املدعيــة بالســرقة املــدون علــى ملــف التحقيــق املرفــق‬\n      ‫باملعاملــة لفــه رقــم ‪ 165‬دوســيه رقــم (‪ )2‬فوجــدت انهــا قــد ذكــرت ان‬\n      ‫قيمــة املســروقات حوالــي مائتــي الــف ريــال فقــط وبعــرض ذلــك علــى‬\n      ‫املدعيــة قالــت نعــم انــا قلــت ذلــك ولكــن كان املبلــغ تقريبيــا والصحيــح‬\n      ‫ان املســروقات كانــت بثالثمائــة الــف ريــال هكــذا قــررت فســألت‬\n      ‫املدعــى عليهمــا عــن املــكان الــذي وجــد فيــه الذهــب املــدون مــن املدعية‬\n      ‫الــذي تعرفــت عليــه لــدى الشــرطة واســتلمته فقــال املدعــى عليــه األول‬\n      ‫ان الشــرطة عثــروا عليهــا عنــدي يف البيــت هكــذا قــرر ثم جــرى الرجوع‬\n      ‫الــى ملــف التحقيــق املرفــق باملعاملــة لفــه رقــم ‪ 165‬دوســيه رقــم (‪)2‬‬\n      ‫فوجــد هــذا نصــه ( بحضورنــا نحــن املوقعــن أدنــاه وبتاريخــه أعــاه ويف‬\n      ‫متــام الســاعة احلاديــة عشــر ظهــرا ويف مقــر جلنــة التحقيــق يف قضايــا‬\n      ‫ســرقات املنــازل مبركــز شــرطة الكعكيــة جــرى عــرض املضبوطــات‬\n      ‫التــي مت العثــور عليهــا يف منــزل املتهــم األول نيجيــري اجلنســية علــى املــرأة‬\n      ‫‪ .......‬ســعودية اجلنســية والتــي ســبقت وان تقدمــت ببــاغ عــن تعــرض‬\n      ‫منزلهــا للســرقة وعنــد العــرض تعرفــت علــى مجموعــه مــن املضبوطــات‬\n      ‫وهــي كاالتــي‪ /1 .:‬عــدد (‪ )8‬بناجــر ذهــب عليــه خطــوط فضيــه ‪/2‬‬\n      ‫عــدد (‪ )13‬خــامت ذهــب متعــددة األشــكال ‪ /3‬عــدد (‪ )2‬زوج اقــراط‬\n      ‫ذهــب ‪ /4‬عــدد (‪ )1‬ســوار يــد ذهــب ‪ /5‬عــدد (‪ )1‬سلســله جــوال ذهــب‬\n      ‫ابيــض ‪ /6‬عــدد (‪ )9‬اقــراط فرديــة ذهــب ‪ /7‬عــدد (‪ )4‬تعليقــات ذهــب‬\n      ‫‪ /8‬عــدد (‪ )1‬تعليقــه اكسســوار اللــون فضــي ‪ .‬كمــا جــرى عــرض‬\n\n\n‫‪119‬‬\n\f‫املضبوطــات التــي مت العثــور عليهــا مبنــزل املتهــم الثاني نيجيري اجلنســية‬\n‫واســتطاعت املــراءة املذكــورة التعــرف علــى بعضهــا وهــي كاالتــي‪.:‬‬\n‫‪ /1‬عــدد واحــد طقــم اكسســوار اللــون فضــي مــع فصــوص ( تعليقــه ‪+‬‬\n‫زوج اقــراط ‪ +‬ســوار يــد ) ‪ /2‬عــدد (‪ )3‬ازواج اقــراط متعــددة االشــكال‬\n‫‪ /3‬عــدد (‪ )3‬تعليقــات ذهــب متعــددة االشــكال ‪ /4‬عــدد (‪ )2‬خــوامت يــد‬\n‫ذهــب اللــون فضــي ‪ /5‬عــدد واحــد خــامت يــد ذهــب ‪ .‬وحفظــا للواقــع مت‬\n‫اعــداد هــذا احملضــر وعليــه جــرى التوقيــع ‪ .‬جنــدي اول توقيــع شــقيقها‬\n‫‪ ........‬توقيــع إ‪-‬ه ـ وبعــرض ذلــك علــى املدعيــة قالــت صحيــح انــا اســتلمت‬\n‫جميــع هــذه االشــياء هكــذا قــررت فســألت املدعيــة عــن ثمــن مــا‬\n‫اســتلمته مــن املســروقات فقالــت أن ثمنهــا هــو ثمانيــة عشــرة الفــا‬\n‫وثمامنائــة وســتني ريــال ولــذا وبــراءة لذمتــي فإنــي اقدرهــا بعشــرين الــف‬\n‫ريــال هكــذا قــررت فســألت املدعيــة عمــا جــاء يف بالغهــا االول مــن ان‬\n‫قيمــة املســروقات مائتــي الــف ريــال تقريبــا فقالــت أننــي قلــت هــذا املبلــغ‬\n‫علــى التقريــب واال فالصحيــح أن ثمنهــا يزيــد عــن مائتــن وخمســن الــف‬\n‫ريــال باإلضافــة الــى أنــه يوجــد ذهــب آخــر لــم أذكــره يف البــاغ األول‬\n‫ولــم اتعــرض لتقديــره وهــو مببلــغ مائــة الــف ريــال وبــذا يكــون مجمــوع‬\n‫ثمــن مــا ســرق مــن بيتــي هــو مبلــغ وقــدره ثالثمائــة وخمســون الــف ريــال‬\n‫وأنــا أطالــب بهــذا املبلــغ هكــذا قــررت وعليــه وألنــه جانــب املدعيــة‬\n‫تقــوى بإقــرار املدعــى عليــه ووجــود بعــض املســروقات ببيــت املدعــى‬\n‫عليهمــا كمــا جــاء يف محضــر املعاينــة وألن املدعيــة ذكــرت يف بــاغ‬\n‫الســرقة االول أن املســروقات تقــارب مــن مائتــي الــف ريــال فقــد قــررت‬\n‫حتليفهــا علــى ذلــك وعلــى أن ثمــن مــا اســتلمته مــن ذهــب هــو مببلــغ‬\n‫عشــرين الــف ريــال فاســتعدت وحلفــت قائلــة واهلل العظيــم أن ثمــن‬\n\n\n                                                                                       ‫‪120‬‬\n\f      ‫املســروقات التــي ســرقها املدعــى عليهمــا مــن بيتــي هــو بأكثــر مــن‬\n      ‫مائتــي الــف ريــال وأنــه يف احلقيقــة ثالثمائــة وخمســن الــف ريــال وأن‬\n      ‫ثمــن مــا اســتلمته عــن طريــق الشــرطة هــو ال يزيــد عــن عشــرين الــف‬\n      ‫ريــال هكــذا حلفــت فبنــاء علــى مــا تقــدم مــن الدعــوى واالجابــة وألن‬\n      ‫املدعــى عليــه أقــر بالســرقة مــن بيــت املدعيــة بينمــا أنكــر ذلــك املدعــى‬\n      ‫عليــه الثانــي وبعــد االطــاع علــى إقــرارات املدعــى عليهمــا املصدقــة‬\n      ‫شــرعا وبعــد االطــاع علــى بــاغ املدعيــة االول بالشــرطة املتضمــن أن‬\n      ‫ثمــن املســروقات مائتــا الــف ريــال تقريبــا وبعــد االطــاع علــى محضــر‬\n      ‫املعاينــة املتضمــن وجــود بعــض املســروقات يف منــزل املدعــى عليهمــا‬\n      ‫وقــد تعرفــت عليهــا املدعيــة وقــد قــررت املدعيــة أن ثمــن مــا اســتلمته ال‬\n      ‫يزيــد عــن عشــرين الــف ريــال وألن الراجــح مــن أقــوال أهــل العلــم أن‬\n      ‫اليمــن يف جانــب اقــوى املتداعــن وقــد تقــوى جانــب املدعيــة باإلقراريــن‬\n      ‫املصدقــن شــرعا وإقــرار املدعــى عليــه األول يف هــذه القضيــة ووجــود‬\n      ‫بعــض املســروقات يف منــزل املدعــى عليهمــا وألن املدعيــة حلفــت اليمــن‬\n      ‫علــى أن ثمــن املســروقات يزيــد علــى مائتــي الــف ريــال وأن ثمــن مــا‬\n      ‫اســتلمته منهــا ال يزيــد عــن عشــرين الــف ريــال وألن املدعيــة مؤاخــذة مبــا‬\n      ‫جــاء يف اقرارهــا يف بــاغ الســرقة االول لذلــك كلــه فقــد حكمــت علــى‬\n      ‫املدعــى عليهمــا بــأن يدفعــا للمدعيــة مائــة وثمانــن الــف ريــال وعــدم‬\n      ‫اســتحقاق املدعيــة لباقــي املبلــغ الــذي تدعيــه وبعــرض احلكــم علــى‬\n      ‫الطرفــن قــرروا جميعــا عــدم القناعــة وطلبوا رفعه حملكمة االســتئناف‬\n      ‫بعــد تقــدمي الئحــة اعتراضيــة فأفهمتهــم مبراجعــة احملكمــة خــال‬\n      ‫عشــرة أيــام الســتالم صــورة الصــك وتقــدمي الالئحــة االعتراضيــة خــال‬\n      ‫ثالثــن يومــا مــدة االعتــراض فــإذا تأخــروا ســقط حقهــم يف طلــب‬\n\n\n‫‪121‬‬\n\f‫االســتئناف واكتســب احلكــم القطعيــة‪ .‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل‬\n   ‫على نبينا محمد وعلى آله وصحبه وسلم‪ .‬حرر يف ‪1434/04/03‬هـ‪.‬‬\n\n\n\n‫•صــدق احلكــم مــن محكمــة االســتئناف برقــم ‪ 34227940‬وتاريــخ‬\n                                                  ‫‪1434/6/3‬هـ‪.‬‬\n\n\n\n\n                                                                          ‫‪122‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":112,"source_page_end":122,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"97311d57b7d1b65a35154cc8239b53cd38ceea16eb5e6f2e37595b51a18a2fb5","normalized_text_hash":"5e8f222f79046c4d95da20d63908c0e7239b54ae977b3bfefa1155699fb1592e","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p112-34184985"},{"id":"5de70533-bbd8-5650-ba2a-e8a55781465a","document_type":"judgment","category":"judicial","subcategory":"general","title":"مطالبة برد مسروق -اشتراك يف سرقة من منزل -عدم قبول الرجوع عن اإلقرار بحق آلدمي -قبول قول املدعي مع ميينه -حتمل ضمان املسروقات بالتساوي بن املتهمن ما لم يقروا باستفادتهم خاف ذلك -ثبوت الدعوى .","document_number":"347621","case_number":"32391711","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة ببريدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/10","year":"1434","subject":"مطالبة برد مسروق -اشتراك يف سرقة من منزل -عدم قبول الرجوع عن اإلقرار بحق آلدمي -قبول قول املدعي مع ميينه -حتمل ضمان املسروقات بالتساوي بن املتهمن ما لم يقروا باستفادتهم خاف ذلك -ثبوت الدعوى .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"        ‫تاريخه‪1434/1/10 :‬هـ‬\n                        ‫ُ‬               ‫َر ْق ُم َّ‬\n                            ‫الص ِّك‪347621 :‬‬\n                          ‫َر ْق ُم الدعوى‪32391711:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 3451153‬تاريخه‪1434/4/24:‬هـ‬\n\n\n      ‫مطالبــة بــرد مســروق ‪ -‬اشــتراك يف ســرقة مــن منــزل ‪ -‬عــدم قبــول‬\n      ‫الرجــوع عــن اإلقــرار بحــق آلدمــي ‪ -‬قبــول قــول املدعــي مــع ميينــه‬\n      ‫‪ -‬حتمــل ضمــان املســروقات بالتســاوي بــن املتهمــن مــا لــم يقــروا‬\n                             ‫باســتفادتهم خــاف ذلــك ‪ -‬ثبــوت الدعــوى ‪.‬‬\n\n\n\n\n                      ‫‪ -1‬قول النبي صلى اهلل عليه وسلم‪( :‬شاهداك أو ميينه)‪.‬‬\n                                   ‫‪ -2‬اليمني تشرع يف جانب أقوى املتداعيني ‪.‬‬\n                                                          ‫‪ -3‬ال عذر ملن أقر ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي بــأن املدعــى عليــه اشــترك مــع آخــر يف ســرقة أطقــم ذهــب‬\n      ‫وأجهــزة إلكترونيــة مــن منزلــه كمــا قامــا بتكســير األقفــال؛ ولــذا‬\n      ‫فقــد طلــب إلزامــه بتســليم نصــف قيمــة املســروقات ونصــف تكاليــف‬\n      ‫إصــاح األقفــال وتنظيــف املنــزل ‪ -‬أنكــر املدعــى عليــه دعــوى املدعــي‪-‬‬\n      ‫اطلعــت احملكمــة علــى إقــرار املدعــى عليــه باالشــتراك يف الســرقة أمام‬\n      ‫جهــة التحقيــق فوجدتــه مجمــا مــن جهــة بيــان قيمــة املســروقات ‪ -‬مــن‬\n      ‫املقــرر شــرعا أنــه ال عــذر ملــن أقــر وأن اليمــن تشــرع يف جانــب أقــوى‬\n      ‫املتداعيــن‪ -‬وجانــب املدعــي يتقــوى بإقــرار املدعــى عليــه بالســرقة‬\n\n‫‪123‬‬\n\f‫فيقبــل قولــه فيمــا يتعلــق بقيمــة املســروقات ‪ -‬قــررت احملكمــة توجيــه‬\n‫اليمــن إلــى املدعــي علــى صحــة دعــواه فأداهــا طبــق مــا طلــب منــه ‪-‬‬\n‫قضــت احملكمــة بإلــزام املدعــى عليــه بتســليم املدعــي املبلــغ املدعــى‬\n‫بــه والــذي ميثــل نصــف املبلــغ اإلجمالــي‪ -‬عــارض املدعــى عليــه علــى‬\n       ‫احلكــم‪ -‬قــررت محكمــة االســتئناف املصادقــة علــى احلكــم ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد‪ :‬لــدي أنا‬\n‫(‪ )......‬القاضــي يف احملكمــة العامــة ببريــدة وبنــاء علــى املعاملــة املقيــدة‬\n‫لنــا مــن فضيلــة الرئيــس برقــم ‪ 321146076‬وتاريخ‪1432/9/3‬ه ـ‬\n‫واحملالــة برقــم ‪ 32391711‬يف ‪1432/9/3‬ه ـ ففــي هــذا اليــوم الســبت‬\n‫املوافق‪1434/1/10‬ه ـ فتحــت اجللســة األولــى يف متــام الســاعة التاســعة‬\n‫صباحــا وفيهــا حضــر ‪ /‬ســعودي بالســجل املدنــي رقــم الوكيل الشــرعي‬\n‫عــن ‪ /‬مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل بريــدة الثانيــة برقــم‬\n‫‪ 34739‬وتاريــخ ‪1433/6/28‬ه ـ مدعيــا علــى احلاضــر معــه ‪ /‬ســعودي‬\n‫بالســجل املدنــي رقــم قائــا يف دعــواه عليــه إنــه يف آخــر شــهر ربيــع األول‬\n‫ســنة ‪1431‬ه ـ قــام املدعــى عليــه ورفيقــه بالســطو علــى منــزل موكلــي‬\n‫الواقع يف حي ‪ ......‬حالي ًا (‪ .....‬ســابقاً) ببريدة وســرقة أطقم ذهب بقيمة‬\n‫ثالثــة وأربعــن ألــف ريــال وجهــاز كمبيوتــر محمــول نــوع توشــيبا بقيمــة‬\n‫خمســة آالف ريــال وجهــاز جــوال ‪ ....‬بقيمــة ثالثــة آالف ريــال كمــا قامــا‬\n‫بتكســير أقفــال األبــواب الداخليــة والتــي كلــف إصالحهــا تســعمائة‬\n‫وخمســن ريــا ًال مــع أعمــال النظافــة للمنــزل وبلــغ مجمــوع ذلــك مبلغــا‬\n‫وقــدره واحــد وخمســون ألفــا وتســعمائة وخمســون ألــف ريــال ومبــا أن‬\n\n                                                                                      ‫‪124‬‬\n\f      ‫املدعــى عليــه شــريك مــع زميلــه يف هــذه الســرقة ويتحمــل نصــف قيمــة‬\n      ‫هــذه املســروقات مــع اصــاح أقفــال األبــواب وأعمــال النظافــة لــذا أطلــب‬\n      ‫إلــزام املدعــى عليــه بتســليمي نصــف قيمــة املســروقات يف وقــت الســرقة‬\n      ‫وذلــك مبلــغ وقــدره خمســة وعشــرون ألفــا وتســعمائة وخمســة وســبعون‬\n      ‫ريــاال هــذه دعــواي وبعــرض ذلــك علــى املدعــى عليــه فقــال مــا نســبه لــي‬\n      ‫املدعــي وكالــة يف دعــواه جملــة وتفصيــا غيــر صحيــح ولــم أقــم أو‬\n      ‫اشــترك بذلــك هــذه إجابتــي ‪ .‬ومبــا أن املدعــى عليــه أنكــر مــا نســب‬\n      ‫لــه يف الدعــوى واســتنادا لقولــه صلــى اهلل عليــه وســلم‪( :‬شــاهداك أو‬\n      ‫ميينــه) لــذا طلبــت مــن املدعــي وكالــة البينــة علــى صحــة دعــواه فقــال إن‬\n      ‫بينتــي علــى ذلــك هــي اعترافــه بذلــك أمــا احملقــق ســابقا أثنــاء التحقيــق‬\n      ‫وميكنكــم طلــب دفتــر التحقيــق لالطــاع عليــه وبنــاء علــى ذلــك جــرت‬\n      ‫مخاطبتــي عــن طريــق فضيلــة مســاعد رئيــس احملكمــة لســعادة مديــر‬\n      ‫ســجن بريــدة بطلــب تزويــدي بنســخة مــن محاضــر التحقيــق مــع املدعــى‬\n      ‫عليــه موجــب اخلطــاب رقــم ‪ 331143772‬يف ‪1433/ 10/ 14‬ه وقــد‬\n      ‫وردتنــي اإلجابــة عــن ذلــك منــه عــن طريــق فضيلــة رئيس احملكمــة برقم‬\n      ‫‪ 1 / 26/ 8338/9‬يف ‪1433/ 11/ 13‬ه ـ املرفــق بهــا دفتــر محاضــر‬\n      ‫التحقيــق مشــفوع ‪ 196‬وباالطــاع عليــه وجــد يف الصحيفــة األولــى منــه‬\n      ‫مــا نصــه‪( :‬وباســتجواب ‪ /‬عــن ارتكابــه عــدة ســرقات فأجــاب منهــا‬\n      ‫عــن الســؤال الثانــي دخلــت منــزل ‪ /‬بحــي ‪ .....‬وســرقت منــه جهــاز ‪.....‬‬\n      ‫جــوال وجهــاز حاســب آلــي ومجموعــة مجوهــرات وكان برفقتــي زميلــي‬\n      ‫‪ /‬فقــط ال غير‪.‬أ‪.‬ه ـ وبعرضــه علــى املدعــى عليــه فقــال مــا نســب لــي‬\n      ‫بذلــك فقــد بصمــت عليــه واعترفــت بــه أمــام البحــث اجلنائــي مكرهــا‬\n      ‫بذلــك هكــذا أفــاد املدعــى عليــه ومبــا أن الفقهــاء قــد نصــوا علــى أنــه‬\n\n\n‫‪125‬‬\n\f‫تؤخــذ اليمــن يف جانــب أقــوى املتداعيــن ونظــرا ألن املدعــى عليــه لــم‬\n‫يفصــح يف إقــراره عــن قيمــة املســروق لــذا طلبــت مــن املدعــي وكالــة‬\n‫إحضــار موكلــه فأحضــر ‪ /‬ســعودي اجلنســية حامــل الســجل املدنــي رقم‬\n‫وبطلــب اليمــن منــه علــى صحــة دعــواه فقــال واهلل العظيــم إنــه يف آخــر‬\n‫شــهر ربيــع األول عــام ‪1431‬ه ـ قــام رجــان بالســطو علــى منزلــي الواقــع‬\n‫يف ‪ .....‬ســابق ًا وحــي ‪ .....‬حاليـ ًا وكســرا أقفــال األبــواب الداخليــة وســرقا‬\n‫مــن داخــل بيتــي أطقــم ذهــب قيمتهــا وقــت الســرقة بثالثــة وأربعــن ألــف‬\n‫ريــال وجهــاز كمبيوتــر محمــول نــوع ‪ .....‬قيمتــه بخمســة آالف ريــال‬\n‫وجهــاز جــوال ‪ .....‬قيمتــه بثالثــة آالف ريــال ومت تصليــح أقفــال األبــواب‬\n‫الداخليــة التــي قامــا بكســرها مببلــغ تســعمائة وخمســن ريــاال مــع‬\n‫أعمــال النظافــة وقــد تبــن لــي مــن اعتــراف املدعــى عليــه هــذا احلاضــر‬\n‫لــدى البحــث اجلنائــي أنــه هــو الــذي قــام بســرقة منزلــي املذكــور وســرقة‬\n‫األعيــان املذكــورة مــع ‪ .....‬وأن قيمــة األعيــان املســروقة مــع قيمــة تصليح‬\n‫األبــواب الداخليــة مــع قيمــة أعمــال النظافــة هــي مــا ذكرتــه آنفــا واهلل‬\n‫علــى مــا أقــول شــهيد وبعــد ســماع الدعــوى واإلجابــة واالطــاع علــى‬\n‫أوراق املعاملــة ومبــا ان املدعــي وكالــة ادعــى مبــا ادعــى بــه وأنكــر‬\n‫املدعــى عليــه ذلــك وأفــاد املدعــي وكالــة أن بينتــه علــى ذلــك هــي مــا ورد‬\n‫يف اعتــراف املدعــى عليــه مبحضــر التحقيــق وبالرجــوع حملضــر التحقيق‬\n‫املنصــوص بعاليــه واعتــراف املدعــى عليــه بذلــك وأنه مكرهــا على ذلك‬\n‫ومبــا أن املدعــى عليــه لــم يذكــر يف اعترافــه قيمــة األعيــان املدعــى بهــا‬\n‫واســتنادا ملــا قــرره الفقهــاء بــأن اليمــن تؤخــذ يف جانــب أقــوى املتداعيني‬\n‫وأدى املدعــي أصالــة اليمــن املعتبــرة شــرعا علــى صحــة دعــواه واســتنادا‬\n‫للقاعــدة ال عــذر ملــن أقــر لــذا فقــد ثبــت لــدي أن يف ذمــة املدعــى عليــه‬\n\n\n                                                                                       ‫‪126‬‬\n\f      ‫للمدعــي أصالــة قيمــة األعيــان املذكــورة يف الدعــوى وقدرهــا خمســه‬\n      ‫وعشــرون الفــا وتســعمائة وخمــس وســبعون ريــاال ومبــا أنــه ثبــت لــدي‬\n      ‫ذلــك فقــد أفهمــت املدعــى عليــه أنــه يلزمــه تســليم ذلــك للمدعــي أصالــة‬\n      ‫هــذا مــا ظهــر لــي وبــه حكمــت ولــدى عــرض ذلــك علــى املدعــى عليــه‬\n      ‫فقــرر عــدم قناعتــه باحلكــم وطلــب رفــع احلكــم مــع املعاملــة حملكمــة‬\n      ‫االســتئناف بــدون الئحــة اعتراضيــة وقــررت رفــع كامــل املعاملــة مــع‬\n      ‫صــك احلكــم وصــورة ضبطــه حملكمــة االســتئناف لتدقيقــه وبــاهلل‬\n              ‫التوفيــق وصلــى اهلل علــى نبينــا محمــد حــرر يف ‪1434/1/10‬ه ـ ‪.‬‬\n\n\n\n      ‫•صــدق احلكــم مــن محكمــة االســتئناف برقــم ‪ 3451153‬وتاريــخ‬\n                                                     ‫‪1434/4/24‬هــ‪.‬‬\n\n\n\n\n‫‪127‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":123,"source_page_end":127,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"a37ff12bbb5cc27b6c85c20a6908ee32fd6b0c80c5adc5fc03b737849426840e","normalized_text_hash":"dbd0356633e368feebf55e702caa183f9098db4f04ef7bb89b087b094e710645","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p123-347621"},{"id":"9cc87f24-b0a1-574d-a166-70a4fffb7435","document_type":"judgment","category":"judicial","subcategory":"general","title":"رد مسروق -اشتراك يف سرقة مبالغ مالية عن طريق تزوير شيكات -اإلقرار -احلكم باإللزام برد املبالغ ممن قبضها واستلمها -رد الدعوى ملن لم يثبت قبضه للمبالغ -اإلفهام بالرجوع على من","document_number":"33316247","case_number":"32540118","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/6/25","year":"1434","subject":"رد مسروق -اشتراك يف سرقة مبالغ مالية عن طريق تزوير شيكات -اإلقرار -احلكم باإللزام برد املبالغ ممن قبضها واستلمها -رد الدعوى ملن لم يثبت قبضه للمبالغ -اإلفهام بالرجوع على من","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1433/6/25 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪33316247 :‬‬\n                    ‫َر ْق ُم الدعوى‪32540118:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 3422887‬تاريخه‪1434/1/26:‬هـ‬\n\n\n‫رد مســروق ‪ -‬اشــتراك يف ســرقة مبالــغ ماليــة عــن طريــق تزويــر شــيكات‬\n‫‪ -‬اإلقــرار ‪ -‬احلكــم باإللــزام بــرد املبالــغ ممــن قبضهــا واســتلمها ‪ -‬رد‬\n‫الدعــوى ملــن لــم يثبــت قبضــه للمبالــغ ‪ -‬اإلفهــام بالرجــوع علــى مــن‬\n                                                                        ‫غــره ‪.‬‬\n\n\n\n\n‫مــا اســتند إليــه القاضــي مــن املبــادئ العامــة وقواعــد العدالــة الــواردة‬\n                                                         ‫يف تســبيب احلكــم ‪.‬‬\n\n\n\n\n‫ادعــى وكيــل الشــركة املدعيــة بــأن املدعــى عليهــم قامــوا باالســتيالء‬\n‫علــى مبالــغ ماليــة مــن احلســاب املصــريف ملوكلتــه عــن طريــق تزويــر‬\n‫شــيكات عائــدة لهــا وصرفهــا لصاحلهــم دون وجــه حــق ؛ وطلــب إلزامهــم‬\n‫متضامنــن بإعــادة املبالــغ املســروقة ملوكلتــه ‪ -‬أنكــر املدعــى عليهــم‬\n‫دعــوى املدعيــة جتاههــم‪ -‬املدعــى عليهمــا األول والرابــع أقــرا بأنهمــا‬\n‫قامــا بصــرف الشــيكات املذكــورة واســتلما املبالــغ املدعــى بهــا نقــدا‪،‬‬\n‫ودفعــا بأنهمــا فعــا ذلــك لصالــح شــخص آخــر وأنهمــا ســلما لــه تلــك‬\n‫املبالــغ بعــد أن أعطاهمــا جــزء منهــا‪ -‬قضــت احملكمــة بإلــزام املدعــى‬\n‫عليهمــا األول والرابــع بتســليم املدعيــة املبالــغ التــي قامــا بســحبها مــن‬\n\n                                                                                    ‫‪128‬‬\n\f      ‫حســابها املصــريف عــن طريــق تلــك الشــيكات املــزورة وأفهمــت األول‬\n      ‫بــأن لــه أن يقيــم دعــواه علــى مــن غــره متــى رغــب ذلك ‪ -‬عارضــت املدعية‬\n      ‫واملدعــى عليــه األول علــى احلكــم وقنــع بــه باقــي املدعــى عليهــم ‪ -‬قررت‬\n                                ‫محكمــة االســتئناف املوافقــة علــى احلكــم ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n      ‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة العامــة مبحافظــة جدة‪/‬املســاعد برقــم ‪ 32540118‬وتاريــخ‬\n      ‫‪ 1432/11/19‬ه ـ املقيــدة باحملكمــة برقــم ‪ 321447916‬وتاريــخ‬\n      ‫‪ 1432/11/14‬ه ـ ففــي يــوم األحــد املوافــق‪ 1433/02/07‬ه ـ حضــر‬\n      ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم الوكيــل الشــرعي عــن‬\n      ‫‪ ....‬بوكالتــه عــن بصفتــه رئيــس مجلــس املديريــن بشــركة ‪ ...‬مبوجــب‬\n      ‫الوكالــة الصــادرة مــن كتابــه عــدل الثانيــة بشــمال جــدة برقــم ‪2348‬‬\n      ‫يف ‪1432/1/7‬ه ـ جلــد ‪ 10215‬وحضــر ســعودي اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم الوكيــل الشــرعي عــن بوكالتــه عــن املدعــى عليــه‬\n      ‫‪ ...‬مبوجــب الوكالــة الصــادرة مــن كتابــه عــدل الثانيــة بشــمال جــدة‬\n      ‫برقــم ‪ 105843‬يف ‪1432/12/19‬ه ـ جلــد ‪ 11251‬و الوكيــل الشــرعي‬\n      ‫عــن بوكالتــه عــن املدعــى عليــه مبوجــب الوكالــة الصــادرة مــن كتابــه‬\n      ‫عــدل الثانيــة بشــمال جــدة برقــم ‪ 5662‬يف ‪1433/1/17‬ه ـ جلــد ‪11340‬‬\n      ‫و حضــر املدعــى عليهمــا الســجينان ولــم يحضــرا مــا يثبــت هويتهمــا‬\n      ‫وابــرز املدعــي وكالــه ‪ ...‬املذكــور اعــاه صحيفــة دعــوى هــذا نصهــا‬\n      ‫‪ :‬حيــث أقــدم املدعــى عليهــم كل مــن‪ ...-4 ...-3 ...-2 ....- 1 :‬علــى‬\n\n‫‪129‬‬\n\f‫االســتيالء علــى مبلــغ وقــدرة ‪3.449.000‬ريــال (ثالثــة ماليــن وأربعمائــة‬\n‫وتســعة وأربعــون ألــف ريــال ) عــن طريــق تزويــر محــررات عرفيــه مــن‬\n‫شــركة موكلــي وحكــم عليهــم مبعاقبــة كل واحــد منهــم بســجنه‬\n‫مــدة ســنتني حتســب مــن تاريــخ توقيفــه علــى ذمــة هــذه القضيــة وتغــرمي‬\n‫كل واحــد منهــم مبلــغ خمســة آالف ريــال ‪.‬وذلــك كمــا هــو واضــح‬\n‫مــن احلكــم الصــادر مــن ديــوان املظالــم برقــم ‪/86‬د‪ 12/‬لعــام ‪1432‬ه ـ‬\n‫و(املرفــق صورتــه) واطلــب إلــزام املدعــى عليهــم متضامنــن بدفــع مبلــغ‬\n‫وقدره‪3449.000.‬ريــال (ثالثــة ماليــن وأربعمائــة وتســعة وأربعــون ألــف‬\n‫ريــال) للشــركة املدعيــة ‪ .‬وبقــراءة هــذه الدعــوى علــى املدعــى عليهــم‬\n‫اصالــه ووكالــة اجابــوا قائلــن نطلــب تســليمنا صــورة الدعــوى وامهالنــا‬\n‫إلحضــار اإلجابــة عليهــا مفصــا وعليــه جــرى تســليمهم صــورة مــن‬\n‫الدعــوى واجلــت اجللســة ويف يــوم االحــد املوافــق ‪1433/3/13‬ه ـ حضــر‬\n‫املدعــي وكالــه املذكــور اعــاه وحضــر املذكــور اعــاه ولــم يحضــر‬\n‫املدعــى عليــه واجــاب املدعــى عليــه وكالــه علــى الدعــوى املرصــودة‬\n‫اعــاه قائــا انــه ال صحــة ملــا جــاء يف هــذه الدعــوى وعليــه طلبــت مــن‬\n‫املدعــي وكالــه البينــة علــى مــا جــاء يف دعــواه فقــال ان بينتــي هــي‬\n‫احلكــم الصــادر مــن ديــوان املظالــم املشــار اليــه يف الدعــوى املتضمــن‬\n‫اعترافــات املدعــى عليهــم باســتعمال احملرريــن املزوريــن وهمــا شــيكني‬\n‫وصرفهمــا مــن البنــك حلســابهما وإلحضــار املدعــى عليــه الســجني‬\n‫واخــذ جوابــه علــى الدعــوى اجلــت اجللســة ويف يــوم األربعــاء املوافــق‬\n‫‪ 1433/05/26‬ه ـ حضــر املدعــي وكالــه املذكــور اعــاه وحضــر‬\n‫املدعــى عليــه وكالــه بهــاء الديــن املذكــور اعــاه وحضــر املدعــى عليــه‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم واجــاب املدعــى عليــه‬\n\n\n                                                                                 ‫‪130‬‬\n\f      ‫قائــا ان مــا جــاء يف الدعــوى غيــر صحيــح واننــي لــم اســتلم شــيئا مــن‬\n      ‫املبلــغ املذكــور يف الدعــوى ابــدا ‪ .‬فطلبــت مــن املدعــي وكالــه ابــراز‬\n      ‫البينــة علــى دعــواه فابــرز حكمــا صــادر مــن ديــوان املظالــم هــذا نصــه‪:‬‬\n      ‫«حكــم رقــم ‪/86‬د‪ 12/‬لعــام ‪1432‬ه ـ صــادر عــن الدائــرة الثانيــة عشــرة‬\n      ‫يف القضيــة رقــم ‪/2/1268‬ق لعــام ‪1432‬ه ـ املقامــة مــن ‪/‬فــرع هيئــة‬\n      ‫الرقابــة والتحقيــق مبنطقــة مكــة املكرمــة ضــد املدعــى عليــه ‪... /‬‬\n      ‫ورفقــاه انــه يف يــوم األحــد املوافــق ‪1432/2/19‬ه ـ اجتمعــت الدائــرة‬\n      ‫الثانيــة عشــرة باحملكمــة االداريــة مبحافظــة جــدة واملشــكلة مــن ‪:‬‬\n      ‫القاضــي ‪ ...‬رئيســا القاضــي عضــوا القاضــي عضــوا وبحضــور امينــا‬\n      ‫للســر وذلــك للنظــر يف القضيــة املذكــورة اعــاه احملالــة للدائــرة بتاريــخ‬\n      ‫‪1432/2/15‬ه ـ الوقائــع تتخلــص وقائــع هــذه القضيــة يف انــه ورد الــى‬\n      ‫احملكمــة اإلداريــة مبحافظــة جــدة خطــاب هيئــة الرقابــة والتحقيــق‬\n      ‫رقــم (‪ )1671/14‬وتاريــخ ‪1432/2/8‬ه املرفــق بــه قــرار االتهــام رقــم‬\n      ‫(‪/224‬ج) لعــام ‪1432‬ه مــع مشــفوعاته وقــد باشــرت الدائــرة النظــر‬\n      ‫يف القضيــة علــى النحــو املثبــت مبحضــر الضبــط حيــث حضــر ممثــل‬\n      ‫االدعــاء ‪ /‬واملتهمــن وادعــى ممثــل االدعــاء يف مواجــه املتهمــن قائــا‪:‬‬\n      ‫تتهــم هيئــة الرقابــة والتحقيــق كل مــن ‪ ... 1 :‬ســعودي اجلنســية ‪)44( ،‬‬\n      ‫ســنة ‪ ،‬متقاعــد ‪،‬متــزوج ولديــه اوالد ‪،‬موقــوف بســجون محافظــة جــدة‬\n                                                ‫اعتبــارا مــن تاريــخ ‪1432/1/16‬ه ـ‬\n      ‫‪ ... -2‬ســعودي اجلنســية ‪ )23( ،‬ســنة ‪ ،‬جنــدي بقــوات الطــوارئ اخلاصــة‬\n      ‫بالعاصمــة املقدســة ‪ .‬اعــزب ‪،‬موقــوف بســجون محافظــة جــدة اعتبــارا‬\n                                                          ‫مــن تاريــخ ‪1432/1/12‬ه ـ‬\n      ‫‪ ... -3‬ســعودي اجلنســية ‪ )34( ،‬ســنة ‪ ،‬موظــف مبصــرف ‪ ...‬متــزوج‬\n\n\n‫‪131‬‬\n\f‫واب لبنــت ‪ ،‬موقــوف بســجون محافظــة جــدة اعتبــارا مــن تاريــخ‬\n                                                                  ‫‪1432/1/28‬هــ‪.‬‬\n‫‪ ... -4‬ســعودي اجلنســية ‪31( ،‬ســنه متــزوج ولديــه بنتــن ‪ ،‬موقــوف‬\n          ‫بســجون محافظــة جــدة اعتبــارا مــن تاريــخ ‪1432/1/28‬هــ‪.‬‬\n‫النهــم وقبــل ذلــك التاريــخ بدائــرة محافظــة جدة مبنطقــة مكة املكرمة‬\n‫‪ :‬املتهــم االول والثانــي والثالــث‪- :‬ســاهموا مــع ‪ /‬؟ ســوري اجلنســية ؟‬\n‫فــرزت لــه اوراق مســتقلة للبحــث عنــه ؟ يف تزويــر ورقــة ماليــه جتاريــة‬\n‫(الشــيك رقــم ‪ 20908‬وتاريــخ ‪2010/12/1‬م باســم املتهــم الثانــي مببلــغ‬\n‫‪ 324000‬ريــال ‪ -‬صــادر مــن البنــك ‪ ...‬فــرع شــارع ‪ ...‬مــن حســاب شــركة‬\n‫‪ )...‬عــن طريــق االتفــاق واملســاعدة وذلــك بــان حصــل املتهــم االول علــى‬\n‫احملــرر مــن ‪ /‬املذكــور بعــد ان قــام بســرقته وتزويــر تواقيــع االشــخاص‬\n‫املعتمديــن لــدى البنــك بصرفــه ثــم قــام بتســليمه للمتهــم الثالــث الــذى‬\n‫قــام بتعبئــة بيانــات املســتفيد واملبلــغ ثــم ســلمه للمتهــم الثانــي الــذى بدوره‬\n‫قدمــه للبنــك ومت صرفــه ‪ ،‬وبنــاء عليــه متــت اجلرميــة املتهــم االول والرابــع‪:‬‬\n‫‪-‬ســاهما مــع ‪ /‬املذكــور اعــاه يف تزويــر ورقــة ماليــه جتاريــة (الشــيك‬\n‫رقم ‪ 20893‬وتاريخ ‪2010/12/7‬م باســم املتهم الرابع مببلغ ‪3125000‬‬\n‫ريــال ‪ ،‬الصــادر مــن البنــك ‪ .....‬فــرع شــارع ‪ .....‬مــن حســاب شــركة ‪...‬‬\n‫) عــن طريــق االتفــاق واملســاعدة وذلــك بــان حصــل املتهــم االول علــى‬\n‫احملــرر مــن ‪ /‬املذكــور بعــد ان قــام بســرقته وتزويــر تواقيــع االشــخاص‬\n‫املعتمديــن لــدى البنــك بصرفــة ثــم قــام املتهــم االول بتعبئــة الشــيك باســم‬\n‫املســتفيد ؟ املتهــم الرابــع ‪ -‬واملبلــغ ثــم ســلمه للمتهــم الرابــع الــذى بــدورة‬\n‫قدمــه للبنــك وقــام بصرفــه مــع علمــه بالتزويــر ؟ وبنــاء عليــه متــت اجلرميــة‪.‬‬\n‫املتهمــن مــن االول حتــى الرابــع ‪ :‬اســتعملوا احملــرران (محــل االتهــام) مــع‬\n\n\n                                                                                          ‫‪132‬‬\n\f      ‫علمهــم التــام بتزويرهمــا وذلــك بتداولهمــا فيمــا بينهــم بعــد امتــام جرميــة‬\n      ‫التزويــر ؟ كمــا هــو موضــح اعــاه ومــن ثــم قيــام املتهــم الثانــي والرابــع‬\n      ‫بتقدميهــا للبنــك وصــرف املبلــغ ؟ بنــاء عليــه متــت اجلرميــة‪ .‬ودللــت الهيئــة‬\n      ‫علــى االتهــام ‪ :‬شــكوى رئيــس شــركة ‪ ...‬املتضمنــة ســرقة الشــيكني ؟‬\n              ‫محــل االتهــام وتزويــر تواقيــع االشــخاص املعتمديــن يف الشــركة‪.‬‬\n      ‫‪ -2‬افــادة البنــك ‪ ...‬املتضمــن ان الــذى قــام بصــرف الشــيكني ؟ محــل‬\n                                                    ‫االتهــام همــا املتهــم الثانــي والرابــع‪.‬‬\n      ‫‪ -3‬اعتــراف املتهــم االول مبــا نســب اليــه مــن قيامــة باحلصــول علــى‬\n      ‫الشــيكني ‪ -‬محــل االتهــام ؟ مــن شــخص ســوري اجلنســية اســمه‪ .../‬ثــم‬\n      ‫قــام بتقدميهمــا الــى املتهمــن الثانــي والرابــع لغــرض الصــرف باســمهما‪.‬‬\n      ‫‪ -4‬اعتــراف املتهــم االول بــان جميــع املتهمــن لديهم العلم بان الشــيكني‬\n                                   ‫محل االتهام مســروقة ومت تعبئتهما بعد الســرقة ‪.‬‬\n      ‫‪ -5‬اعتــراف املتهــم االول بــان الــذى قــام بتعبئــة بيانــات الشــيك االول‬\n      ‫الــذى باســم املتهــم الثانــي هــو املتهــم الثالــث ولديــه العلــم بالتزويــر‪-6.‬‬\n      ‫اعتــراف املتهــم الثانــي بأنــه قــام باســتخراج تذكــره ســفر لغــرض صرف‬\n      ‫الشــيك باســمة كــون بنــك املطــار ال يصــرف الشــيك اال للمســافرين ثــم‬\n      ‫قــام بصرفــه وتســليم املبلــغ للمتهــم االول دون ان يســتلم مبلــغ التذكــرة‬\n      ‫الــذى جتاوز(‪800‬ريــال) ‪ -7‬اعتــراف املتهــم الثانــي بأنــه ذهــب الــى املطار‬\n      ‫لغــرض صــرف الشــيك ؟ محــل االتهــام ؟ برفقــة املتهمــن االول والثالــث‪.‬‬\n      ‫‪ -8‬اعتــراف املتهــم الثالــث بانــه قــام بتعبئــة الشــيك ؟ محــل االتهــام الــذى‬\n                                 ‫باســم املتهــم الثانــي بتدويــن اســم املســتفيد واملبلــغ ‪.‬‬\n      ‫‪ -9‬املتهــم الثالــث يعمــل مبصــرف ‪ ...‬وأفــاد بأنــه التحــق بــدورات تدريبيــة‬\n      ‫لألعمــال املصرفيــة وبذلــك لديــه العلــم بانــه مــا قــام بــه مخالــف لألنظمــة‬\n\n\n‫‪133‬‬\n\f‫مــن قيامــة بتعبئــة بيانــات املســتفيد دون علــم صاحــب احلســاب والرجــوع‬\n                                                                             ‫اليــه ‪.‬‬\n‫‪ -10‬اعتــراف املتهــم الرابــع مبــا نســب اليــه مــن انــه حصــل علــى الشــيك‬\n‫الــذى باســمة محــل االتهــام مــن املتهــم االول ثــم قــام بصرفــة مــع علمــه‬\n‫التــام بالتزويــر ‪.‬وطلبــت الهيئــة مــن احملكمــة االداريــة محاكمــة‬\n‫املتهمــن املذكوريــن طبقــا ألحــكام املــواد (‪ )10،7،6،5‬مــن نظــام‬\n‫مكافحــة التزويــر وقــرار مجلــس الــوزراء رقــم (‪ )223‬لعــام ‪1399‬هــ‪.‬‬\n‫وبســؤال املدعــى عليــه االول اجلــواب اجــاب قائــا ‪:‬اعتــرف مبــا ورد‬\n‫يف الدعــوى جملــه وتفصيــا فقــد حصلــت علــى الشــيك محــل االتهــام‬\n‫مــن شــخص ســوري اســمه‪ /‬موقــع مــن شــخصني مــن شــركة ‪ ...‬وقمــت‬\n‫بتســليم الشــيك للمتهــم الثانــي ‪ /‬وقمنــا بصــرف الشــيك مــن مصــرف ‪...‬‬\n‫فــرع ‪ ...‬ثــم وبعــد ذلــك ســلمني املتهــم الثانــي املبلــغ كــون الشــيك باســمة‬\n‫وســلمته نســبته خمســة يف املائــة البالغــة ثمانيــة عشــر الــف ريــال وأصادق‬\n‫علــى أقوالــي الســابقة وأضــاف بأنــه متــزوج ويعــول اســره مكونــه مــن‬\n‫زوجــه وطفلــن ووالدتــي األرملــة‪ .‬وبســؤال املدعــى عليــه الثانــي اجلــواب‬\n‫اجــاب قائــا‪ :‬بــان املتهــم ‪...... /‬ســلمني الشــيك محــل االتهــام وقــام‬\n‫بكتابــة اســمى علــى الشــيك املتهــم الثالــث ‪ /‬وذهبنــا الــى املطــار‬\n‫ودخلــت الــى مصــرف ‪ ...‬فــرع ‪ ...‬واملتهــم االول‪ /‬وقمــت بصــرف الشــيك‬\n‫وســلمت املبلــغ اليــه وبســؤاله عــن اقوالــه يف التحقيقــات اجــاب بانهــا‬\n‫صحيحــة ويصــادق عليهــا وبســؤاله عــن نســبته مــن مبلــغ الشــيك اجــاب‬\n‫بأنــه لــم يســتلم أي نســبة ومبواجهتــه باعترافــه يف التحقيقــات بأنــه قــام‬\n‫باســتخراج تذكــرة ســفر لغــرض صــرف الشــيك الــذى باســمة الن بنــك‬\n‫املطــار ال يصــرف الشــيك اال للمســافرين اجــاب ذلــك صحيــح‪ .‬وبســؤال‬\n\n\n                                                                                        ‫‪134‬‬\n\f      ‫املدعــى عليــه الثالــث اجلــواب اجــاب قائــا‪ :‬اعتــرف بأنــى قمــت بكتابــة‬\n      ‫اســم املســتفيد ‪ /‬واملبلــغ علــى الشــيك مببلــغ ثالثمائــة وأربعــة وعشــرون‬\n      ‫الــف ريــال وقمــت بتوصيــل املتهمــن االول والثانــي الــى مطــار ‪ ...‬لصــرف‬\n      ‫الشــيك وال اعلــم عــن موضــوع الشــيك وقــد ذكــر لــي أخــي املتهــم االول‬\n      ‫انــه عبــارة عــن عربــون مصنــع وبســؤاله عــن اقوالــه يف التحقيقــات اجــاب‬\n      ‫بأنهــا صحيحــة ويصــادق عليهــا وبســؤاله ايــن تعمــل فأجــاب باننــي اعمــل‬\n      ‫مبصــرف ‪ ...‬وقــد التحقــت بعــدة دورات تدريبيــة لألعمــال املصرفيــة‬\n      ‫وبســؤاله قيامــك بكتابــة اســم املســتفيد واملبلــغ علــى الشــيك محــل‬\n      ‫االتهــام دون علــم صاحــب احلســاب والرجــوع اليــه مخالــف لألنظمــة ؟‬\n      ‫اجــاب بأنــه غيــر مخالــف لألنظمــة ‪.‬وبســؤال املدعــى عليــه الرابــع اجلواب‬\n      ‫اجــاب قائــا ‪ :‬بــان املتهــم االول ‪ /‬ســلمني الشــيك مكتــوب باســمي‬\n      ‫وعليــه املبلــغ بثالثــة ماليــن ومائــة وخمســة وعشــرون الــف ريــال فســألته‬\n      ‫ملــاذا قــام بكتابــة الشــيك باســمي فأجابنــي بأنــه حســابه مقفــل وذهبنــا‬\n      ‫معــا الــى بنــك ‪ ...‬وقمــت بصرفــه علــى النحــو التالــي ‪(:‬مبلــغ مائتــن‬\n      ‫وخمســة وســبعون الــف ريــال نقــدا وقمــت بتحويــل باقــي املبلــغ يف حســابه‬\n      ‫يف مصــرف ‪ ...‬وســلمني املتهــم االول مبلــغ مائــة وتســعة وثالثــون الــف‬\n      ‫ريــال مســتحقاتي التــي متثــل عملــي معــه ملــدة ســبعة اشــهر وبســؤاله عــن‬\n      ‫اقوالــه يف التحقيقــات اجــاب بانهــا صحيحــة‪ .‬وبســؤال املتهــم االول كــم‬\n      ‫نســبة املتهــم الرابــع مــن صــرف الشــيك الثانــي فأجــاب باننــي ســلمته‬\n      ‫خمســة يف املئــة مــن قيمــة الشــيك مبلــغ وقــدرة مائــة وتســعة وثالثــون الــف‬\n      ‫ريــال وباقــي مبلــغ الشــيك ســلمته للشــخص الســوري ‪./‬وبســؤال املدعــى‬\n      ‫عليــه االول بــان املتهــم الرابــع ذكــر بــان املبلــغ الــذى تســلمه منــك كان‬\n      ‫عبــارة عــن رواتبــه املتأخــرة ملــدة ســبعة اشــهر فأجــاب بــان كالمــه غيــر‬\n\n\n‫‪135‬‬\n\f‫صحيــح واملبلــغ املســلم لــه ميثــل خمســة يف املئــة مــن قيمــة الشــيك وبســؤال‬\n‫املدعــى عليــه الرابــع عــن اقوالــه الســابقة اجــاب بانهــا صحيحــة ويصــادق‬\n‫عليهــا ثــم اضــاف املتهــم الرابــع بانــه يعــول اســرة مكونــه مــن زوجتــن‬\n‫وطفلتــن ليــس لهــم عائــل بعــد اهلل غيــرى ثــم اكتفــى االطــراف مبــا‬\n‫قدمــوه وطلبــوا الفصــل يف القضيــة بحالتهــا الراهنــة ‪.‬وحيــث انــه بنــاء‬\n‫علــى الدعــوى واإلجابــة وبعــد دراســة القضيــة واالطــاع علــى االوراق‬\n‫وعلــى شــكوى رئيــس شــركة ‪ ....‬املتضمنــة ســرقة شــيكني محــل‬\n‫االتهــام وتزويــر تواقيــع املعتمديــن يف الشــركة وعلــى افــادة البنــك ‪...‬‬\n‫بــان الــذى قــام بصــرف الشــيكني محــل االتهــام املدعــى عليهمــا الثانــي‬\n‫والرابــع وعلــى اعتــراف املدعــى عليــه االول يف جميــع مراحــل التحقيــق‬\n‫وأمــام الدائــرة مبــا نســب اليــه مــن قيامــة باحلصــول علــى الشــيكني محل‬\n‫االتهــام مــن شــخص ســوري اجلنســية يدعــى ‪........ /‬ثــم قــام بتقدميهمــا‬\n‫للمدعــى عليهمــا الثانــي والرابــع مــن اجل صرفهما باســمهما وان املدعى‬\n‫عليهــم جميعــا لديهــم العلــم بــان الشــيكني مزوريــن وان نصيــب كال‬\n‫منهــم خمســة يف املائــة مــن قيمــة الشــيك وعلــى اعتــراف املدعــى عليــه‬\n‫الثانــي بأنــه قــام باســتخراج تذكــرة ســفر لغــرض صــرف الشــيك الــذى‬\n‫باســمه الن بنك املطار ال يصرف الشــيك إال للمســافرين ثم قام بصرفة‬\n‫وتســليم املبلــغ الــى املدعــى عليــه االول دون ان يســتلم مبلــغ التذكــرة‬\n‫البالــغ ثمامنائــة ريــال مــن املدعــى عليــه االول وانــه ذهــب للمطــار مــن اجــل‬\n‫صــرف الشــيك برفقــة املدعــى عليهمــا االول والثالــث وعــل اعتــراف‬\n‫املدعــى عليــه الثالــث بأنــه قــام بتعبئــة الشــيك محــل االتهــام الــذى باســم‬\n‫املدعــى عليــه الثانــي وذلــك بتدويــن اســم املســتفيد املدعــى عليــه الثانــي‬\n‫واملبلــغ علــى الرغــم مــن علمــه بــان ذلــك مخالــف لألنظمــة كونــه يعمــل‬\n\n\n                                                                                         ‫‪136‬‬\n\f      ‫يف مصــرف ‪ ...‬ولديــه عــدة دورات تدريبيــة لألعمــال املصرفيــة وقيامــة‬\n      ‫بتعبئــة بيانــات املســتفيد واملبلــغ علــى الشــيك دون علــم صاحــب احلســاب‬\n      ‫والرجــوع اليــه و علــى اعتــراف املدعــى عليــه الرابــع يف التحقيقــات بانــه‬\n      ‫حصــل علــى الشــيك الــذى باســمة محــل االتهــام مــن املدعــى عليــه االول‬\n      ‫ثــم قــام بصرفــة واســتالم نســبته خمســة يف املائــة مــن قيمــة الشــيك مــع‬\n      ‫علمــه التــام بتزويــره ممــا تخلــص معــه الدائــرة الــى ادانتهــم بجرائــم‬\n      ‫التزويــر واالســتعمال املنســوبة اليهــم يف هــذه الدعــوى‪ .‬ومعاقبتهــم عــن‬\n      ‫ذلــك طبقــا لنــص املــادة (‪ )10،7،6،5‬مــن نظــام مكافحــة التزويــر‬\n      ‫واعتبارهــم فاعلــن اصليــن طبقــا لقــرار مجلــس الــوزراء رقــم (‪)223‬‬\n      ‫لعــام ‪1399‬ه مــع االكتفــاء بالعقوبــة املقــررة للجرميــة االشــد اعمــاال ملبدأ‬\n      ‫تداخــل العقوبــات يف الفقــه اإلســامي ‪ .‬لذلــك حكمــت الدائــرة‪ :‬بإدانــة‬\n      ‫كل مــن االول ‪ .../‬والثانــي‪..... /‬والثالــث‪..... /‬والرابــع ‪(...... /‬ســعوديي‬\n      ‫اجلنســية) بجرائــم التزويــر واالســتعمال املنســوبة اليهــم يف هــذه الدعــوى‬\n      ‫ومعاقبــة كل واحــد منهــم بســجنه مــدة ســنتني حتســب مــن تاريــخ‬\n      ‫توقيفــه علــى ذمــة هــذه القضيــة وتغــرمي كل واحــد منهــم مبلــغ خمســة‬\n      ‫آالف ريــال ملــا هــو موضــح باألســباب وبإعالنــه علــى االطــراف قــرروا‬\n      ‫القناعــة بــه وبذلــك اصبــح احلكــم نهائيــا وواجــب النفــاذ‪ .‬واهلل املوفــق‬\n      ‫وصلــى اهلل علــى نبينــا محمــد وعلــى الــه وصحبــه وســلم»‪ .‬وبعــرض مــا‬\n      ‫جــاء يف هــذا احلكــم علــى املدعــى عليهــم قالــوا اننــا حضرنــا لــدى ديــوان‬\n      ‫املظالــم وصــدر علينــا احلكــم املرصــود اعــاه وللتأمــل يف الدعوى اجلت‬\n      ‫اجللســة احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء املوافــق‪1433/06/25‬‬\n      ‫ه ـ حضــر املدعــي وكالــه املذكــور اعــاه وحضــر املدعــى عليــه وكاله‬\n      ‫‪ ...‬املذكــور اعــاه وحضــر الســجناء املذكوريــن اعــاه وابــرز املدعــى‬\n\n\n‫‪137‬‬\n\f‫عليــه وكالــه صــك وكالــة صــادر مــن كتابــه عــدل الثانية بشــمال جدة‬\n‫برقــم ‪ 47238‬يف ‪1433/5/25‬ه ـ جلــد ‪ 11756‬تتضمــن توكيل املدعى‬\n‫عليــه يف املرافعــة واملدافعــة وحضــور اجللســات ‪...‬الــخ وتخــول للوكيــل‬\n‫الســير يف هــذه الدعــوى نيابــة عــن املدعــى عليــه املذكــور اعــاه ‪ .‬وبعــد‬\n‫التأمــل يف الدعــوى واالطــاع علــى احلكــم الصــادر مــن ديــوان املظالــم‬\n‫املرصــود اعــاه وجــد ان املدعــى عليــه هــو مــن قــام بصــرف الشــيك رقــم‬\n‫‪ 020893‬واســتالم قيمتــه وبســؤال املدعــى عليــه املذكــور اعــاه عــن‬\n‫ذلــك قــال صحيــح اننــي قمــت بصــرف الشــيك رقــم ‪ 020893‬واســتلمت‬\n‫قيمتــه وقدرهــا ثالثــة ماليــن ومائــه وخمســه وعشــرون الــف ريــال‬\n‫واخــذت منهــا مبلــغ مائــه وتســعه وثالثــن الــف ريــال فقــط واملبلــغ الباقــي‬\n‫وقــدرة مليونــان وتســعمائة وســته وثمانــن الــف ريــال قمــت بتحويلــه علــى‬\n‫حســاب املدعــى عليــه وبســؤال املدعــى عليــه عــن ذلــك قــال صحيــح‬\n‫ان املدعــى عليــه ‪ ...‬قــد حــول املبلــغ علــى حســابي وانــا قمــت بســحبه‬\n‫نقــدا وتســليمه للمدعــو ســوري اجلنســية نقــدا وباالطــاع علــى احلكــم‬\n‫الصــادر مــن ديــوان املظالــم املرصــود اعــاه وجــد ان املدعــى عليــه ‪ ...‬هــو‬\n‫مــن قــام بصــرف الشــيك رقــم ‪ 020908‬واســتالم قيمتــه وبســؤال املدعــى‬\n‫عليــه املذكــور اعــاه عــن ذلــك قــال صحيــح اننــي قمــت بصــرف الشــيك‬\n‫رقــم ‪ 020908‬واســتلمت قيمتــه وقدرهــا ثالثمائــة واربعــه وعشــرون الــف‬\n‫ريــال وقمــت بســحبه نقــدا وتســليمه للمدعــى وبســؤال املدعــى عليــه عــن‬\n‫ذلــك قــال صحيــح ان املدعــى عليــه ‪ ...‬قــد ســلمني املبلــغ نقــدا وقمــت‬\n‫بتســليمه للمدعــو ســوري اجلنســية نقــدا وســلمني مــن املبلــغ ثمانيــة عشــر‬\n‫الــف وســتمائة ريــال فقــط وعليــه بنــاء علــى الدعــوى واإلجابــة ومــا جــاء‬\n‫يف احلكــم النهائــي الصــادر مــن ديــوان املظالــم املرصود اعــاه واعتراف‬\n\n\n                                                                                      ‫‪138‬‬\n\f      ‫املدعــى عليــه ‪ ...‬باســتالم مبلــغ مائــه وتســعه وثالثــن الــف ريــال واعتراف‬\n      ‫املدعــى عليــه باســتالم مبلــغ مليونــن وتســعمائة وســته وثمانــن ريــال مــن‬\n      ‫الشــيك االول ومبلــغ ثالثمائــة واربعــه وعشــرين الــف ريــال مــن الشــيك‬\n      ‫الثانــي ليصبــح مجمــوع املبلــغ الــذي اســتلمه املدعــى عليــه هــو مبلــغ‬\n      ‫ثالثــة مليــون وثالثمائــة وعشــرة االف ريــال وجلميــع مــا ذكــر بعاليــه‬\n      ‫فقــد حكمــت علــى املدعــى عليــه بتســليم شــركة ‪ ...‬مبلــغ مائــه وتســعه‬\n      ‫وثالثــن الــف ريــال وحكمــت علــى املدعــى عليــه بتســليم شــركة ‪...‬‬\n      ‫مبلــغ ثالثــة ماليــن وثالثمائــة وعشــرة االف ريــال وحكمــت بــرد دعــوى‬\n      ‫املدعيــة شــركة ‪ ...‬املذكــورة اعــاه علــى املدعــى عليهمــا ‪.....‬و ‪ ...‬لعــدم‬\n      ‫ثبــوت اســتالمهما ملبلــغ الشــيكني املذكوريــن اعــاه وافهمــت املدعــى‬\n      ‫عليــه املذكــور اعــاه بــان لــه ان يقيــم دعــواه علــى املدعــو ‪ ...‬متــى‬\n      ‫رغــب ذلــك حكمــا افهمتــه اجلميــع باملجلــس الشــرعي فقــرروا عــدم‬\n      ‫قناعتهــم بــه مــا عــدا املدعــى عليهــم ‪...‬و‪ ...‬و‪ ...‬املذكوريــن اعــاه فقــد‬\n      ‫قــرروا القناعــة باحلكــم وافهمــت املعترضــن علــى احلكــم املذكوريــن‬\n      ‫اعــاه بــأن عليهــم مراجعــه احملكمــة بعــد عشــرة ايــام الســتالم صــورة‬\n      ‫مــن صــك احلكــم واالعتــراض عليــه خــال ثالثــن يومــا مــن تاريــخ‬\n      ‫اســتالمهم صــورة صــك احلكــم واذا مضــى ثالثــون يومــا علــى تســجيل‬\n      ‫صــك احلكــم ولــم يقدمــوا اعتراضهــم عليــه ســقط حقهــم يف االعتــراض‬\n      ‫واصبــح احلكــم مكتســب القطعيــة وغيــر خاضــع للتمييــز ففهمــوا ذلــك‬\n      ‫وامــرت بإخــراج صــك مبوجبــه ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                  ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/06/25‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ثــم عــادت إلينــا املعاملــة مــن محكمــة االســتئناف‬\n      ‫مبكــة املكرمــة وبرفقهــا صــك احلكــم مظهــرا عليــه بالتصديــق‬\n\n\n‫‪139‬‬\n\f‫مــن الدائــرة اجلزائيــة الرابعــة مبحكمــة االســتئناف مبكــة املكرمــة‬\n‫بالقــرار رقــم ‪ 3422887‬يف ‪1434/1/26‬ه ـ وهــذا نصــه بعــد املقدمــة ‪:‬‬\n‫وبدراســة احلكــم وصــورة ضبطــه والالئحتــن االعتراضيتــن تقــررت‬\n‫املوافقــة علــى احلكــم وبــاهلل التوفيــق ‪ ،‬وعليــه أمــرت باحلــاق ذلــك‬\n‫بضبطــه وســجله وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                          ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/2/24‬ه ـ ‪.‬‬\n\n\n\n\n                                                                               ‫‪140‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":128,"source_page_end":140,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"7786c42a3bfc0f3d4915da13f2bf3f08f451a03827e02067107d4b6e91d3bcc9","normalized_text_hash":"5e43bcf6f1843a2209de1b46e6a0c10d864eef58a8e9b4d3ddc7af541bd8d7ae","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p128-33316247"},{"id":"ad9998b4-d967-57d5-840c-b806c8947b69","document_type":"judgment","category":"judicial","subcategory":"general","title":"قيمة مسروق -املطالبة برد قيمة جواالت مسروقة -إقرار املدعى عليهما املصدق شرعا -وجوب رد العن املسروقة على مالكها إذا كانت باقية -ورد قيمتها إذا كانت تالفة -أو مثلها إذا كانت مثلية -تقدير قيمة املسروق عن طريق قسم اخلبراء -احلكم برد قيمة اجلواالت املسروقة -تنازل املدعى عن احلق احملكوم به.","document_number":"348978","case_number":"33293198","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف مبنطقة مكة ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/11","year":"1434","subject":"قيمة مسروق -املطالبة برد قيمة جواالت مسروقة -إقرار املدعى عليهما املصدق شرعا -وجوب رد العن املسروقة على مالكها إذا كانت باقية -ورد قيمتها إذا كانت تالفة -أو مثلها إذا كانت مثلية -تقدير قيمة املسروق عن طريق قسم اخلبراء -احلكم برد قيمة اجلواالت املسروقة -تنازل املدعى عن احلق احملكوم به.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"        ‫تاريخه‪1434/1/11 :‬هـ‬\n                        ‫ُ‬                ‫َر ْق ُم َّ‬\n                             ‫الص ِّك‪348978 :‬‬\n                          ‫َر ْق ُم الدعوى‪33293198 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 3435048‬تاريخه‪1434/2/11:‬هـ‬\n\n\n      ‫قيمــة مســروق ‪ -‬املطالبــة بــرد قيمــة جــواالت مســروقة ‪ -‬إقــرار املدعــى‬\n      ‫عليهمــا املصــدق شــرعا ‪ -‬وجــوب رد العــن املســروقة علــى مالكهــا إذا‬\n      ‫كانــت باقيــة ‪ -‬ورد قيمتهــا إذا كانــت تالفــة ‪ -‬أو مثلهــا إذا كانــت‬\n      ‫مثليــة ‪ -‬تقديــر قيمــة املســروق عــن طريــق قســم اخلبــراء ‪ -‬احلكــم بــرد‬\n           ‫قيمــة اجلــواالت املســروقة ‪ -‬تنــازل املدعــى عــن احلــق احملكــوم بــه‪.‬‬\n\n\n\n\n             ‫‪ .1‬قوله صلى اهلل عليه وسلم «على اليد ما أخذت حتى تؤديه»‪.‬‬\n      ‫‪ .2‬قــال ابــن رشــد ‪« :‬إذا اجتمــع القــوم يف الغصــب أو الســرقة أو احلرابــة‬\n      ‫بعضــا‪،‬‬\n          ‫فــكل واحــد منهــم ضامــن بجميــع مــا أخــذوه‪ ،‬ألن بعضهــم قـ ّوى ً‬\n      ‫جميعــا‪ ،‬وإن ولــي‬\n                    ‫ً‬      ‫كالقــوم املجتمعــن علــى قتــل رجــل فيقتلــون بــه‬\n                                                           ‫القتــل أحدهــم وحــده»‪.‬‬\n      ‫‪ .3‬قــال ابــن قدامــة رحمــه اهلل‪« :‬ال يختلــف أهــل العلــم يف وجــوب رد‬\n      ‫العــن املســروقة علــى مالكهــا إذا كانــت باقيــة‪ ،‬فأمــا إن كانــت تالفــة‪،‬‬\n      ‫فعلــى الســارق رد قيمتهــا‪ ،‬أو مثلهــا إن كانــت مثليــة‪ ،‬قطــع أو لــم‬\n                         ‫يقطــع‪ ،‬موســر ًا كان أو معســر ًا» املغنــي‪.)274/10( :‬‬\n      ‫‪ .4‬جــاء يف التشــريع اجلنائــي لعبــد القــادر عــودة «إذا كان الســارق قــد‬\n      ‫تعــاون مــع غيــره يف إخــراج الســرقة ‪ ،‬فــكل مــن لزمــه القطــع يف الســرقة‬\n      ‫كان مســئو ًال بالتضامــن عمــا أخــذه غيــره ممــن وجــب عليهــم القطــع‪.‬‬\n\n\n‫‪141‬‬\n\f‫ادعــى املدعــي بالوكالــة عــن مؤسســة جتاريــة أن يف ذمــة املدعى عليهما‬\n‫ملوكلتــه خمســة وتســعني ألفــا وســبعمائة وأربعــة وأربعــن ريــاال قيمــة‬\n‫أربعــة وثالثــن جــوا ًال مــن نــوع آي فــون‪ ،‬وذلــك لقيــام املدعــى عليهمــا‬\n‫بســرقة هــذه األجهــزة مــن الشــركة الشــاحنة ‪ ،‬وقــد أقــرت الشــركة‬\n‫أن هــذه اجلــواالت للمؤسســة املدعيــة ‪ ،‬وطلــب إلزامهمــا بدفــع املبلــغ‬\n‫املذكور‪ ،‬جرى الرجوع إلقرار الشــركة املذكورة يف الصك الصادر‬\n‫برقــم ‪ ....‬وتاريــخ ‪ ،.....‬وإقــرار الشــركة أيضـ ًا املرفــق باملعاملــة املتضمــن‬\n‫أن األجهــزة املتعلقــة بهــذه الدعــوى تخــص فــرع املؤسســة املدعيــة وتنــازل‬\n‫الشــركة الناقلــة عــن الدعــوى لصالــح املؤسســة املذكــورة‪ ،‬بعــرض‬\n‫الدعــوى علــى املدعــى عليهمــا أنكــرا الدعــوى جملــة وتفصيال‪ ،‬بســؤال‬\n‫املدعــى وكالــة عــن بينتــه علــى دعــواه‪ ،‬أجــاب أن بينتــه مــا جــاء يف‬\n‫أوراق املعاملــة مــن إقــرار املدعــى عليهمــا ‪ ،‬جــرى االطــاع علــى إقــراري‬\n‫املدعــى عليهمــا املصدقــن شــرع ًا ‪ ،‬جــرى االطــاع علــى الصــك الصــادر‬\n‫برقــم ‪ .....‬وتاريــخ ‪ .....‬املتضمــن تقديــر اجلــوال الواحــد مــن أهــل اخلبــرة‬\n‫بألفــن وثمامنائــة وســتة عشــر ريــاال ‪ ،‬ويصبــح مجمــوع قيمــة اجلــواالت‬\n‫خمســة وتســعني ألفــا وســبعمائة وأربعــة وأربعــن ريــاال‪ ،‬بنــاء علــى‬\n‫مــا جــاء يف إقــراري املدعــى عليهمــا املصدقــن شــرعا‪ ،‬ومــا جــاء يف‬\n‫أقوالهمــا يف التحقيقــات‪ ،‬مــا جــاء يف تقريــر أهــل اخلبــرة بتقديــر قيمــة‬\n‫اجلــواالت املســروقة‪ ،‬لقولــه صلــى اهلل عليــه وســلم «علــى اليــد مــا أخــذت‬\n‫حتــى تؤديــه»‪ ،‬لــذا مت احلكــم علــى املدعــى عليهمــا بدفــع مبلــغ وقــدره‬\n‫خمســة وتســعون ألفــا وســبعمائة وأربعــة وأربعــون ريــاالً‪ ،‬للمدعــي أصالــة‬\n\n\n                                                                                       ‫‪142‬‬\n\f      ‫‪ -‬بعــرض احلكــم علــى املدعــي وكالــة قــرر القناعــة وقــرر املدعــى‬\n      ‫عليهمــا عدمهــا ‪ -‬بعــد رفــع احلكــم حملكمــة االســتئناف متــت املصادقــة‬\n      ‫عليــه ‪ -‬قــرر وكيــل الشــركة املدعيــة التنــازل عــن حــق موكلــه لوجــه‬\n                                                                       ‫اهلل تعالــى ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة اجلزائيــة يف محافظــة جدة‪/‬املســاعد برقــم ‪33293198‬‬\n      ‫وتاريــخ ‪ 1433/04/26‬ه ـ املقيــدة باحملكمــة برقــم ‪ 33403935‬وتاريخ‬\n      ‫‪ 1433/03/01‬ه ـ ففــي يــوم األحــد املوافــق‪ 1434/01/11‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة (‪ )10:00‬لســماع دعــوى ‪ ..........‬ضــد ‪ .........‬وفيهــا‬\n      ‫حضــر ‪ ...........‬ســعودي اجلنســية مبوجــب بطاقــة الهويــة الوطنيــة رقــم‬\n      ‫‪............‬الوكيــل الشــرعي عــن ‪ ................‬أصالــة عــن نفســه وبصفتــه‬\n      ‫صاحــب مؤسســة ‪...........‬التجاريــة برقــم ‪..........‬وتاريــخ ‪1433/07/14‬ه ـ‬\n      ‫املخولــة لــه املطالبــة وإقامــة الدعــاوي املرافعــة واملدافعــة ســماع الدعــاوي‬\n      ‫والــرد عليهــا اإلقــرار واإلنــكار والصلــح التنــازل طلــب اليمــن ورده‬\n      ‫واالمتنــاع عنــه وإحضــار الشــهود والبينــات والطعــن فيهــا الطعــن يف‬\n      ‫التزويــر تعيــن اخلبــراء واحملكمــن وادعــى علــى احلاضريــن معــه يف‬\n      ‫هــذه اجللســة ‪ ..........‬مينــي اجلنســية مبوجــب بطاقــة بديلــه رقــم ‪2/.........‬‬\n      ‫ا يف‬ ‫و ‪ ..........‬مينــي اجلنســية مبوجــب بطاقــة بديلــه رقــم ‪ 2/.........‬قائ ـ ً‬\n      ‫حتريــر دعــواه إن ملوكلتــي يف ذمــة املدعــى عليهمــا احلاضريــن معــي‬\n      ‫يف هــذه اجللســة مبلــغ وقــدره خمســة وتســعون ألــف وســبعمائة وأربعــة‬\n\n‫‪143‬‬\n\f‫وأربعــون ريــال ‪95744‬ريــال وذلــك قيمــة أربعــة وثالثــون جــوال مــن‬\n‫نــوع آي فــون وذلــك لقيــام املدعــى عليهمــا بســرقة هــذه األجهــزة مــن‬\n‫شــركة ‪ ..............‬الشــركة الشــاحنة وذلــك بتاريــخ ‪1430/01/02‬ه ـ‬\n‫وقــد أقــرت الشــركة يف مجلــس احلكــم عنــد الشــيخ ‪ ............‬بــأن‬\n‫هــذه اجلــواالت لنــا وذلــك بتاريــخ ‪1432/7/25‬ه ـ ومبوجــب إقرارهــم‬\n‫املرفــق باملعاملــة أطلــب إلزامهمــا بدفــع هــذا املبلــغ ملوكلتــي علم ـ ًا بــأن‬\n‫احلــق العــام قــد نظــر مــن قبــل فضيلــة الشــيخ ‪ ...........‬وصــدر فيــه القــرار‬\n‫الشــرعي رقــم ‪/5/08‬م وتاريــخ ‪ 1432/01/07‬واملصــدق مــن محكمــة‬\n‫االســتئناف مبنطقــة مكــة برقــم ‪ 3381504‬وتاريــخ ‪1433/02/14‬هــذه‬\n‫دعــواي وبالرجــوع إلــى إقــرار الشــركة الناقلــة شــركة ‪............‬‬\n‫بواســطة وكيلهمــا ‪ ...............‬الوكيــل الشــرعي عــن شــركة ‪.......‬‬\n‫القابضــة مبوجــب الوكالــة برقــم ‪66690‬يف ‪1431/9/15‬ه ـ واملخولــة‬\n‫لــه يف وكالتــه حــق اإلقــرار وقــرر أن الشــركة رفعــت الدعــوى بصفتهــا‬\n‫الشــركة الناقلــة وصــادق علــى ذلــك وكيــل مؤسســة ‪ ...‬كمــا جــاء‬\n‫يف الصــك الصــادر برقــم ‪/5/80‬م وتأريــخ ‪1432/01/07‬ه ـ وإقرارهــم‬\n‫املرفــق باملعاملــة املتضمــن أن األجهــزة املتعلقــة بهــذه الدعــوى تخــص‬\n‫فــرع مؤسســة ‪ ..........‬وتنــازل الشــركة الناقلــة عــن الدعــوى لصالــح‬\n‫مؤسســة ‪ ..........‬وعليــه توقيــع وكيــل شــركة ‪ ...‬ووكيــل مؤسســة‬\n‫‪ .........‬وبعــرض الدعــوى علــى املدعــى عليهمــا وســؤالهما اجلــواب أجابــا‬\n‫ا‬‫قائلــن مــا ذكــره املدعــى وكالــة كلــه غيــر صحيــح جملــة وتفصي ـ ً‬\n‫ا مــا‬‫هكــذا أجابــا وبســؤال املدعــى وكالــة عــن بينتــه أجــاب قائ ـ ً‬\n‫جــاء يف أوراق املعاملــة مــن إقرارهمــا عليــه جــرى اطالعــي علــى إقــرار‬\n‫املدعــى عليــه ‪ .............‬علــى املصــدق شــرعا املرفــق باملعاملــة لفــة رقــم‬\n\n\n                                                                                         ‫‪144‬‬\n\f      ‫(‪ )122‬صحيفــة رقــم (‪ )2-1‬واملتضمــن مــا نصــه أنــه يف حوالــي الســاعة‬\n      ‫الثانيــة ظهــرا يــوم األثنــن املوافــق ‪1430/1/15‬ه ـ أثنــاء تواجــدي يف‬\n      ‫مطعــم ومطبــخ ‪ ...‬يف حــي ‪ .....‬لغــرض شــراء وجبــة غــداء قابلــت أحــد‬\n      ‫األشــخاص ويدعــي ‪ ............../‬صومالــي اجلنســية والــذي أعرفــه مــن‬\n      ‫الســابق وأبلغنــي أنــه يوجــد لديــه أجهــزة جــواالت جديــدة يرغــب يف‬\n      ‫بيعهــا وســألني عمــا إذا كنــت اعــرف أحــد يرغــب يف شــرائها وأخبرتــه‬\n      ‫أننــي ال أعــرف أحــد وقــام هــو بــدوره باالتصــال علــى املدعــو ‪............/‬‬\n      ‫مينــي اجلنســية وطلــب منــه احلضــور إلينــا وبعــد حضــوره ركبنــا ســويا يف‬\n      ‫ســيارة املدعــو ‪ ............/‬وتوجهنــا إلــى أحــد محــات اجلــواالت يف شــارع‬\n      ‫‪ ...‬وهــو محــل ‪ .....‬لالتصــاالت وقــام املدعــو‪ ............. /‬بدخــول احملــل‬\n      ‫ومعــه أجهــزة اجلــواالت ورجــع إلينــا وأبلغنــا بأنــه ثمــن األجهــزة غيــر‬\n      ‫متوفــر بالكامــل وســوف يكتمــل بعــد ســاعة تقريبــا وانتظرنــا خــارج‬\n      ‫احملــل وبعــد ذلــك دخلــت احملــل مــع املدعــو‪ ......... /‬وقــام العامــل باحملــل‬\n      ‫بتســليم املدعــو‪ ............ /‬مبلــغ مالــي وقــدرة (‪ )60000‬ســتون ألــف‬\n      ‫ريــال وقــام بعدهــا بتســليمها لــي وخرجنــا مــن احملــل ســوا وركبنــا مــع‬\n      ‫املدعــو‪ ...../‬يف ســيارته مــن نــوع‪ ........‬اللــون أبيــض ال أعــرف رقــم لوحتهــا‬\n      ‫وقــام بإيصالــي إلــي ســيارتي يف حــي ‪ .....‬بجــوار مطعــم ‪ ...‬وســلمني مبلــغ‬\n      ‫مالــي وقــدره (‪ )1700‬ريــال ســعودي كمســاعده لــي كونــي عاطــل عــن‬\n      ‫العمــل حاليــا وبعــد ذلــك ذهــب املدعــو ‪ ............./‬وبرفقــة املدعــو ‪......./‬‬\n      ‫إلــي جهــة غيــر معروفــة لــدي وأخــذت ســيارتي وتوجهــت إلــى منزلــي بعــد‬\n      ‫ذلــك هــذا إقــراري وعليــه أوقــع كمــا جــرى اطالعــي علــى إقــرار املدعــى‬\n      ‫عليــه ‪ ...‬املصــدق شــرعا واملرفــق باملعاملــة لفــة رقــم (‪ )129‬صحيفــة رقــم‬\n      ‫(‪ )4/3/2‬واملتضمــن مــا نصــه أقــر وأعتــرف أنــا املدعــو ‪.................. /‬‬\n\n\n‫‪145‬‬\n\f‫مينــي اجلنســية ‪ 34‬ســنه وأقيــم يف البــاد بطريقــة غيــر مشــروعه بأنــه‬\n‫ســبق وأن مت القبــض علــي يف عــدة قضايــا جنائيــة كان آخرهــا عــام‬\n‫‪1426‬ه ـ ومت ابعــادي عــن البــاد علــى أثرهــا وقدمــت إلــي الســعودية‬\n‫قبــل حوالــي شــهرين بطريقــة التهريــب عبــر احلــدود الســعودية اليمنيــة‬\n‫وقبــل حوالــي شــهر وعشــرون يومــا قمــت بشــراء إقامــة مــزورة حتمــل‬\n‫صورتــي واســم ‪ ...........‬مينــي اجلنســية واســتخدمتها كإثبــات للهويــة‬\n‫ولقــد اشــتريتها مــن شــخص باكســتاني اجلنســية ال أعرفــه وال أســتطيع‬\n‫اإلرشــاد عليــه مقابــل مبلــغ مالــي وقــدرة (‪ )300‬ثالثمائــة ريــال ويف يــوم‬\n‫األثنــن ‪1430/1/15‬ه ـ اتصــل بــي املدعــو‪ .............. /‬مينــي اجلنســية‬\n‫وأبلغنــي أنــه يوجــد لديــه عــدد (‪ )33‬جهــاز جــوال نــوع ‪ .....‬جديــدة‬\n‫ويرغــب يف بيعهــا وقمــت بــدوري باالتصــال علــى املدعــو‪ .............. /‬مينــي‬\n‫اجلنســية والــذي يعمــل مبحــل ‪ .............‬لالتصــاالت بحــي ‪ .....‬بشــارع ‪.....‬‬\n‫وأبلغتــه باألجهــزة املوجــودة فقــال لــي أنــه ســوف يقــوم بشــراء األجهــزة‬\n‫وذكــرت لــه أنهــا مســروقة فقــال لــي ال يهــم ســوف اشــتريها وأنــه يقــوم‬\n‫بشــراء األجهــزة املســروقة وبالفعــل توجهــت إلــي احملــل الــذي يعمــل بــه‬\n‫أنــا واملدعــو‪ .................. /‬وشــخص اخــر صومالــي اجلنســية ال أعرفــه‬\n‫مــن الســابق وكانــت األجهــزة بحــوزة املدعــو‪ .............. /‬ومت تســليم‬\n‫املدعــو‪ ............. /‬عــدد ثالثــون جهــاز جــوال وقــام بتجربــة بعضــا منهــا‬\n‫ودفــع للمدعــو ‪ ................. /‬مبلــغ(‪ )60900‬ســتون ألــف وتســعمائة ريــال‬\n‫ســعودي وغــادرت أنــا واملدعــو‪ ............./‬احملــل وقــام بتســليمي املذكــور‬\n‫مبلــغ (‪ )1000‬ألــف ريــال لتوســطي يف بيــع األجهــزة ورجعــت إلــي محــل‬\n‫‪ ..........‬مــرة أخــرى وقــام املدعــو‪ ................ /‬بتســليمي مبلــغ (‪)1700‬‬\n‫الــف وســبعمائة ريــال كأتعــاب لتوســطي يف بيــع األجهــزة أيضــا ويف يــوم‬\n\n\n                                                                                      ‫‪146‬‬\n\f      ‫اخلميــس املوافــق ‪1430/1/18‬ه ـ توجهــت أنــا واملدعــو‪ ................ /‬مــرة‬\n      ‫اخرى إلى محل ‪ ...‬لالتصاالت ومت بيع عدد (‪ )3‬أجهزة من نفس النوع‬\n      ‫علــى املدعــو‪ .................../‬وأســتلم املدعــو‪ .............. /‬مبلــغ (‪)6000‬‬\n      ‫ســتة أالف ريــال ســعودي ويف يــوم اخلميــس املوافق‪1430/1/25‬ه ـ قــام‬\n      ‫املدعــو ‪ ................./‬بتســليمي عــدد خمســة ســتون وجهــه غــاف جــوال‬\n      ‫متنوعــة لبيعهــا وال اعلــم مــن أيــن حصــل عليهــا وتوجهــت إلــى محــل ‪.........‬‬\n      ‫التصــاالت وقمــت ببيعهــا مببلــغ (‪ )200‬ريــال وقــد مت القبــض علــي يف‬\n      ‫نفــس اليــوم مــن قبــل دويــات األمــن بعــد اإلبــاغ علــي مــن ‪ ......‬املذكــور‬\n      ‫وشــخص آخــر معــه ولقــد مت القبــض علــي وبرفقتــي شــخص مرافــق‬\n      ‫لــي يدعــى‪ ................./‬صومالــي اجلنســية الــذي قــام بإيصالــي إلــى‬\n      ‫محــل ‪ ......‬لالتصــاالت كمــا أقــر بأننــي أعــرف املدعــو‪ ............. /‬منــذ‬\n      ‫حوالــي ســنتني واعــرف املدعــو ‪ .................. /‬منــذ حوالــي شــهر تقريبــا‬\n      ‫واملدعــو‪ .................. /‬منــذ حوالــي أســبوعني هــذا إقــرار واعتــراف منــي‬\n      ‫بذلــك وعليــه أوقــع وبســؤال املدعــى باحلــق اخلــاص وكالــة عــن تقديــر‬\n      ‫قيمــة اجلــواالت املســروقة أجــاب قائــا ســبق وأن أحضرنــا عنــد فضيلــة‬\n      ‫الشــيخ ‪ ...........‬مقدريــن مــن أهــل اخلبــرة وهــي مســجلة بصــك احلكــم‬\n      ‫الصــادر منــه هكــذا أجــاب عليــه جــرى اطالعــي علــى الصــك الصــادر‬\n      ‫مــن قبــل فضيلــة الشــيخ برقــم ‪/5/80‬م وتاريــخ ‪1432/01/07‬ه ـ‬\n      ‫املتضمــن طلــب فضيلتــه مــن املدعــى مقدريــن مــن أهــل اخلبــرة فاحضــر‬\n      ‫كل مــن ‪ ..................‬مصــري اجلنســية إقامــة رقــم ‪ ...............‬و‪..............‬‬\n      ‫اجلنســية إقامــة رقــم ‪ ............‬وقــرر كل منهمــا إننــا نعــرف جــواالت‬\n      ‫املدعــي أصالــة نــوع آي فــون ‪16‬قيقــا ويقــدر الواحــد بألفــن وثمامنائــة‬\n      ‫وســتة عشــر ريــال ‪ 2816‬يصبــح مجمــوع قيمــة اجلــواالت خمســة وتســعني‬\n\n\n‫‪147‬‬\n\f‫ألــف وســبعمائة وأربعــة وأربعــن ريــال عليــه وبنــاء علــى مــا تقــدم مــن‬\n‫الدعــوى واإلجابــة ونظــرا ملــا جــاء يف إقــرار املدعــى عليهمــا املصــدق‬\n‫شــرعا ومــا جــاء يف أقوالهمــا يف التحقيقــات وملــا جــاء يف تقريــر أهــل‬\n‫اخلبــرة بتقديــر قيمــة اجلــواالت املســروقة وملــا جــاء يف املغنــي البــن قدامــه‬\n‫مــن قولــه‪ »:‬ال يختلــف أهــل العلــم يف وجــوب رد العــن املســروقة علــى‬\n‫مالكهــا إذا كانــت باقيــة‪ ،‬فأمــا إن كانــت تالفــة‪ ،‬فعلــى الســارق رد‬\n‫قيمتهــا‪ ،‬أو مثلهــا إن كانــت مثليــة‪ ،‬قطــع أو لــم يقطــع‪ ،‬موســر ًا كان‬\n‫أو معســر ًا (‪ »)274/10‬وجــاء يف التشــريع اجلنائــي لعبدالقــادر عــودة‬\n‫«إذا كان الســارق قــد تعــاون مــع غيــره يف إخــراج الســرقة ‪ ،‬فــكل مــن‬\n‫لزمــه القطــع يف الســرقة كان مســئو ًال بالتضامــن عمــا أخــذه غيــره ممن‬\n‫وجــب عليهــم القطــع» قــال ابــن رشــد ‪« :‬إذا اجتمــع القــوم يف الغصــب أو‬\n‫الســرقة أو احلرابــة فــكل واحــد منهــم ضامــن بجميــع مــا أخــذوه‪ ،‬ألن‬\n‫بعضــا‪ ،‬كالقــوم املجتمعــن علــى قتــل رجــل فيقتلــون بــه‬     ‫بعضهــم قـ ّـوى ً‬\n‫جميعــا‪ ،‬وإن ولــي القتــل أحدهــم وحــده» و لقولــه صلــى اهلل عليــه وســلم»‬ ‫ً‬\n‫علــى اليــد مــا أخــذت حتــى تؤديــه» عليــه فقــد حكمــت علــى املدعــى‬\n‫عليهمــا بدفــع مبلــغ وقــدره خمســة وتســعني ألــف وســبعمائة وأربعــة‬\n‫وأربعــن ريــال‪ 95744‬للمدعــن أصالــة وبعــرض احلكــم علــى املدعــن‬\n‫قــرر املدعــى وكالــه القناعــة وقــرر املدعــى عليهمــا عــدم القناعــة مــع‬\n‫االكتفــاء مبــا قــدم ســابقا مــن لوائــح اعتراضيــه وجــرى النطق باحلكم‬\n‫يف يــوم األحــد املوافــق ‪1434/1/11‬ه ـ وعلــى ذلــك جــرى التوقيــع وكان‬\n‫ختــام هــذه اجللســة الســاعة (‪ )11:00‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n      ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/1/11‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...........‬القاضــي يف احملكمــة‬\n\n\n                                                                                         ‫‪148‬‬\n\f      ‫اجلزائيــة مبحافظــة جــدة ففــي يــوم األربعــاء املوافق‪1434/05/15‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة (‪ )11:00‬املتعلقــة بدعــوى ‪ .................‬ضــد‬\n      ‫‪ .................‬وفيهــا حضــر ‪ ................‬ســعودي اجلنســية مبوجــب بطاقــة‬\n      ‫الهويــة الوطنيــة رقــم ‪...........‬الوكيــل الشــرعي عــن ‪ ..............‬أصالــة عــن‬\n      ‫نفســه وبصفتــه صاحــب مؤسســة ‪..................‬التجاريــة برقــم ‪...............‬‬\n      ‫وتاريــخ ‪1433/07/14‬ه ـ املخولــة لــه املطالبــة وإقامــة الدعــاوي املرافعــة‬\n      ‫واملدافعــة ســماع الدعــاوي والــرد عليهــا اإلقــرار واإلنــكار والصلــح‬\n      ‫التنــازل طلــب اليمــن ورده واالمتنــاع عنــه وإحضــار الشــهود والبينــات‬\n      ‫ال‬\n       ‫والطعــن فيهــا الطعــن يف التزويــر تعيــن اخلبــراء واحملكمــن وقــرر قائ ً‬\n      ‫أن موكلتــي قــد تنازلــت عــن املبلــغ احملكــوم ملوكلتــي يف باطــن هــذا‬\n      ‫الصــك وقــدره خمســة وتســعون ألــف وســبعمائة وأربعــة وأربعــون ريــال‬\n      ‫‪ 95744‬ريــال وال تطالــب املدعــي عليهمــا بشــيء بخصــوص هــذه القضية‬\n      ‫وذلــك لوجــه اهلل تعالــى وبنــاء علــى ذلــك ومبــا أن وكيــل املدعــي قــرر‬\n      ‫تنــازل موكلتــه وهــو بكامــل أهليتــه املعتبــرة شــرعا و باالطــاع علــى‬\n      ‫وكالتــه وجدتهــا تخولــه حــق اإلقــرار لــذا فقــد ثبــت لــدي تنــازل وكيــل‬\n      ‫املدعيــة عــن دعواهــا جتــاه املدعــى عليهمــا ‪.........‬و‪ ...........‬بكامــل املبلــغ‬\n      ‫املدعــى بــه يف باطــن هــذا الصــك وأخليــت ســبيل املدعــى عليهمــا مــن‬\n      ‫هــذا املبلــغ املدعــى بــه يف باطــن الصــك وبهــذا تكــون القضيــة منتهيــة‬\n      ‫وأقفلــت اجللســة الســاعة ‪ 11 : 30‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n              ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/5/15‬ه ـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد فقــد‬\n      ‫جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة اخلامســة مبحكمــة االســتئناف‬\n      ‫يف منطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n\n\n‫‪149‬‬\n\f‫رئيــس احملكمــة اجلزائيــة مبحافظــة جــدة املســاعد برقــم ‪33/403935‬‬\n‫وتاريــخ ‪1434/1/28‬ه ـ املرفــق بهــا الصــك رقــم ‪ 348978‬وتاريــخ‬\n‫‪1434/1/11‬ه ـ الصــادر مــن فضيلــة الشــيخ‪ ............... /‬القاضــي‬\n‫باحملكمــة اجلزائيــة مبحافظــة جــدة املتضمــن دعــوى‪ ............ /‬وكالــة‬\n‫ضــد‪ ............ /‬مينــي اجلنســية ورفقــاه يف ســرقة جــواالت احملكــوم‬\n‫فيــه مبــا دون بباطــن الصــك ‪ ،‬وبدراســة الصــك وصــورة ضبطــه قررنــا‬\n‫املوافقــة علــى احلكــم باألكثريــة ‪ ،‬واهلل املوفــق وصلــى اهلل علــى نبينــا‬\n                                         ‫محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                  ‫‪150‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":141,"source_page_end":150,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"f1ea87e9fe15c847b78c2161d3aa33f1403b379e32c49003c497fef8d7d98880","normalized_text_hash":"027ce882eed94c2452a62cf365be4e1cad10d12040bf3a19e59dde53f1363a4c","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p141-348978"},{"id":"81f836a4-c202-59ed-8ebd-dd96a4ac7684","document_type":"judgment","category":"judicial","subcategory":"general","title":"مطالبة برد مسروق -اشتراك يف سرقة مبلغ مالي من منزل -عدم قبول الرجوع عن اإلقرار بحق آلدمي -ثبوت الدعوى -إلزام كل متهم مبا حصل عليه من املسروق .","document_number":"33368850","case_number":"33327793","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بعنيزة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/8/6","year":"1434","subject":"مطالبة برد مسروق -اشتراك يف سرقة مبلغ مالي من منزل -عدم قبول الرجوع عن اإلقرار بحق آلدمي -ثبوت الدعوى -إلزام كل متهم مبا حصل عليه من املسروق .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫تاريخه‪1433/8/6 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪33368850 :‬‬\n                          ‫َر ْق ُم الدعوى‪33327793:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                   ‫‪ 3453803‬تاريخه‪1434/3/2:‬هـ‬\n\n\n      ‫مطالبــة بــرد مســروق ‪ -‬اشــتراك يف ســرقة مبلــغ مالــي مــن منــزل ‪ -‬عــدم‬\n      ‫قبــول الرجــوع عــن اإلقــرار بحــق آلدمــي ‪ -‬ثبــوت الدعــوى ‪ -‬إلــزام كل‬\n                                        ‫متهــم مبــا حصــل عليــه مــن املســروق ‪.‬‬\n\n\n\n                        ‫‪ -1‬اإلنسان مؤاخذ بإقراره والسيما يف حق اآلدميني‪.‬‬\n      ‫‪ -2‬شــهادة الفســاق تقبــل علــى بعضهــم إذا لــم يدفــع الواحــد منهــم عــن‬\n                                ‫نفســه ضــررا ‪ ،‬كمــا ذكــره بعــض أهــل العلــم ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي بــأن املدعــى عليهــم اشــتركوا يف ســرقة مبلــغ مالــي مــن‬\n      ‫منزلــه وأنــه أعيــد لــه جــزء منــه؛ وطلــب إلزامهــم بإعــادة باقي املبلــغ املالي‬\n      ‫املســروق ‪ -‬أنكــر املدعــى عليهــم دعــوى املدعــي‪ -‬اطلعــت احملكمــة‬\n      ‫علــى حكــم صــادر منهــا بإدانــة املدعــى عليهــم يف الســرقة املذكــورة‬\n      ‫كمــا اطلعــت علــى إقراراتهــم باالشــتراك يف الســرقة ‪ -‬مــن املقــرر‬\n      ‫شــرعا أن الرجــوع عــن اإلقــرار يف حقــوق اآلدميــن غيــر مقبــول ‪ -‬لذلــك‬\n      ‫قضــت احملكمــة بإلــزام كل واحــد مــن املدعــى عليهــم بتســليم املبلــغ‬\n      ‫الــذي حتصــل عليــه مــن الســرقة إلــى املدعــي ‪ -‬قنــع املدعــي واملدعــى‬\n      ‫عليــه األول باحلكــم وعــارض عليــه املدعــى عليهمــا الثانــي والثالــث ‪-‬‬\n             ‫قــررت محكمــة االســتئناف باألكثريــة املصادقــة علــى احلكــم‪.‬‬\n‫‪151‬‬\n\f‫احلمــد هلل وحــده وبعــد يف يــوم الثالثــاء املوافــق ‪1433/5/25‬ه ـ لــدي‬\n‫أنــا ‪ ...‬القاضــي باحملكمــة العامــة بعنيــزة افتتحــت اجللســة يف الســاعة‬\n‫الثامنــة صباحــا للنظــر يف الدعــوى املقامــة مــن املقيــدة بهــذه احملكمــة‬\n‫برقــم ‪ 33887521‬يف ‪1433/5/11‬ه ـ احملالــة لنــا بشــرح فضيلة الرئيس‬\n‫وقــد حضــر يف هــذه اجللســة ‪ .......‬اجلنســية باإلقامــة رقــم وادعــى علــى‬\n‫احلاضريــن يف هــذه اجللســة األول ‪ /‬ســعودي اجلنســية مبوجــب ســجل رقــم‬\n‫والثانــي ‪ /‬ســعودي مبوجــب ســجل رقــم والثالــث ‪ /‬ســعودي مبوجــب‬\n‫ســجل رقــم قائــا يف حتريــر دعــواه لقــد قــام املدعــي عليهــم بســرقة‬\n‫مبلغــا مــن منزلــي الواقــع يف حــي متــروك بعنيــزة قــدره ثالثمائــة وثمانيــة‬\n‫االف ريــال قبــل ســنة تقريبــا وحكــم عليهــم بإثبــات إدانتهــم وصــدر قرار‬\n‫بذلــك مكتســب للقطعيــة ثــم ســلمت مبلغــا قــدره خمســة االف ريــال عــن‬\n‫طريــق شــرطة عنيــزة وأخبرونــي انــه جــزء مــن هــذا املبلــغ املدعــي بــه‬\n‫وذلــك قبــل عشــرين يــوم تقريبــا لــذا فإننــي اطلــب إلــزام املدعــي عليهــم‬\n‫بإعــادة املبلــغ املتبقــي مــن املبلــغ الذي ســرقوه مني وقــدره ثالثمائة وثالثة‬\n‫االف ريــال هــذه دعــواي وبســؤال املدعــي عليهــم عمــا جــاء يف دعــوى‬\n‫املدعــي أجــاب كل واحــد منهــم مبفــرده قائــا مــا ذكــره املدعــي كلــه‬\n‫غيــر صحيــح وجــرى منــي ســؤال املدعــي هــل لديــه بينــة علــى إقــرارات‬\n‫املدعــي عليهــم فأجــاب بقولــه أطلــب الرجــوع إلــى املعاملــة االساســية‬\n‫وإحضارهــا وفيهــا اإلقــرارات وجــرى منــي االطــاع علــى دفتــر التحقيــق‬\n‫مــن املعاملــة االساســية ومت االطــاع علــى إقــرارات املدعــي عليهــم فهــي‬\n‫كالتالــي إقــرار يف لفــة رقــم ‪ 39‬وفيــه مــا نصــه نعــم أنــا أقــر واعتــرف‬\n\n                                                                                     ‫‪152‬‬\n\f      ‫بأنــي قمــت بســرقة منــزل داخــل حــي البحيــرة وهــو بيــت‪ /‬مينــي اجلنســية‬\n      ‫صاحــب محــات وكان معــي كال مــن ‪ /‬و ‪ /‬كان دوري يف الســرقة‬\n      ‫املراقبــة خــارج املنــزل وإلهــاء مــن يأتــي ورمــي حجــر داخــل املنــزل وقــام‬\n      ‫بدخــول املنــزل كل مــن األول والثانــي وبعــد دخــول املنــزل بنصــف ســاعة‬\n      ‫خرجــوا مــن اجلهــة الثانيــة مــن املنــزل مــن فــوق الســور وكان معهــم مبالــغ‬\n      ‫ماليــه وقــام بإعطائــي مبلــغ مالــي وقــدره عشــرة االف ريــال فذهبــت إلــى‬\n      ‫املنــزل وحــدي وذهبــوا إلــى مــكان آخــر ال أعلــم أيــن وبعدهــا قامــوا‬\n      ‫بإقفــال جوالتهــم وهــذا هــو إقــرار منــي وعليــه أوقــع علمــا أنــه باقــي‬\n      ‫مــن املبلــغ خمســة االف ريــال ومت االطــاع علــى إقــرار يف لفــة رقــم ‪3‬‬\n      ‫وفيــه مــا نصــه أقــر أنــا ‪ /‬ســعودي اجلنســية أنــه قبــل فتــرة ال أذكــر‬\n      ‫بــأي يــوم وال أي تاريــخ ولكــن كنــت نائمــا يف منــزل والدتــي حضــر‬\n      ‫إلــى املدعــو ‪ /‬ومعــه املدعــو ‪ /‬ودخلــوا علــي وأنــا نائــم وصحونــي مــن‬\n      ‫النــوم ورجعــت وقلــت ألهلــي ســوف نذهــب لالســتراحة وبعــد خروجنــا‬\n      ‫نحــن الثالثــة واجتهنــا إلــى منــزل املدعــو ‪ /‬لقصــد الســرقة وقــام بالقفــز‬\n      ‫مــن الســور األمامــي للمنــزل ودخــل وبقيــت أنــا أراقــب يف أول الشــارع‬\n      ‫واملدعــو يف آخــر الشــارع وبعــد نصــف ســاعة جــاء ومعــه مبلــغ يف بطنــه‬\n      ‫وأخــرج مبلــغ وأعطانــي عشــرون الــف ريــال وإعطــاء املدعــو ‪ /‬ال أعــرف‬\n      ‫كــم وبعدهــا تفرقنــا وذهبــت ووضعــت يف املنــزل عنــد شــبك احلمــام يف‬\n      ‫البلــك وموجــود االن وبعدهــا ذهــب املدعــو‪ /‬مــع املدعــو ‪ /‬إلــى منــزل‬\n      ‫ولــد خالتــه وأعطــى املدعــو الــف ريــال والباقــي املبلــغ معــه هــذا إقــراري‬\n      ‫وعليــه أصــادق ومت االطــاع علــى إقــرار يف لفــة رقــم ‪ 9‬وفيــه مــا نصــه‬\n      ‫أقــر أنــا بأننــي أنــا وحيــث قــام ‪ /‬بدخــول منــزل ‪ /‬ومعــه ‪ /‬عــن طريــق‬\n      ‫الســور وســمعت صــوت كســر بــاب وبعــد نصــف ســاعة خرجــوا ومعهــم‬\n\n\n‫‪153‬‬\n\f‫مبالــغ ال أعلــم كــم ولكــن أعطانــي عشــرة االف ريــال وذهبــوا هــذا‬\n‫إقــراري وعليــه أصــادق فبنــاء علــى مــا تقــدم وحيــث طلــب املدعــي إلــزام‬\n‫املدعــي عليهــم بدفــع املبلــغ املدعــي بــه وحيــث أنكــر املدعــي عليهــم‬\n‫دعــوى املدعــي العــام وحيــث أنــه يوجــد إقــرار علــى املدعــى عليهــم‬\n‫بســرقة املبلــغ مــن بيــت املدعــي وحيــث أن اإلنســان مؤاخــذ بإقــراره‬\n‫والســيما يف حــق اآلدميــن حيــث أنــه ال يســقط حــق املدعــي بعــد إقــرار‬\n‫املدعــي عليهــم بالســرقة وحيــث أقــر املدعــي عليهــم أنــه اســتلم مــن ‪/‬‬\n‫مبلغــا وقــدره عشــرة االف ريــال وأعــاد أحــد أخوتــه خمســة االف ريــال‬\n‫وحيــث أقــر املدعــي عليــه ‪ /‬أنــه اســتلم مبلغــا وقــدره عشــرون الــف ريــال‬\n‫وحيــث أن املدعــي عليهــم ‪ /‬و ‪ /‬شــهد ‪ /‬بــأن مــن قــام بالقفــز وأخــذ املبلــغ‬\n‫هــو املدعــي عليــه ‪ /‬وحيــث أن شــهادة الفســاق تقبــل علــى بعضهــم كمــا‬\n‫ذكــره بعــض أهــل العلــم لذلــك كلــه فقــد حكمــت أوال بــأن يدفــع‬\n‫املدعــي عليــه ‪ /‬مبلغــا وقــدره خمســة االف ريــال وثانيــا حكمــت بــأن‬\n‫يدفــع املدعــي عليــه مبلغــا وقــدره عشــرون الــف ريــال وثالثــا حكمــت‬\n‫بــأن يدفــع املدعــي عليــه ‪ /‬مبلغــا وقــدره مائتــان وثمــان ســبعون ألــف ريــال‬\n‫هــذا مــا ظهــر لــي وبعرضــه عليهمــا قــرر املدعــي القناعــة وقــرر املدعــي‬\n‫عليــه ‪ /‬القناعــة وقــررا املدعــى عليهــم ‪ /‬وعــدم ‪ /‬القناعــة وأفهمــوا بــأن‬\n‫لهــم ثالثــون يومــا مــن تاريــخ صــدور الصــك لتقــدمي الئحــة اعتراضيــة‬\n‫وإال اكتســب احلكــم القطعيــة ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1433/7/30‬ه ويف يــوم‬\n‫االثنــن املوافــق ‪1434/02/04‬ه ـ افتتحــت اجللســة الســاعة ‪12:00:00‬‬\n‫وفيهــا عــادت املعاملــة مــن محكمــة االســتئناف بالقصيــم وبرفقتهــا‬\n‫القــرار رقــم ‪33471023‬يف ‪1433/11/30‬ه ـ الصــادر مــن قضاة الدائرة‬\n\n\n                                                                                       ‫‪154‬‬\n\f      ‫الثانيــة لتدقيــق القضايــا اجلزائيــة واملتضمــن املالحظــة علــى احلكــم‬\n      ‫الصــادر منــي مبــا يلــي أن فضيلتــه حكــم علــى املدعــى عليــه بــأن يدفــع‬\n      ‫للمدعــي املبلــغ املذكــور ولــم يذكــر مســتنده علــى مقــدار املبلــغ الــذي‬\n      ‫حكــم بــه كمــا أن مــا أشــار إليــه فضيلتــه مــن قبــول شــهادة الفســاق‬\n      ‫مخصــوص مبــا إذا لــم يدفــع عــن نفســه ضــررا كمــا يف هــذه القضيــة‬\n      ‫وإذا توجــه احلكــم علــى املدعــي عليهــم باملبلــغ فإنــه يلزمهــم متضامنــن‬\n      ‫إذا ثبــت اشــتراكهم بالســرقة مــع تنبيــه فضيلتــه إلــى إحلــاق مــا يــدل‬\n      ‫علــى أن املدعــي عليــه قــد قنــع باحلكــم وســدد املبلــغ احملكــوم بــه‬\n      ‫عليــه بالصــك وعليــه أجيــب أصحــاب الفضيلــة عــن املالحظــة االولــى أن‬\n      ‫املدعــي عليــه أقــر علــى نفســه بســرقة املــال ووضعــه معــه عنــد الســرقة ثم‬\n      ‫قــام بتوزيــع املــال علــى أصحابــه وبقــى املبلــغ الــذي حكــم عليــه بــه حتــت‬\n      ‫يــده لــذا فإنــه ملــزم بإعــادة مــا كان حتــت يــده مــن املــال املســروق وأمــا‬\n      ‫قبــول شــهادة بعضهــم علــى بعــض فإنــه يعضدهــا اعتــراف املدعــي عليــه‬\n      ‫بأنــه هــو مــن قــام بالســرقة وهــو مــن قــام بتوزيــع املــال علــى بقيــة رفقــاه‬\n      ‫فيكــون ملــزم بإعــادة املبلــغ الــذي اعتــرف أنــه بحوزتــه وأمــا إلزامهــم‬\n      ‫متضامنــن فــا وجــه لــه حيــث أن املدعــي عليــه ‪ .....‬هــو مــن قــام بالقفــز‬\n      ‫وتوزيــع املــال وحيــازة املبلــغ األكبــر الــذي حكمــت بــه عليــه وأمــا ‪.....‬‬\n      ‫فإنــه علــى صحيفــة خمســة وأربعــن مــن مجلــد الضبــط الثانــي عشــر‬\n      ‫اجلنائــي قــرر قناعتــه باحلكــم وســلم للمدعــى مبلغــا وقــدره عشــرون الف‬\n      ‫ريــال مبوجــب شــيك املســحوب علــى بنــك ‪ .....‬لــذا فإنــي مــا زلــت علــى‬\n      ‫حكمــي الســابق وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n      ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/2/4‬ه احلمــد هلل وحــده وبعــد فلــدي‬\n      ‫أنــا القاضــي يف احملكمــة العامــة بعنيــزة وبنــاء علــى املعاملــة احملالــة‬\n\n\n‫‪155‬‬\n\f‫لنــا مــن فضيلــة رئيــس احملكمــة العامــة بعنيــزة برقــم ‪33327793‬‬\n‫وتاريــخ ‪1433/05/11‬ه ـ املقيــدة باحملكمــة برقــم ‪ 33887521‬وتاريــخ‬\n‫‪ 1433/05/10‬ه ـ ففــي يــوم الســبت املوافــق‪ 1434/03/21‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 10:15:00‬وفيهــا عــادت املعاملــة مــن محكمــة‬\n‫االســتئناف بالقصيــم وبرفقتهــا قــرار التصديــق رقــم ‪ 3453803‬يف‬\n‫‪1434/3/2‬ه ـ الصــادر مــن قضــاة الدائــرة الثانيــة لتدقيــق القضايــا‬\n‫اجلزائيــة قــاض اســتئناف ختمــه وتوقيعــه وقــاض اســتئناف ختمــه‬\n‫وتوقيعــه ولــه وجهــة نظــر ورئيــس الدائــرة ختمــه وتوقيعــه وبــاهلل التوفيــق‬\n‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                               ‫‪1434/3/21‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                     ‫‪156‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":151,"source_page_end":156,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"9eaf435c386ba998b707def713f5fad73b893b0f32abcb07ebacf357902523bc","normalized_text_hash":"4e746bab8f61d840cd84363e5b492c89803043b4b9e89fa05e7cd14ce4053a83","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p151-33368850"},{"id":"f5a8b0f2-29fc-582f-a24a-bd112042cf82","document_type":"judgment","category":"judicial","subcategory":"general","title":"رد مسروق -سرقة مبلغ مالي من سيارة -إقرار أحد املدعى عليهم في ر د مثله إن عجز عن رد وإنكار البقية -املسروق إذا كان مثليا عينه -احلكم برد باقي املبلغ املسروق بعد خصم ما مت رده.","document_number":"34201455","case_number":"33386410","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/29","year":"1434","subject":"رد مسروق -سرقة مبلغ مالي من سيارة -إقرار أحد املدعى عليهم في ر د مثله إن عجز عن رد وإنكار البقية -املسروق إذا كان مثليا عينه -احلكم برد باقي املبلغ املسروق بعد خصم ما مت رده.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/4/29 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34201455 :‬‬\n                          ‫َر ْق ُم الدعوى‪33386410:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34253709‬تاريخه‪1434/6/27:‬هـ‬\n\n\n      ‫رد مســروق ‪ -‬ســرقة مبلــغ مالــي مــن ســيارة ‪ -‬إقــرار أحــد املدعــى عليهــم‬\n      ‫فيـ َـر ُّد مثلــه إن عجــز عــن رد‬\n                                       ‫وإنــكار البقيــة ‪ -‬املســروق إذا كان مثليــا ُ‬\n             ‫عينــه ‪ -‬احلكــم بــرد باقــي املبلــغ املســروق بعــد خصــم مــا مت رده‪.‬‬\n\n\n\n\n      ‫قــول النبــي صلــى اهلل عليــه وســلم‪( :‬لــو يعطــى النــاس بدعواهــم الدعــى‬\n               ‫نــاس دمــاء رجــال وأموالهــم ولكــن اليمــن علــى املدعــى عليــه) ‪.‬‬\n\n\n\n\n      ‫ادعــى وكيــل املدعــي علــى احلاضريــن معــه بــأن املدعــى عليهمــا األول‬\n      ‫والثامنــة قامــا بســرقة مبالــغ ماليــة مــن ســيارة موكلــه َّإبــان عملهمــا‬\n      ‫لديــه كســائق وخادمــة‪ ،‬ثــم قــام األول باقتســام تلــك املبالــغ مــع بقيــة‬\n      ‫املدعــى عليهــم‪ ،‬وبعــد القبــض عليهــم أعــادوا قيمــة جــزء منهــا للمدعــي‪،‬‬\n      ‫ولــذا فقــد طلــب إلزامهــم بإعــادة باقــي املبالــغ التــي ســرقت مــن موكله‪-‬‬\n      ‫أقــر األول بجميــع مــا جــاء يف دعــوى املدعــي جتاهــه وذكــر أنــه تصــرف‬\n      ‫بباقــي املبالــغ محــل الدعــوى‪ ،‬وأنكــر باقــي املدعــى عليهــم مــا جــاء يف‬\n      ‫الدعــوى إال أنهــم أقــروا ســوى الثامنــة باســتالم مبالــغ ماليــة مــن األول‪،‬‬\n      ‫ودفعــوا بأنهــم أعــادوا قيمتهــا للمدعــي‪ -‬املدعــي لــم يقــدم بينــة تثبــت‬\n      ‫دعــواه جتــاه املدعــى عليهــم وطلــب ميينهــم ‪ -‬عــدا األول‪ -‬علــى نفــي دعــواه‬\n‫‪157‬‬\n\f‫فأدوهــا طبــق مــا طلــب منهــم ‪ -‬قضــت احملكمــة بنــاء علــى إقــرار األول‬\n‫بإلزامــه بإعــادة مثــل املبلــغ الــذي ســرقه مــن املدعــي بعــد خصــم قيمــة‬\n‫اجلــزء الــذي ســبق أن أعــاده إليــه مــن املبلــغ اإلجمالــي‪ ،‬كمــا قضــت‬\n‫بصــرف النظــر عــن دعــوى املدعــي جتــاه بقيــة املدعــى عليهــم ‪ -‬قنــع‬\n‫املدعــي واملدعــى عليهــم باحلكــم عــدا األول فقــد عــارض عليــه ‪ -‬قــررت‬\n               ‫محكمــة االســتئناف املوافقــة علــى احلكــم باألكثريــة ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالرياض‪/‬املســاعد برقــم ‪ 33386410‬وتاريــخ ‪ 1433/06/08‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 331039024‬وتاريــخ ‪ 1433/06/03‬ه ـ ففــي‬\n‫يــوم الثالثــاء املوافــق‪ 1434/03/17‬ه ـ افتتحــت اجللســة الســاعة ‪11 : 15‬‬\n‫وفيهــا حضــر‪ ...../‬ســعودي مبوجــب الســجل املدنــي رقــم‪ )....( :‬بالوكالة‬\n‫عــن‪..... /‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‪ ).....(:‬مبوجــب‬\n‫الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة بجنــوب الريــاض برقــم‪:‬‬\n‫(‪ )3364510‬وتاريــخ ‪1433/5/3‬هـ ـ والتــي تخولــه املطالبــة واملرافعــة‬\n‫واملدافعــة واإلقــرار واإلنــكار والصلــح‪ ،‬كمــا حضــر حلضــوره ‪..... /1‬‬\n‫ســريالنكي هويــة رقــم‪...... /2 .).....( :‬ســريالنكي هويــة رقــم‪).....( :‬‬\n‫‪....... /3‬ســريالنكي هويــة رقــم‪...... /4 ).....( :‬ســريالنكي هويــة‬\n‫رقــم‪ ......./5 ،)....( :‬ســريالنكي (يحمــل بطاقــة نزيــل محكــوم‬\n‫رقــم‪ )..../../ ...:‬صــادرة مــن ســجن امللــز‪ ..../6 .‬ســريالنكي (يحمــل‬\n‫بطاقــة نزيــل محكــوم رقــم‪ ).../.../..:‬صــادرة مــن ســجن امللــز‪...... /7 .‬‬\n                                                                                   ‫‪158‬‬\n\f      ‫ســريالنكي هويــة رقــم‪..... /8 .).....( :‬ســريالنكية اجلنســية مبوجــب‬\n      ‫الهويــة رقــم‪ ).....( :‬واملعــرف بهــا مــن قبــل الســجانة حاملــة الســجل املدنــي‬\n      ‫رقــم‪ ،).....( :‬كمــا حضــر حلضورهــم املترجم املتعاون‪..... /‬ســريالنكي‬\n      ‫اجلنســية مبوجــب رخصــة اإلقامــة رقــم‪ ،).....( :‬وادعــى املدعــي وكالــة‬\n      ‫قائــا يف دعــواه‪ :‬إن املدعــى عليــه‪ ، .....‬واملدعــى عليهــا ‪ ...‬يعمــان‬\n      ‫لــدى موكلــي يف منزلــه ســائق وخادمــة‪ ،‬ويف تاريــخ ‪1432/3/23‬هـ ـ‬\n      ‫قامــا بالســرقة مــن موكلــي خمســة وخمســن ألــف جنيــه إســترليني‪،‬‬\n      ‫وخمســن ألــف يــورو‪ ،‬وذلــك مــن ســيارته ثــم قــام املدعــى عليــه بتوزيــع‬\n      ‫املبلــغ املســروق علــى زمالئــه املدعــى عليهــم البقيــة‪ ،‬وقــد أعــادوا مائــة‬\n      ‫ألــف ريــال ســعودي مــن املبلــغ املســروق وإننــي أطلــب يف دعــواي هــذه‬\n      ‫ســؤال املدعــى عليهــم وإلزامهــم بإعــادة املتبقــي مــن املبلــغ‪ ،‬والــذي يقــدر‬\n      ‫مببلــغ أربعمائــة ألــف ريــال ســعودي‪ ،‬هــذه دعــواي‪ .‬وبســؤال املدعــى‬\n      ‫عليهــم بواســطة املترجــم املذكــور أجــاب املدعــى عليــه‪ /‬بــأن كل مــا‬\n      ‫ذكــره املدعــي وكالــة يف دعــواه صحيــح فقــد ســرقت املبلــغ املذكــور‬\n      ‫بوحــدي وزوجتــي املدعــى عليهــا‪ /‬ال عالقــة لهــا بذلــك‪ ،‬وبعــد ســرقتي‬\n      ‫للمبلــغ ســلمت مــا يقــدر مبائــة ألــف للمدعــى عليــه ‪ ،‬والــذي قــام بتوزيــع‬\n      ‫املبلــغ علــى بقيــة املدعــى عليهــم احلاضريــن معــي يف مجلــس احلكــم‪،‬‬\n      ‫وأمــا املبلــغ املتبقــي والــذي يقــدر بأربعمائــة ألــف ريــال فســلمته لشــخص‬\n      ‫اســمه ‪ ،...‬وقــد ســافر يف نفــس اليــوم خــارج اململكــة‪ ،‬واملدعــى عليهــم‬\n      ‫احلاضريــن معــي قامــوا بإعــادة مــا اســتلموه‪ ،‬وهــو مائــة ألــف ريــال‪،‬‬\n      ‫واســتلمها املدعــي مــن الشــرطة‪ ،‬هــذا مــا لــدي‪ ،‬وأجــاب بقيــة املدعــى‬\n      ‫عليهــم عــدا املدعــى عليهــا بــأن مــا جــاء يف دعــوى املدعــي وكالــة غيــر‬\n      ‫صحيــح فلــم نســرق أي مبلــغ والصحيــح أن املدعــى عليــه‪ /‬اســتلم مــن‬\n\n\n‫‪159‬‬\n\f‫املدعــى عليــه مائــة ألــف ريــال ســعودي وقــام بتوزيعهــا علينــا وعنــد مــا‬\n‫قبــض علينــا قمنــا بإعادتهــا‪ ،‬هــذا مــا لدينــا‪ .‬وقالــت املدعــى عليهــا‬\n‫بواســطة املترجــم إن كل مــا ذكــره املدعــي وكالــة غيــر صحيــح‪،‬‬\n‫فأنــا لــم أســرق وال عالقــة لــي بذلــك‪ ،‬هــذا مــا لــدي‪ .‬وبعــرض ذلــك علــى‬\n‫املدعــي وكالــة قــال‪ :‬الصحيــح مــا ذكــرت يف دعــواي‪ ،‬وبســؤاله هــل‬\n‫لديــه بينــة علــى مــا ادعــى بــه مــن قيــام بقيــة املدعــى عليهــم عــدا األول‬\n‫باملشــاركة يف الســرقة‪ ،‬فقــال‪ :‬ليــس لــدي بينــة‪ ،‬ولكــن أطلــب ميينهــم‬\n‫علــى نفــي ذلــك وبعــرض ذلــك علــى املدعــى عليهــم عــدا األول اســتعدوا‬\n‫بــأداء اليمــن‪ ،‬وحلــف كل واحــد منهــم مبفــرده قائــا‪( :‬واهلل العظيــم‬\n‫أننــي لــم أشــارك املدعــى عليــه األول يف ســرقة املدعــي أصالــة‪ ،‬ولــم‬\n‫أســرق املبالــغ املدعــى بهــا وأن املدعــى عليــه هــو الــذي أعطانــي مبلــغ‬\n‫مائــة ألــف ريــال)‪ ،‬وبنــاء عليــه فقــد قــررت الكتابــة إلــى مؤسســة النقــد‬\n‫العربــي لتقديــر قيمــة املبلــغ املســلم للمدعــي مــن املبلــغ املســروق‪ ،‬وبــه‬\n‫رفعــت اجللســة‪ ،‬ويف جلســة أخــرى حضــر املدعــي وكالــه واملدعــى‬\n‫عليهــم جميعــا ولــم يحضــر املترجــم رغــم طلبــه وكان قــد جــرى منــا‬\n‫الكتابــة إلــى مؤسســة النقــد الســعودي باخلطــاب رقــم ‪34682630‬‬\n‫يف ‪1434/3/2‬ه ـ لتقديــر ‪ -1‬قيمــة املبلــغ خمســة وخمســن ألــف جنيــة‬\n‫إســترليني ‪ -2‬قيمــة مبلــغ خمســن ألــف يــورو وقــد وردنــا خطابهــم رقــم‬\n‫‪ 341000041129‬يف ‪1434/4/2‬ه ـ املتضمــن نفيدكــم بــأن قيمــة كل‬\n‫من ‪ -1 :‬مبلغ ‪ 55000‬جنية إســترليني تســاوي ‪ 322965/50‬ريال بســعر‬\n‫‪ 5.8721‬ريــال ســعودي‪ -2 .‬مبلــغ ‪ 50000‬ألــف يــورو تســاوي ‪254680/-‬‬\n‫ريــال بســعر ‪ 5.0936‬ريــال ســعودي ‪.‬أ‪.‬ه ـ ‪ ،‬ولعــدم حضــور املترجــم‬\n‫قــررت رفــع اجللســة ويف جلســة أخــرى حضــر املدعــي وكالــة‪..... /‬‬\n\n\n                                                                                       ‫‪160‬‬\n\f      ‫املدونــة هويتــه ووكالتــه ســابقا‪ ،‬كمــا حضــر املدعــى عليهــم جميعــا‪،‬‬\n      ‫وحضــره حلضورهــم املترجــم املتعــاون املدونــة هويتــه ســابقا‪ ،‬واملترجــم‬\n      ‫‪ .....‬ســريالنكي اجلنســية مبوجــب رخصــة اإلقامــة رقــم‪ ، ).....(:‬وبعرض‬\n      ‫مــا جــاء يف خطــاب مؤسســة النقــد العربــي الســعودي علــى املدعــى‬\n      ‫عليــه‪ ، /‬قــال‪ :‬إننــي ال أعلــم عــن تقديــر قيمــة اليــورو واالســترليني‪،‬‬\n      ‫هــذا مــا لــدي‪ .‬وبنــاء علــى مــا ســبق مــن الدعــوى واإلجابــة‪ ،‬ولقولــه صلــى‬\n      ‫اهلل عليــه وســلم (لــو يعطــى النــاس بدعواهــم الدعــى نــاس دمــاء رجــال‬\n      ‫وأموالهــم ولكــن اليمــن علــى املدعــى عليــه) ومبــا أن املدعــى عليــه ‪/‬‬\n      ‫‪.....‬قــد أقــر يف جوابــه بســرقة املبالــغ املدعــى بهــا‪ ،‬ومبــا أن بقيــة املدعــى‬\n      ‫عليهــم عــدا املدعــى عليهــا ‪ ...‬أنكــروا الســرقة ودفعــوا بتســليم مــا ســلم‬\n      ‫لهــم مــن أمــوال‪ ،‬وقدرهــا مئــة ألــف ريــال وقــد صــادق املدعــي وكالــة‬\n      ‫علــى مــا ذكــروه مــن تســليم املبلــغ املذكــور ومبــا أن املدعــى عليهــا‪/‬‬\n      ‫‪.....‬أنكــرت مــا جــاء يف الدعــوى‪ ،‬وقــررا املدعــي وكالــة عــدم وجــود‬\n      ‫بينــة لديــه‪ ،‬وطلــب ميــن بقيــة املدعــى عليهــم‪ ،‬ومبــا أن املدعــى عليهــم‬\n      ‫عــدا قــد أدوا اليمــن الشــرعية‪ ،‬علــى نفــي قيامهــم بالســرقة ومبــا أن‬\n      ‫املبلــغ املســلم للمدعــي‪ ،‬والــذي قــدره مئــة ألــف ريــال ســعودي يســاوي‬\n      ‫بالتقديــر املذكــور ســتة عشــر الــف وثمامنائــة وســتة وأربعــن يــورو وســتة‬\n      ‫وثالثــن باملئــة منــه لذلــك كلــه فقــد حكمــت علــى املدعــى عليــه بــأن‬\n      ‫يســلم للمدعــي خمســة وخمســن ألــف جنيــه اســترليني وثالثــة وثالثــن‬\n      ‫ألــف ومائــة وثالثــة وخمســن يــورو وثالثــة وســتني باملائــة مــن اليــورو‬\n      ‫وصرفــت النظــر عــن دعــوى املدعــي وكالــة جتــاه بقيــة املدعــى عليهــم‬\n      ‫وبــه حكمــت وبعــرض احلكــم عليهــم قــرر املدعــي وكالــة واملدعــى‬\n      ‫عليهــم عــدا القناعــة باحلكــم‪ ،‬أمــا املدعــى عليــه‪ ... /‬فقرر عــدم القناعة‬\n\n\n‫‪161‬‬\n\f‫باحلكــم‪ ،‬وطلــب رفــع معاملتــه إلــى محكمــة االســتئناف فأجبتــه إلــى‬\n‫طلبــه‪ ،‬وقــررت بعثهــا إلــى محكمــة االســتئناف‪ ،‬وأفهمتــه بأنــه ســوف‬\n‫يســلم صــورة مــن نســخة احلكــم يوم األربعاء املوافــق ‪1434/5/1‬ه ـ ـ وأن‬\n‫لــه مهلــة ثالثــن يومــا مــن تاريــخ االســتالم‪ ،‬لتقــدمي الئحتــه االعتراضيــة‬\n‫فــإذا انتهــت املهلــة ولــم يتقــدم بالئحتــه ســقط حقــه يف االعتــراض‪،‬‬\n‫وأصبــح احلكــم نافــذا‪ ،‬وبــه ختمــت اجللســة الســاعة‪ 30:12‬وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                ‫حــرر يف ‪ 1434/04/29‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء املوافــق‪ 1434/07/12‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 12:15‬وقــد عــادت املعاملــة مــن محكمــة‬\n‫االســتئناف باخلطــاب رقــم ‪ 341360101‬يف ‪1434/7/8‬ه ـ وبرفقهــا‬\n‫القــرار الصــادر مــن الدائــرة الثانيــة لتمييــز القضايــا اجلزائيــة يف‬\n‫محكمــة االســتئناف رقــم ‪ 34253709‬يف ‪1434/6/27‬ه ـ واملتضمــن‬\n‫وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة واوراق املعاملــة‬\n‫قررنــا باألكثريــة املصادقــة علــى احلكــم واهلل املوفق اه ـ ‪ ،‬وعليه جرى‬\n‫التهميــش مبوجبــه ‪ ،‬وبــه ختمــت اجللســة يف متــام الســاعة ‪ 12:20‬وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                 ‫حــرر يف ‪1434/7/12‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                     ‫‪162‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":157,"source_page_end":162,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"0a1c789a0eefa1dbc31f2f111794c42d7b78fec04e958bb551cbae55c009aeec","normalized_text_hash":"c95c0706affebd17f2058f0061b78bbf4e24c13d0e7a9a681a92534d0bceef05","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p157-34201455"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS document_files
